/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170123-6","meetingId":"h29-cm01","date":"2017年1月23日","dateIso":"2017-01-23","committee":"区民委員会","time":"午後 １時００分～午後 ２時２０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)荏原第四区民集会所の休館","agenda":"はじめに、(1)荏原第四区民集会所の休館","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"非常に老朽化しているので、本当にありがたいことなのですけれども、何点かお伺いしたいのが、３４年間という、この大規模改修は、耐震とかそういうものも含めた大規模改修なのかどうなのかということと、ちょっとすみません、確認なのですけれども、あそこは講習室が、多分借りて、利用率がどれぐらいかということは僕はわからないので、どんな感じなのか、そこを利用している人たちは。","respondent":"伊崎地域活動課長","answer":"工事ですけれども、耐震の対応はもうしておりますけれども、今回ももちろん耐震を配慮した工事とすることとなっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どこが幾らかというと、バラバラに設定されていてわからないのですが、例えば違うところへ行ったら高くなってしまったとなると、その部分で、あまり嫌らしいことは質問をしたくないのですけれども、例えば差額が出た場合に、その差額を、今まで、会の運営でいろいろ借りていると思うので、それもご負担になってしまうとあれなので、もし差額が出て、安ければいいのかもしれないですけれども。","respondent":"伊崎地域活動課長","answer":"ご案内につきましては、よくお話をお伺いしながら、そのご利用者の団体に適切なところをご案内できればと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"３つ目なのですけれども、大規模改修の内容については、予算も伴うという話ですけれども、ただ、改修が終わった後、できたものがどういう形になるのかというのは、利用団体にとってとても関心のあるところで、今で言うと、第１集会室、第２集会室、和室と３つあって、第１と第２がパーティションで仕切られている、こういう形が現状だと思うのですけれども、広さとか形とか、その形状というのでしょうか。","respondent":"石田（し）委員長、伊崎地域活動課長","answer":"答えられる範囲でお願いします。改修後につきましては、先ほど申し上げたとおり、来年度予算で工事費を計上する予定ですので、その改修の予算の成立後に、またどういった形になるかはご説明を差し上げたいと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"改修後のことは改めて報告をいただけるということで、地域から上がっている要望だけお伝えしたいと思うのですけれども、まずは、改修後どうなるのかというのは、利用団体にとってはとても気になるところだと思いますので、そこも含めた周知をお願いしたいというのが前提なのですけれども、確かに私もたびたび区民集会所は利用するのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"私も改修工事のことは予算後ということはわかっているのですけれども、要望として、今もお話に出ていたとおり、障害のある方たちの使いやすいトイレだったりとか、使いやすい環境であることと、あと、子ども連れ、お子さんが一緒に入れるトイレだったり、あと、男性トイレにもおむつ替えのところがほしいなど、そういう声が、今は女子トイレにもないのですけれども、そういうこともあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"開館以来３４年ということで、この施設が老朽化しているということで、大規模改修という形、ここを選んでしていただけるというのは、改修するのはよくわかったのですけれども、改めてお伺いしたいのは、３４年で老朽化という意味で言うならば、品川区の区民集会所という形で言うならば、老朽化している、そして大規模改修しなくてはいけないと現時点て考えている施設は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"そういう答弁だと伺わなくてはならないのですけれども、今回は３４年間で老朽化していることからと、やはり年数も関係あると思うのですけれども、その前はどこで老朽化していないと判断したのかということもありますし、大体３４年と、４年という意味でやっているけれども、３０年ぐらいとか、そういう意味においては、ほかにも老朽化しているところがあると思うので、徐々にやっていきますとか。","respondent":"伊崎地域活動課長","answer":"今、地域センターの区民集会室のみのお話として申し上げたところですが、区の施設全体として、どのような形で見直しをしていくかということは、これから検討課題となってくると考えておりますので、その中でまた区民集会所あるいは地域センターについても。","voiceIndex":18,"id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"確認だけです。周知の方法で、この工事は業務を並行しながら工事をするという形で、１階の事務所が２階に行くと。だから、ここの地域センターにいろいろな手続に来られる方は、多分この周辺の町内会の方々だと思います。その町内会への連絡等は、どんなタイミングでどういうふうにされるのかだけ確認をさせてください。","respondent":"伊崎地域活動課長","answer":"本日、議会の皆様に休館のご報告をさせていただきました。工事につきましても、まず皆様へのご報告を、予算として通りました後に、どのように進めていくかということはまた考えたいと考えていますが、町会長会議などでご説明はさせていただこうと考えております。","voiceIndex":21,"id":"exchange-008"}]},{"id":"topic-02","title":"「品川区消費生活・社会貢献活動展」の開催","agenda":"「品川区消費生活・社会貢献活動展」の開催","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"多分、毎年やっていると思うのですけれども、本当に素朴なあれで、第何回となぜ入れないのかということと、この後あると思うのですけれども、第２７回伝統の技と味しながわ展と、あるわけですね。項目がわかれば教えていただきたいのです。表記なのですけれども、後から説明があるのは、会場等使用料とか、設営とか、いろいろ細かく予算が出ているので、その辺を教えてください。","respondent":"河内協働・国際担当課長","answer":"第何回目ですが、一昨年より合同の形で対応しておりまして、消費生活展につきましては今回で４２回目、それから社会貢献活動展といたしましては９回目ということで、数字がかなりわかりにくくなるところから、あえてそちらのほうをのせず。","voiceIndex":28,"id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問","question":"済みません、あと１点、区制７０周年というのは、入れるべきイベントではないのですか。","respondent":"河内協働・国際担当課長","answer":"内容ですが、消費生活展が大変伝統あるものではあるのですけれども、関連性というところで言いますと、ほかに多くのものがあったこともございまして、区制７０周年というところの位置づけとしておるところです。","voiceIndex":30,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"去年、報告があったのかと思うのですけれども、この消費生活展と社会貢献活動展が合同開催となった経緯や理由、それをご説明いただきたいのと、今年度はさらに発展・融合したというご説明ですけれども、どの辺がどう発展・融合したという形なのか、去年と今年との経緯をご説明いただきたいと思います。","respondent":"河内協働・国際担当課長","answer":"そもそも２つの課が分かれてやっていたところではあるのですが、共通したテーマをもって区民に訴えかけるには、お互いのメリットをもってどうやったらいいかというところで検討したところなのですけれども、消費生活展から申しますと、もう４０数回やっておりますので、知名度。","voiceIndex":32,"id":"exchange-011"}]},{"id":"topic-03","title":"不動産業界及び警察との「危険薬物及び特殊詐欺の根絶に係る協定」の締結","agenda":"不動産業界及び警察との「危険薬物及び特殊詐欺の根絶に係る協定」の締結","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"情報提供の場合は疑わしいという時点での提供になるのでしょうか。犯罪が行われたという確認になると、裁判とか警察の判断とか、いろいろ手はずがあるわけであって、最終的な契約の解除に至る経過はどういう、このフローチャートだと、その辺がよくわからなかったので、そこをご説明いただきたいと思います。","respondent":"濱田生活安全担当課長","answer":"この犯罪の認定は誰が行いますかというのは、最終的には、もちろん捜査機関である警察が行いますが、今回の協定では、疑わしい段階でそういったものは、例えば、あそこの店、危険薬物を売っているのではないかと、買った人がいますとか、そのほかに特殊詐欺であれば。","voiceIndex":38,"id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"その辺がよくわからなかったので、もう一度ご説明いただいて、あともう１つ一緒に、そうは言っても、こういういわば反社会的な勢力は、地域社会から根絶させなければいけないと思っているのですけれども、そういう犯罪行為が行われているときは、いわゆる契約をするときの確約書だったり、特約がなければ、賃貸借契約を解除できないものなのか。","respondent":"濱田生活安全担当課長","answer":"ただ、これがあるからと言って、これはわかりませんが、強制的にまではいかないと思います。今まで、これがなかったからと言って、できなかったのかと言えば、強制的にはやはりできないです。特殊詐欺ではなくて危険薬物です。危険薬物はできません。実際に私が渋谷署にいたときも、摘発されたのですけれども、なかなかそこにまた居座って販売して、３回目の摘発でようやく出ていったということがありますので。","voiceIndex":40,"id":"exchange-013"},{"speaker":"中塚委員","kind":"確認","question":"繰り返しですけれども、もちろん根絶したいという思いで聞いてはいるのですけれども、確かに薬物は、私も報道の範囲でしか知らないのですけれども、次々と新しいものができて、指定されているもの、されていないもの、最近は包括するものまで法改正も進んでいる話は報道で聞くのですけれども、つまり、今回も疑いがあるというその時点で、確約書だったり協定があっても。","respondent":"濱田生活安全担当課長","answer":"これが個々に契約書なりそういったものに盛り込んだとしても、強制力は、たしか私の認識では、ないです。","voiceIndex":43,"id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"重要事項の説明の中にそういった文言を入れるということですよね。そういう場合はどうするのですか。撤去するのもお金が、逮捕されてしまったら誰も片づけないわけですから、そういう部分を含めてしっかりつじつまが合うような協定に、もう協定書はできていると思うのですけれども、そういう質問もこの団体からあるのではないかと思うのですけれども、その辺はどうお考えかということだけ教えてください。","respondent":"濱田生活安全担当課長","answer":"基本的な今回の考えといたしましては、この部分を盛り込んでいただくということだけ不動産業界の方に。初めに質問がありました遡及できるのかできないのか、基本的な考えは遡及はまずできません。","voiceIndex":45,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"私はよくわからないのですけれども、そもそもこの２つ、危険薬物および特殊詐欺という２つのためにこういう施策が出たのは、なぜでしょうか。もうちょっと広くして、犯罪があるではないですか。なぜこの２つに絞ったのかという点と、それとあと、協定で、この２つに関する情報を不動産関係団体に提供するとありますね。","respondent":"濱田生活安全担当課長","answer":"２つに絞った理由です。一番最初にもご説明したとおり、まず東京都と、警視庁と、全日本不動産協会の東京都本部でまず締結いたしました。その経緯といたしましては、当時、一番最初に締結したのは、実は豊島区がまず危険薬物だけを締結しました。","voiceIndex":48,"id":"exchange-016"}]},{"id":"topic-04","title":"「品川区新製品・新技術クラスターフェア」の開催","agenda":"「品川区新製品・新技術クラスターフェア」の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この開催の準備にあたっていろいろ進めていらっしゃるのだと思いますし、それほど中身について深く入るつもりはなかったのですけれども、ただ、３番、内容の4)で「ＴＰＰ特恵関税の活用について」という、ここだけを伺いたいと思ったのですけれども、つまり、アメリカ大統領がかわって、ＴＰＰ自体の合意は今やできないという、そういう状況に今ぐっと来ている中で。","respondent":"立木産業活性化担当課長","answer":"そういった中では、非常にこちらのＪＥＴＲＯのセミナーは各地で好評を得ているというところでは、品川区のこのフェアにお越しいただくお客様にとって、非常に有益になるものだろうという判断から、そのまま進めさせていただいた次第です。","voiceIndex":54,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"日本としては進めたいというのは私も報道でよく見ますが、ＴＰＰの枠自体は、アメリカが離脱をすると成立しない仕組みになっている中で、これが品川区の事業としてふさわしいのかと率直に思うのです。内容の変更について、なぜ検討しなかったのか改めて伺いたいと思います。","respondent":"立木産業活性化担当課長","answer":"発効について難しい課題が上がっているかもしれませんが、この段階で勉強を進めて、発効に向けて国が努力している中では、ともに勉強をして進めていくという意味では、非常にＴＰＰはメリットもある中では、ここでやっていくべきなのだろうというところで。","voiceIndex":56,"id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"ＴＰＰにメリットがあると言われると、ちょっと一言言いたいなと思いまして、やはりこれは日本でいうと、食料を海外に依存する、私は間違った方向だと思いますので、私はデメリットしかないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"出展企業についてお伺いしたいのですけれども、今回だけでなくてもいいのですけれども、直近の出展企業の中で、西大井の駅前、創業支援という形で品川区はやっていますけれども、ああいう創業した企業がこういう出展企業になっているという例はあるのでしょうか。","respondent":"立木産業活性化担当課長","answer":"過去には、今手元に資料がないのではっきりとは申し上げられませんが、区内の創業支援施設からこちらのほうにご応募いただいて、認定を受けて出展という形も過去にはあると考えています。","voiceIndex":59,"id":"exchange-020"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"予算的にも今言った４つの中で一番予算をつけているわけです。なのに、これ、なぜその他で説明・報告するのですか。そうですよね。いや、わからないのですけれども、課長がその他でいいと決めたのですか。だって、これはお正月といいますか、毎年これを楽しみにしているイベントだし、質問を受けたくないからその他になっているのか、その辺をお伺いします。","respondent":"山崎商業・ものづくり課長、石田（し）委員長","answer":"例えば、先ほどの消費生活・社会貢献活動展につきましては、私ども消費生活のほうで４０回ほどやりまして、先ほどご説明の社会貢献活動のほうは９回目、いろいろ事業の成り立ちがあって。委員会運営につきましてですので、これは正副と理事者のほうとで話を進める中で決定していますので、その点はご了承いただければと思います。","voiceIndex":69,"id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問","question":"区内の保育園と言っても、区内の保育園が全部来るわけないと思いますし、その辺を、例えばファンとの撮影会となると、そのファンはどなたなのか、やはり追っかけみたいな人もいると思うので、本来であれば区民という、その辺をどう考えているか、簡単でいいので教えてください。いや、いいことですよ、これをやることはすごく。それは評価をしつつも、何かもっとやり方があったのではないかなどと思いました。","respondent":"鈴木文化観光課長","answer":"シアタールームの利用については、基本的には区の正式な委嘱式ということで行いまして、一般公開の予定ではない状態で手配をしておりました。","voiceIndex":77,"id":"exchange-022"},{"speaker":"本多委員","kind":"質問","question":"その他で意見だけなのですけれども、以前、一般質問で観光大使を取り上げたことがありまして、今回のサンリオとの連携でシナモンはすばらしいと思います。この任命式も理解できるのですけれども、観光大使は複数幅広くあってもいいと思うので、ぜひ人の活用を考えてください。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-023"},{"speaker":"伊藤副委員長","kind":"確認","question":"１つだけ、サンリオのシナモンはいいのだけれども、これは観光大使をお願いした後の話で、例えば、区民の方が自分のホームページへアップするとか、それから商店街もアップするとか、議員も含めていろいろ出てくると思うのです。契約の関係でそういうのは大丈夫なのですか。その確認だけ。","respondent":"鈴木文化観光課長","answer":"ただし、一個人の区民の方とか、区議の皆さんとかが自由に使えるというものではありません。あくまで観光に使うと。","voiceIndex":80,"id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"確認","question":"要は、せっかく観光大使に就任していただくのだから、権利を十分に守りながらなのだけれども、シナモロールの写真とかを自由に活用していいのですねという確認だけお願いできればと思います。","respondent":"鈴木文化観光課長","answer":"失礼いたしました。一般の方が写真とかを撮った場合には、それは例えば今、もう一般化しているＳＮＳとかでオープンにすることは問題ないです。","voiceIndex":82,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2772#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":24475,"voices":87}},{"id":"h29-20170123-7","meetingId":"h29-cm01","date":"2017年1月23日","dateIso":"2017-01-23","committee":"厚生委員会","time":"午後 １時００分～午後 ３時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「品川“くるみ”認知症ガイド」（案）","agenda":"「品川“くるみ”認知症ガイド」（案）","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"それをもとに、このくるみぷらんも含めてなのですが、こちらも今、原案の報告をいただいて、すばらしい出来ばえと言ったらいいのですか、ちょっと大ざっぱになってしまいますが、これがＡ４サイズということであれば、文字の大きさ、見やすさを含めて、あと、必要であり、正確な情報を届ける本当に中心となり得るものというふうに捉えています。これは大ざっぱで構いません。","respondent":"永尾高齢者福祉課長","answer":"活用方法については、これから多職種の方との会議で決めることにはなるかとは思うのですけれども、もちろん高齢者クラブだとか、町会とか、そういうところにも配布はしたいと思うのですけれども、ただお渡ししても、なかなか中身までご理解できませんので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"もう既に検討の中に入られているという前提で伺いました。活用方法のところで、これからという意味なので、１つ希望的な意味で聞いてください。一番重要なのは、認知症支援という中では、地域力といいますか、全体の底上げ、理解だとかがあると思うので、そこは、今、キャラクターの活用ということもありました。本当にやることに無駄はないと思うのです。","respondent":"永尾高齢者福祉課長","answer":"やはり一般の区民の方が親しみやすいということで、キャラクターの活用だとか、区民の方が必要と思われるようなグッズの活用も含めて、認知症についての正しい理解ということを主題として広めていきたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"幾つか認知症ガイドでお聞きしたいのですけれども、１ページのところに、下の段に、認知症が誰でもかかる可能性のある脳の病気ですということで、平成２５年度では１３.７％で、都内ではということで書かれていますけれども、品川区だと、認知症の方がどれくらいということで、このパーセンテージで考えていいのか。","respondent":"永尾高齢者福祉課長","answer":"３番目のご質問として、接し方のところで、プライドを傷つけないということでしたけれども、こちらも国のほうには載っていたのですけれども、これに対しては、この検討会の中で主に福祉関係の事業者だとか、ケアマネなどのご意見の中で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"医療とか介護の従事者に対しても、この認知症に対しての理解を深めるという研修も必要になってくると思うのですけれども、そこら辺のところはどういうふうに考えられているのかと、それから、今度、在宅介護支援センターで、初めのワンストップのところでの相談というふうなことになっていくと思うのですけれども。","respondent":"永尾高齢者福祉課長","answer":"この検討会を行うに当たっても、そういった施設職員などについて代表者を出していただいていますので、そこの代表者にこれまでの計画、議事録等、全てお渡ししていますので、そういう状況の中で多職種との連携をこれから図りながら進めていきたいというふうに考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが在支で品川区はやるということなのですけれども、そこでの体制は、今回こういうガイドをつくられましたが、今後、ケアパスをつくられた段階で改めてその体制の人員配置ですとか、委託費の増額ですとか、そういうふうな体制がとられるのかというところと、それから、やはり在宅介護支援センターということであれば。","respondent":"永尾高齢者福祉課長","answer":"ただ、区といたしましては、そういう在宅介護支援センターのケアマネジャーがきちんとしたところに紹介できるような、それから研修なり指導は必要だと考えておりますので、これからもそういうところも視点に入れながらやっていきたいというふうに考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは今回こういうガイドができて、これから動き始めるというところですので、期待しています。本当にこれからさまざま取り組む中で、さらに充実をしていっていただきたいと思いますし、この在宅介護支援センターのところは、本当に品川区独特という部分がありますので、私は地域包括のそういうふうな体制という点では、今後とも充実をしていただけるように要望を改めてしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問","question":"先ほどのご説明の中で、高齢者、約８万人ぐらいですか、８万人ぐらいの高齢者に配布をされるということで、まずは一番対象に近いというか、対象になるご高齢者にというのは、非常に結構なことなのですけれども、今、品川区でも結構ひとり暮らしとか、高齢世帯のお宅が増えてきて、なかなかそういう方がこれを配布されても、なかなか見切れないというか、そういう方もいるのかなと。","respondent":"永尾高齢者福祉課長","answer":"このアンケートの中でも、やはり若年層の方が認知症への理解はまだまだだなというふうに考えておりますので、先ほど、ほかの委員からもご質問あったとおり、町会、自治会を使ったりとか、あと、そのほかのさまざまな会や団体を使ったり。","voiceIndex":16,"id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問・要望","question":"実際に配られても、自分でやるとなると、読み込んでいく中であきらめてしまうかもしれないので、そういうさまざまな会を通じて、気軽にやってもらって、自分で気づいてもらうみたいな取り組みもこれから必要になってくるのかなと思うので、先ほどとお答えは一緒だと思うのですけれども、いろいろなところを通じてやっていただきたいのと、また、先々は、例えば前から出ていましたけれども、子どもたちとか。","respondent":"永尾高齢者福祉課長","answer":"区がこれから一番取り組むべきことは、高齢者だけではなくて、若い世代も含めた認知症への理解、正しい理解の普及ということかと考えています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"松永委員","kind":"確認","question":"ご説明ありがとうございました。私からは１点だけなのですけれども、確認でいいのですが、「品川“くるみ”認知症ガイド」の中の介護予防事業についてなのですけれども、これ、各地区ごとに転々と分かれているのですが、大井・八潮地区だけに、水中トレーニングがあります。","respondent":"松山高齢者地域支援課長","answer":"介護予防の中の今ご質問がございました水中トレーニングですけれども、そちらは特に証明書等必要ございませんで、ほかの地区の方も参加可能です。","voiceIndex":20,"id":"exchange-009"},{"speaker":"松永委員","kind":"質問","question":"ほかの全部のトレーニングというか、こういった講座は、どの地区の方でも品川区であれば参加できるということでいいのですか。","respondent":"松山高齢者地域支援課長","answer":"ほかの介護予防事業につきましても、同様にどの地区の方でもご参加は可能です。","voiceIndex":22,"id":"exchange-010"},{"speaker":"安藤副委員長","kind":"確認","question":"それと、さきほど３職種の話がありましたが在宅介護支援センターにおいて、保健師が配置されていないということなのですか、こういう３職種が配置されていなくても、先ほどのような専門職につなぐというような相談は十分対応できているという考えなのかどうか、そこら辺がわからなかったので、保健師を配置しなくてもそうした相談は十分なのですという考えなのか、そこを確認させてください。","respondent":"永尾高齢者福祉課長","answer":"それとあと、次のグループホームがどこにあるかということですけれども、こちらも実はマップをつくるときにどこまでの情報を入れるかというのを大分検討をしています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"安藤副委員長","kind":"質問","question":"それと、在宅介護支援センターの窓口の件ですが、現場で民間のケアマネジャーをやっている方から伺ったのですが、在宅介護支援センターの主任ケアマネジャーは、自分でケアプランも相当抱えていますので、４０件かそこらのケアプランを抱えながら地域のご相談とかに乗るというのはなかなか大変な状況なのではないだろうかというような意見を伺ったのですが、そこら辺でちょっと心配があるのですけれども。","respondent":"永尾高齢者福祉課長","answer":"ただ、そうは言っても高齢者の数がどんどん増えていますし、いろいろな不安を持っている方もたくさんいらっしゃいますので、その実態に合わせて、例えば民間の居宅介護支援事業所にお願いをしたりとか、最初のところは受けるけれども、その後、状態を見て民間のほうに移すだとか。","voiceIndex":26,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"前にも質問させていただきました認知症サポーターなのですけれども、ガイドの１５ページに出ております。小学校でも講座を行ったということもありますので、このような形で進めていくとなると、そういう方々の力も必要かなと思いますが、今後、計画をされているのかどうか、そこら辺について教えてください。","respondent":"永尾高齢者福祉課長","answer":"ですので、そういう動きをさらに広げまして、さまざまなところへの出前講座もありますし、集中講座もある中で、そういうことを工夫していきたいというふうに考えています。学校については、教育委員会とも相談しながら方法について考えていきたいと思います。","voiceIndex":28,"id":"exchange-013"},{"speaker":"浅野委員","kind":"意見","question":"子どもたちといいますと、おじいちゃん、おばあちゃん、かわいがってくれたという恩も感じていますし、そういうおじいちゃん、おばあちゃんが、今後、どんどん認知症が進んでいくとなると、お孫さんも、人間は順番を追ってそういうふうになっていくんだということをしっかりと知る上でも重要な勉強だと思うのです。ぜひともそういう形で進めていただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今の認知症サポーターのところなのですけれども、この「品川“くるみ”認知症ガイド」の８ページの一番下のところに、「◆養成講座は、グループや企業、各種団体、小中学校などに出前で行います。その派遣は、誰が講座をやってくださるのかということについてもお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"そういう方が集まったら、区でも実際には受け付けておりますので、いろいろな啓発をするときでもそういうような説明をしています。講座のときの講師ですけれども、キャラバンメイトの資格を持っている人がやっております。","voiceIndex":31,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう１つ、先ほどからの在宅介護支援センターなのですけれども、その体制は、今回こういうガイドができて、ワンストップのところが新たな役割ということで位置づけられてくるのかと思うのですけれども、それでも体制としては、今までの体制にプラスしていくのか、それともさらに委託料を増やしていくのか、先ほどもちょっとお聞きしたのですけれども、委託料を増やして人員配置もされるようになるのか。","respondent":"永尾高齢者福祉課長","answer":"というのは、現在も認知症の方はたくさんいらっしゃって、その対応もやっているところですので、ただ、この新しく認知症のガイドができたということで、相談に来る方も少しずつ変わってきて、相談票もつける予定ですので、そこに実際に書いてきていただいてやることによって。","voiceIndex":33,"id":"exchange-016"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"済みません、ちょっと抜本的なことというか、根本的なことで、このデータヘルス計画、今いろいろご説明いただいたのですけれども、国保の都道府県化に向けて、この目標等が掲げられていますけれども、これをクリアしないと都道府県化のときに各自治体でペナルティー的な負担金が増えるとか、何かそういうものがあるのでしたか。","respondent":"高森国保医療年金課長","answer":"ペナルティーというのは行われるということは聞いておりませんで、逆に国からの支援金が増えるというふうな形で加算されるというふうな形でたしか聞いております。ただ、具体的にはまだ都道府県化の話がまだ決まっておりませんので、いろいろ話が出てきておる段階です。","voiceIndex":39,"id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問","question":"今、国からの支援が増えるというのは、クリアすれば増えるという、それともクリアされていないからもっと頑張れということで国からお金が出る、どちらなのでしょうか。","respondent":"高森国保医療年金課長","answer":"目標値をクリアされた場合には、国からのお金が来るということで、それをまたさらに被保険者の方に活用してもらいたい、そういうふうな趣旨と理解しています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。私がちょっと理解不足かもしれません。右側の軽度リスク者対策の肥満対策のところで、実績とありまして、平成２７年度１２％、平成２６年度１７.４％。括弧の中に平成２８年、今年度１１月末現在で１８.９％ということで、平成２７年度に比べてると増えているような気がするのですけれども、昨年費マイナス１.０となっているのですけれども、済みません、ここを説明を説明してもらえますか。","respondent":"高森国保医療年金課長","answer":"申しわけございません。これは、誤記です。１８.９ではなくて８.９です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このデータヘルス事業について、全国保険医新聞の記事を見ていたら、特定健診等以外に後発医薬品等の使用割合や、糖尿病などの重症化予防の取り組みの実施状況など６つの共通事業に基づいて、保険者種別によってインセンティブ制度を設けるというふうなことが書かれていて、国保は保険者努力支援制度を創設し、１６年度から特別調整交付金を増減させるというふうに書かれているのですけれども。","respondent":"高森国保医療年金課長","answer":"国からも確かに都道府県化に向けた制度設計という流れの中では、保険者の努力支援ということで、先ほど申し上げたような健診受診率が向上した場合だとかという形で支援が出てくるというのは、こういう意味でのお金が回ってくるというふうな状況で、それを活用してくれという。","voiceIndex":46,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、品川区としては、こんないろいろ取り組みをされて、そういうインセンティブというか、そこのところの保険者努力支援制度というふうなところでの特別調整交付金というふうなところでは、どういうふうになっているのかということがわかったら教えていただきたいのが１点と、それから、いろいろと細かくデータを使いながらさまざまな勧奨をするということになっているわけですけれども。","respondent":"高森国保医療年金課長","answer":"それと、データの管理につきましては、当然ですけれども、個人情報保護条例に基づきまして委託業者とも契約をしておりますし、例えばここで言っている保健指導の際に、医療勧奨ということで医療機関のほうで健診結果をご本人様にお伝えしたときに。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そうすると、データそのものは区がこういうふうなところでこういうふうに使いますというところ以外は使われないというふうなところが保証されているということですね。多分、受診してずっと医療管理がされているというところで、ドクターとの連携というのは、ドクターと相談をした上で指導に入るといった、ドクターとの連携というのはどうなっているのかについてもお聞かせください。","respondent":"高森国保医療年金課長","answer":"かかりつけ医の先生だと、食事だとか、保健指導の部分までなかなか実際にはそこまでやり切れないというふうな方もいらっしゃいますので、お医者さんが了解したものについて、こちらのほうに送っていただいて、当然ですけれども、その方と保健指導を行った、いついつに行って。","voiceIndex":50,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、例えば、重度の糖尿病であれば、１日の総カロリーが何キロカロリーとかという、そういう指示もかかりつけのドクターから出されるとか、食事とか運動とかいろいろ入ってくるのかと思うのですけれども、そういう指示はかかりつけのドクターから指示が出されて指導に入るという、そういう仕組みになっているのですか。","respondent":"高森国保医療年金課長","answer":"その段階で医師のほうからの指導に基づいて保健師がやるということではなく、連携をするということでは間違いないのですけれども、実際に食事の量だとか、カロリー、運動の部分だとか、実際にその方がどういうサイクルで生活をされているかとか。","voiceIndex":52,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは「社会階層と健康健康格差のエビデンスからの政策提言」というふうなところで、ここの中でもいろいろと社会的な経済格差によって健康格差があらわれているというところの指摘があり、それを踏まえた形でのさまざまな対応が必要だということで、何項目にもわたって政策提言がされているのですけれども、例えば、生活習慣というふうなところに対しては。","respondent":"高森国保医療年金課長","answer":"ただ、区によっては、基本健診についても受診料ということで料金設定がされているところもありますが、品川区は無料で、当然ですけれども、１人でも多くの方に何とか受診していただきたいということでＰＲを重ねている状況ですので、そういう形で。","voiceIndex":54,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さまざまなそういう生活にかかる仕事ですとか、経済的な問題ですとか、自分の努力だけではどうにもならない部分から健康が害されるという、そういうふうなところが、本当に自分の健康は自分で守るという自己責任論がすごく強調されてきた中で、今改めて健康格差というふうなところが大きく国のほうでもこのところはきちんと取り組んでいくことが必要だというふうなところが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問・要望","question":"説明いただいた中から、健診受診啓発プロジェクトの中で、未受診の理由をアンケートをとったということで、対象者が３年間受診していないという２万６,５１０人ということで、回収率も７.５％でかなり意識的には低いのかなと、本人は自分は大丈夫と、そういうふうに考えているかと思いますけれども、こういう方々にどうやってアプローチしていくのかというのは、今後の大きな課題だと思いますので。","respondent":"高森国保医療年金課長","answer":"それと、健診結果説明会の対象者ですが、こちらの対象者は、健診を毎年受けていない方と、健診結果が少し悪かったけれども、保健指導の対象外だった方なのですけれども、この中身で、血糖、脂質、血圧のどれかが要観察レベルにありまして、保健指導の対象にならない。","voiceIndex":57,"id":"exchange-026"},{"speaker":"浅野委員","kind":"質問","question":"その中で参加者数で５０人から２５人まであるのですけれども、最初にこれをやるときに、人数をどの程度考えられていたのかということと、これはどういう形で実施したのか、全員が集まって、そこで講演をされたというようなイメージだと思うのですけれども、また個別に相談に乗るとか、そういうようなこともこのときには行われたのかどうかということについて教えていただければと思います。","respondent":"高森国保医療年金課長","answer":"実は、この健診結果説明会につきましては、株式会社タニタに委託をしておりまして、こちらの会社の保健師が説明会を実際にやられているのですけれども、その説明会だけではなく、その前の時間で、例えばタニタが持っている体組成計だとか。","voiceIndex":59,"id":"exchange-027"},{"speaker":"浅野委員","kind":"意見","question":"今、最後に言われたところがやっぱり一番重要なのかなというふうに思いますので、そういうところは積極的にアピールをしていただければと思います。そういう方も今後対象者として検討していただければと思いますので、その点、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-028"},{"speaker":"安藤副委員長","kind":"質問","question":"インセンティブのところで今後の話があったのですけれども、現状では、基本健診などの受診率などでそういったものはないのか。後期高齢者医療制度における後期高齢者支援金などを加減算する仕組みなどがあるというふうにもちらっと聞いているのですが、その辺の現状はどうなっているかということをお伺いします。これは２点目です。","respondent":"高森国保医療年金課長","answer":"１２月に行われました検討結果の評価委員会においても、現状を踏まえた上で来年度に向けた方策ということで、当然ですけれども、この右下の生活習慣病の重症化予防事業の数値を変更するというふうなお話を申し上げたとおり、当然、分析して状況を踏まえた上で展開していく。","voiceIndex":62,"id":"exchange-029"},{"speaker":"安藤副委員長","kind":"確認","question":"インセンティブのところは、では、ご説明ですと、インセンティブはないと、２３区に関しては、健診受診率が一定届かないからといって、国からの罰則みたいなものはないということで、インセンティブもないということでよろしいですか。それが確認でした。それで、もう少し具体的にお伺いしたいのは、今のご説明は、一緒に庁舎に来てもらって、区のパソコンで一緒に見て作業しているということなのでしょうか。","respondent":"高森国保医療年金課長","answer":"こちらに戻ってきて、暗号を解くと、Ａさんのデータがまた戻るという状況になっていますから、こちらに来て分析ということではありませんけれども、個人情報には十分注意して、当然ですけれども、作業しているというふうにご理解ください。","voiceIndex":64,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3466#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":39364,"voices":70}},{"id":"h29-20170123-8","meetingId":"h29-cm01","date":"2017年1月23日","dateIso":"2017-01-23","committee":"建設委員会","time":"午後 １時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年２月都営住宅入居者募集","agenda":"平成２９年２月都営住宅入居者募集","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"教えていただきたいのですが、都営ですので、品川区内の都営住宅が何戸あるのかということと、今回の募集、１,６０１戸は既に空いているという認識ですか。その点について、お答えください。","respondent":"今井住宅課長","answer":"１点目のご質問の都営住宅の戸数ですけれども、品川区内に約３,５００戸ほどあります。２点目は、こちらは空いたときの登録募集ですので、全てが空いているという認識ではございません。失礼いたしました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"そうすると、１,６０１戸ある中で、今空いているわけではないが、いずれは空くという予定のものなのか。どういうところまでが、この募集になっているのでしょうか。","respondent":"今井住宅課長","answer":"ですので、もう一回申し上げますと、ポイント方式につきましては、全て空いているというわけではないと申し上げたのですけれども、訂正させていただきまして、申し訳ありません、ポイント方式の家族向け、このポイント方式の部分につきましては。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"中延一丁目区営住宅および従前居住者用住宅の整備","agenda":"中延一丁目区営住宅および従前居住者用住宅の整備","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"区営住宅は、戸数をその２１戸のままで建て替えるということですけれども、m2数とかに変化はない。今までどおりと変わらないものなのかをお伺いしたいのと、この従前居住者用住宅に入られる方はどういった方を想定されているのかを伺いたいと思います。","respondent":"今井住宅課長、寺嶋木密整備推進課長","answer":"初めに、区営住宅のm2数ですけれども、以前は２１戸、５１.０４m2ということで、若干小さくなるという状況ですが、３ＤＫについてはほぼ変わらない状態です。近隣では、中延二丁目旧同潤会地区でその事業が今進められているところでございまして、こちらのほうからの入居もある程度見込んでいるところです。","voiceIndex":13,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、従前居住者用住宅３１戸は、もう埋まるという予定なのか、満杯になるのかどうかを伺いたいのですが。","respondent":"寺嶋木密整備推進課長","answer":"あくまでも事業施行時にご意向をお伺いしての入居になりますので、今の時点で全部が埋まるかどうかということについては確定的なものはありませんけれども、見込みとしましては、全室が埋まるとは考えておりません。","voiceIndex":16,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、事業を進めるにあたって、協力していただく方に入ってもらうということですけれども、これで、今、同潤会の名前も出たのですけれども、同潤会のほうでも３１戸で足りてくるという考えなのですか。","respondent":"寺嶋木密整備推進課長","answer":"そちらの場合につきましても、こちらの制度の趣旨から、一度、民間住宅等に移ってはいただくのですけれども、その後、完成した時点で入居のご希望があるかどうかということは、簡易な調査ではありますけれども、そこの調査は既にさせていただいておりまして、それに関しては。","voiceIndex":18,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"この中延一丁目区営住宅と従前居住者用住宅は、もともとはかなり余裕のある土地というか、土地の割には余裕のある建物で、もっとたくさんの戸数を建てたいという要望、期待があったかと思うのです。","respondent":"今井住宅課長","answer":"すみません、容積率までいっぱいにはなっておりませんけれども、近隣の影響を考えまして、今までの影響等を踏まえて、その中で検討して、この戸数になったものです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"わかりました。一応、従前居住者用の戸数については、質疑の中で足りるということだったのですけれども、確認したいのは、従前居住者用住宅というのは、いろいろな入居においてどういうプライオリティーというか、例えば戸数に対してたくさんの人が入居したい、誰かを選ばなければいけないということが生じた場合に、どういう順序立てで選ばれていくという考え方とかがあるのかどうか。","respondent":"寺嶋木密整備推進課長","answer":"それが１点目の戸数を超えた場合の対応です。","voiceIndex":22,"id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"一定程度は、常に満室になってはまずいという話も先ほどあったと思うのですけれども、そういう出入りというものが行われるということもいっぱいあるのだと思うのですが、大体どういうような運営を、永住される方と短期間の方がある程度見えた中で、満室にならずに回していけるという見込みが立っているということで受けとめていいのかどうかについて、少しご説明いただけますか。","respondent":"寺嶋木密整備推進課長","answer":"本日現在で、もう満室になっていますので、今後、必要数が見込まれた上で、今度、３１戸できますと、かなり密集事業を進める際には、大変お役に立てるというか、ご協力いただけるものが増えるだろうという見込みです。","voiceIndex":24,"id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"確認にもなるのですけれども、従前居住者用住宅との複合施設ということですが、この従前居住者用住宅というのはそもそもあったのだけれども、今回、防災などの観点、整備の理由で、１回全部真っさらにして、新しいものを建てるという理解でよろしいのでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"少しご説明が不明確だったかもしれないので、改めて確認なのですけれども、まず、もともとこの場所にあったのは区営住宅のみです。従前居住者用住宅はこの位置にはなくて、先ほど、住宅課長からご説明申し上げたとおり、老朽の程度により建替えをということになりました。","voiceIndex":26,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"区営住宅を建て直して、従前居住者用の複合施設という手法は、もともとあったのでしょうか。これは初めての施設なのですか、その辺の事情を知りたいと思います。","respondent":"今井住宅課長","answer":"その際に、やはり区営住宅の建替えに伴って、住宅に困窮する従前居住者としての活用も併設して図るために研究を進めていくという形でご報告しているところで、その平成２６年５月のときには、議会のほうにも従前居住者あわせてということでご報告しております。","voiceIndex":28,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"この複合施設というのが、例えば法的に何か規制緩和されている形でこうできますと、そういう法的なところでの決まりとかはあるのですか。ただ、従前居住者となると、今度は空き室というのですかね、そういうものが出てくると思うのですね。その辺の考え方は、区としてどういう考え方を持って、こういう複合施設と考えているのかなということなのですが、いかがでしょうか。","respondent":"今井住宅課長","answer":"一方で区営住宅につきましては、戸数は現状維持という形で、これは区の方針としては変わっておりませんので、新しく広げた部分については従前居住者用で利用するという方針で進めているものです。","voiceIndex":30,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"確かに、永続的にここに住めるのかという、先ほどの質問もあったと思うのですけれども、暫定的にこの場所を使って密集市街地を整備していきますよ。全体的に住民の人たちの住宅対策をどう考えているのでしょうかと思うのですね。だったら、何で区営住宅をしていかなかったのか、それも１つの候補ではないかと思うのですけれども、それはどういう考えなのでしょうか。","respondent":"今井住宅課長","answer":"そういった中では、やはり事業協力者のところで、区内で木密整備を推進するための戸数を新たに確保したというところでご理解いただければと思うのですが、空き家との関連では申し訳ありません、なかなか難しい課題でございまして、お答えしかねるところです。","voiceIndex":32,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"だから、品川区の中で空いている部分があって、それも問題だねと言っているにもかかわらず、ここで新しくつくるという考え方がどうなのだろう。そこを、いやいや、要りませんよと。だから、区営住宅をこれだけ入れていきましょう。複合の施設というのは、どういう意味合いなのですかと聞いているのですけれども、お答えできる範囲で結構です、難しいかもしれないけれども。","respondent":"今井住宅課長","answer":"一方で、一人暮らし高齢者ですとか、いわゆる障害者のほうでも、それぞれの所管が福祉的な面からサポートするという高齢者住宅、障害者住宅等を持っておりますので、今後、住宅の政策をつくるときには、今お話があった木密の事業だけではなくて。","voiceIndex":34,"id":"exchange-013"}]},{"id":"topic-03","title":"中延二丁目旧同潤会地区防災街区整備事業に伴う解体工事","agenda":"中延二丁目旧同潤会地区防災街区整備事業に伴う解体工事","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。組合を立ち上げて約１年になった後の解体工事になったと思うのですけれども、今現在の世帯数を把握していないので教えていただきたい。これは当然、全員退去されているかと思うのですけれども、改めてその辺のところをお聞かせ願います。","respondent":"寺嶋木密整備推進課長","answer":"こちらの直近の情報といたしましては、建物の棟数にしまして、８６棟あると聞いております。それから世帯数ですが、８９世帯という報告を受けてあります。移転につきましては、引っ越しの最終段階に入っています。","voiceIndex":40,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは解体工事なのですけれども、前面道路が一方通行路ですよね。そうしますと、対象区域の図を見ますと、左側が西面になると思うので、これは重機を、おそらく前面道路からやるかと思うのですけれども、工事の日程を含めて、解体工事をどういうふうにやっていくのか教えてください。","respondent":"寺嶋木密整備推進課長","answer":"こちらは、解体工事の説明会の内容によりますと、まず期間は先ほど申し上げたとおり２月から５月ということです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうしますと、解体工事にかかわる当該地区はある程度仮囲いとか、南面も当然やっていくかと思うのですが、仮囲いとかそういうものも当然考えておられると思うのですけれども、そのところを１つお聞きしたい。改めてわかる範囲で、消防訓練はどういった訓練か、わかる範囲でいいのですけれども、再度ご答弁をお願いいたします。","respondent":"寺嶋木密整備推進課長","answer":"１点目の工事の仮囲い等の手法ですけれども、こちらにつきましては、例えば仮囲いをした上で、いわゆる粉塵が飛んだりするようなことを全部抑えた上での散水による防止対策を行う形をはじめとして、対応をきちんとということは聞いているところです。","voiceIndex":44,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、世帯数を８６棟、８９世帯と伺ったのですけれども、この中の地権者数と借家人件数、数を教えていただきたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"内訳としまして、地権者数になると、複数権利者とかいろいろな解釈で、足し算はありませんけれども、まず権利者としては、土地建物所有者の方が８０名いらっしゃるということで、それから土地のみ所有されている方が６名、建物のみ所有されている方は６名。","voiceIndex":47,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"その８６棟、８９世帯中、戻ってくる世帯数というのを今わかっている範囲で伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほど、全ての人が今まだここから立ち退けていないというお話でした。２月から５月に解体工事ということですけれども、２月１日から、もう解体工事が進むということなのでしょうか。そうすると、あとわずかなのですけれども、今、立ち退かれていない人がいる状況でも、解体工事は進めてしまうのかということを伺いたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"すみません、後段のほうのご質問から。当然、引っ越しが済んだ状況でないと解体工事ができませんので、今現在、最終の調整段階に入っているというか、まさに具体的な場所だけではなく、引っ越しされる作業のご都合等もありますので、まだ済んでいない方がいるという認識です。","voiceIndex":51,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"確認","question":"今、最終の調整をして、確認した上で解体するということを確認させていただきました。この間、１月に行われた説明会で、アスベストの問題が結構出されたのではないかと思うのですね。この８６棟中の８割から９割がアスベスト建材を使っているという説明だったそうなのです。これができていないのであれば、解体を進めるべきではないと思うのですけれども、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"アスベスト対策関係ですので、環境課からお答えします。アスベストについては、法、条例にのっとりまして、調査、また対策が必要となっております。今現在のところ、環境課にはまだ届いておりません。","voiceIndex":53,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、やはり８割、９割がアスベストを使われているということですので、この調査結果と、その報告と対策がしっかり出ていないもとでの解体は進めるべきではないと思うのです。そこを、区もそういう立場なのかを伺いたい。もし立ち退きたくない、引っ越したくないという方がいる場合、強制執行という形になっていくのかどうなのかというのを伺いたいと思います。","respondent":"三ツ橋環境課長、寺嶋木密整備推進課長","answer":"実際に、アスベストは本当に健康被害を伴うものですので、そちらにつきましては、住民、また大気汚染の関係で、きちんと対応してまいります。我々の立場としては、法令上の問題でまず最初の判断をしますので、そういう意味ではできないということではないのですけれども、当然そういった形で事業を進めていただくことは、区としても本望ではないので。","voiceIndex":55,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"アスベストのところは、本当にしっかりと対応と対策が確認できるまでは解体させないというところまで、品川区で進めていただきたいなと思うのです。それで、強制執行できる仕組みだということです、それは今までもそうなのですけれども。しかし、それが頑張ってもされずに、もし強制執行になってしまったときというのは、どこが強制執行する機関になるのか伺いたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"これはあくまでもマンションの建築ですので、もしそういう事態になった場合は、事業者ということになります。ただ、何度も繰り返しますが、そのようなことにはならないように、区のほうは再三、事業者とは話し合いをした上で、誠実に進めるように、何度も申し入れはしています。","voiceIndex":58,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"外にいる皆さんが工事が進むにあたっての要望や、建設されることには反対はしていないのです。それで、品川区も、この事業へ補助金を出していく関係にあると思いますので、そういったところで、こういった事業が進むにあたっての住民同士のコミュニケーションというのですか、そういうところへの区の責任というのは、どのように考えられているのか伺いたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"いずれにしても、我々はきちんと誠実に対応してほしいと申し入れできる立場ですので、事業者のほうには、その点についてはしっかりしてもらって、報告としましては、説明会は終わりましたけれども、今後もきちんと話し合いの場を設けて進めていくと報告も受けておりますので。","voiceIndex":60,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、区も関わる事業であって、そして区民の暮らし、防災というところに関わることですので、ぜひ区としてしっかり力を貸していただきたいなと思うのです。すみません、先ほど補助金を出す関係もあるということだったのですけれど、補助金はどういう形で、都と区から来る補助金の割合と金額もわかれば教えていただきたいのと、どういう名目が補助金になるのかを伺いたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"口頭だとわかりづらいかもしれないのですけれども、そういった形になります。補助対象事業費の３分の２が行政からの補助金といった形になるのと、補助の対象にならないのは専有部分の工事費等は対象にはなりませんと、こういった内容です。","voiceIndex":62,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"意見","question":"それで今回、補助対象部分の区が出す部分というのが幾らになるか金額はわかるのか。名目、補助対象経費がどういう名目の補助金になるのか。","respondent":"寺嶋木密整備推進課長","answer":"既に当初からも若干動いてはいるのですけれども、今現在で見込まれているという部分につきましては、総経費がおそらく９０億円台になろうかと見込んです。これは当初からの総経費です。それに対して、区の補助金は約９億円になると見込んでおります。","voiceIndex":64,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今現在で９０億円ぐらいかかりそうという中の９億円が補助金ということで、やはりこれだけの税金が入るということでも、品川区の責任は多分にあると思いますので、本当にコミュニティがしっかりと守れる事業の進行を進めていただきたいと思います。そして事業者の誠実な対応ですか、それがあればこんなにこじれなかったというのが多くの方の意見でした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"ここは、随分前から何とかしなければいけないねという話をして、何度か視察も行ったりしています。とりあえず、設立１年で解体にまでこぎつけたという状況はどうだったのでしょうか。それをどのように克服されたのかという、その経過を教えていただきたい。どういうものが建てられるのか、またこれから設計して、この委員会でもご報告があるのかなと思うのですが、それはいつ頃出ますでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"ご質問と順番が逆転して申し訳ないのですが、建築工事が平成２９年６月と資料の７番に書いてありますので、当然その前の４月なり、５月なり、まだ日時は詳細が出揃ったらということで、まして建築工事なので、先方の事業者のほうからの提示がないとなかなか設定できないのですが。","voiceIndex":67,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、ここには直接関係ないのですけれども、そこら辺の展望というか、進め方とか何かあったら、どういう形で進めていくのか。いい例というか、いい例にしていただきたいと思うのですが、やはりまちづくりという意味では、そこだけ整備しても、この地域全体が密集市街地ですから、全体のグラウンド的なイメージが必要になってくると思うのです。そこら辺の区としての考え方を教えていただきたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"実際に、東中延地区の他のエリアでは、幾つかの地区に分けて、勉強会、検討会というのをこの間ずっと進めておりますので、同じ手法になるかどうかというより、いろいろなやり方がありますので、それぞれの皆さんのお考えとか、あくまでも権利者の方。","voiceIndex":69,"id":"exchange-028"},{"speaker":"塚本委員","kind":"確認","question":"最初に、先ほど少しアスベストに関する質疑がありました。その認識で間違いないかどうかの確認を、１つお願いしたいと思います。その辺について、工事の時間帯とか、曜日とか、できる限りの配慮をお願いしたいと思いますけれども、騒音対策について、ご答弁いただければと思います、お願いします。","respondent":"寺嶋木密整備推進課長","answer":"先ほど別の委員からもご質問いただいたように、説明会の段階ではまだ調査が済んでいなかったという状況も我々は把握しておりますので、その辺についてはきちんと対応して、ここはまさにそのとおりにやっていただかなければそもそも進められない部分ですので。","voiceIndex":71,"id":"exchange-029"}]},{"id":"topic-04","title":"京急本線連続立体交差化計画等都市計画素案説明会の開催","agenda":"京急本線連続立体交差化計画等都市計画素案説明会の開催","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"この都市計画素案説明会での内容は、先ほどお話にもありましたかもしれませんけれども、今回の高架化の話と北品川駅前広場のお話、この２点になるのかということ。具体的な工事期間というのは、計画決定された後になるのでしょうけれども、具体的に大体どのぐらいから工事が始まるのかということがわかりましたら、お教えください。","respondent":"東野まちづくり立体化担当課長","answer":"工事期間の終わりですけれども、リニア中央新幹線の開通が平成３９年度に予定されておりますので、これを目途に進めていくことになると聞いております。","voiceIndex":77,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"北品川駅の駅前広場は、もともと何があったところになるのかを伺いたい。結構広大というか、大きめなものになってくるのでしょうか。それで、広場ですけれども、ただ広いというだけなのかと言ったらあれですけれども、何か公園のような形になるのか、そういったところまで計画があるのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"この計画につきましては、まちづくりビジョンでも示しています、駅前の景観に合わせた広場の計画ということになりますので、そういったしつらえを考えていきたい。北品川の旧東海道に面した広場というようなしつらえを、今後考えていきたいと考えています。","voiceIndex":79,"id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"マンション等もあるということだったのですが、そうすると、立ち退いてもらうということになるのでしょうか。そういった説明等々は、もうされているのかというところを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"まだ、この計画の形が決まっていないという部分もありますので、権利者の方への説明はまだ行っておりません。今回の説明会が、公での説明の一番最初の説明となるという形になります。今後、権利者の方々につきましては、丁寧な説明を行ってまいりたいと思います。","voiceIndex":81,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"まだ形が決まっていないということですけれども、もしそういう立ち退く状況になるのであれば、相当丁寧な説明が必要になってくるのではないかなと思うのです。まだ決まっていないということですけれども、ぜひそこは丁寧に進めていかなくてはいけないところだと思いますので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-033"},{"speaker":"西本委員","kind":"確認","question":"今の質問で確認したいのですが、計画がまだ未定のところが多いかと思うのですが、立ち退きという話がありました。例えば京急の持ち物なのか、そういうものであれば、別の用途で使うからどいてねという話になると思うのですけれども、その辺はどういう関係になってこの広場の想定がなされているのでしょうか。どういう状況になっているのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"ですから、民地のところで駅前広場をつくるという計画につきましては、この計画案が固まった段階、それからこういった説明会の機会を捉えまして、所有者の方への丁寧な説明を行っていきたいと考えております。","voiceIndex":84,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"だから、ここが公的なところでの持ち物であれば、品川区の持ち物であれば、いろいろつくるのは当然いいとは思うのですけれども、そこを民地の方をどいてくださいとまで、この広場がそんなに重要なものなのかということをちゃんと話をしないと、今度の説明会のときも納得いかないのではないかと思うのです、この辺はいかがですか。","respondent":"東野まちづくり立体化担当課長","answer":"こういった用地買収を伴う駅前広場につきましては、そういった土地の所有者の方に納得していただけるような形での説明が必要だと考えております。","voiceIndex":86,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"それは将来的に、品川区、この地域をどうしていくかという話なので、それは理解できます。そこをどういうふうに進めていくのかというのは、相当理解していただけるようなことを着々とやっていかないと、反対が起きて終わりになってしまう可能性もあるのではないかなと、私は非常に心配したのです。今の現状として、その辺の進め方はどうですか。","respondent":"東野まちづくり立体化担当課長","answer":"こういった立体化の計画に合わせた駅前広場、そういったものをまちの人が望んでいる。もしかしたら、今住まわれている人は要らないというお話があるかもしれません。そういったところにつきましては、十分な調整、説明を行っていきたいと考えます。","voiceIndex":88,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"そこは、本当に丁寧に何回も説明していただいて、ご理解いただくというのをぜひお願いしたいなと思っています。もしくは、知らないで、終わった後で、えっ、そういう話になっていたのみたいな状況になっては困りますので、そこはしっかり近隣の該当者だけでもちゃんと話を聞いて、当初から計画の中にいろいろと関わっていただきたいなと思うのですが、その辺はいかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"今回の説明会は、あくまでも素案という形での説明になります。この素案説明が一番最初の説明という形になりますので、権利者の方、それからまちの方につきましても、品川区として丁寧に対応していきたい。説明については、必要があれば、何度も足を運んでいきたいと考えます。","voiceIndex":90,"id":"exchange-037"}]},{"id":"topic-05","title":"品川区地球温暖化防止対策実行計画（第三次）の実績","agenda":"品川区地球温暖化防止対策実行計画（第三次）の実績","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"教えていただきたいのですが、２の平成２７年度の実績は、グラフでも下がっているということで、これはわかります。平成２９年度の棒グラフの棒線は０.０４２１と増えているのですけれども、これは何ででしょうか。","respondent":"三ツ橋環境課長","answer":"最初に、この実行計画をつくったときに、平成２１年度が基準年度、そして目標年度が平成２９年度としております。したがいまして、５年間で毎年１％削減の目標が０.０４２１となっておりまして、今回の平成２７年度につきましては、かなりの削減となっております。","voiceIndex":96,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"よくわかりました。正直言って、かなり頑張っているな、すごいなと思うのですけれども、平成２９年度の目標値よりもかなり下がって、達成されていますよということだと思います。いろいろなことをされている成果かなと。なので、努力は努力と認めるのは認めるのですけれども、もう少し明るいところでご飯を食べてもいいのではないかなと感じるところもあるので、その辺の考え方はいかがなのでしょうか。","respondent":"三ツ橋環境課長","answer":"委員ご指摘のとおり、昼休みの消灯の徹底は全庁的にしております。しかしながら、実際に事業に関して、窓口のところではある程度つけて、事務事業に支障のないように対応してもらっているのが現状であります。","voiceIndex":98,"id":"exchange-039"},{"speaker":"西本委員","kind":"意見","question":"なので、そこの兼ね合い、努力は努力でやっていかなければいけない部分もありつつも、やはりここは福利厚生的な考え方もあるので、どうしてもＣＯ２削減というと我慢と直結してしまうことがあるので、もう少し楽しくできるような方向に、ぜひ方向転換を考えて、ただ、ぼんと上がるのもいけないと思いますから、３年計画が始まるということなので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"この計画の概要のところで、区役所の事業に関わる全ての施設・車両の二酸化炭素の排出量を管理するということで、この計画期間と目標で、目標は達成してきたということなのですが、総排出量から見て、排出量は減らされているのかをお聞きしたいのです。","respondent":"三ツ橋環境課長","answer":"そちらと比較するのはなかなか難しくて、こちらは昨年度の計画で、一事業者としての品川区の実行計画となっておりますので、最新のデータが削減目標で１０.７％削減している状況になっております。","voiceIndex":101,"id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"この実行計画、今報告されているのは、区役所の事業に関わる全ての施設と車両の数字だということはわかるのです。総排出量のところも、２年前のものが出るということでしたけれども、２年前のものでも総排出量が減っているということが大事だと思うのです。そこは、どのようになっているのかを伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"しかしながら、品川区独自の区役所全体の削減量は、かなり総排出量を削減しているということをお知らせしたいと考えています。こちらの実行計画につきましては、本当に皆さんの努力の賜物があると考えています。","voiceIndex":103,"id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり区内の総排出量というところで、今回の報告は、ここに限った報告だというのも理解するのですけれども、やはり総排出量を大幅にしっかり下げていくということが必要だと思いますので、どこがどのように排出されているのかというのもしっかりと表わしていただいて、私たちも注視していきたいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"ＣＯ２の排出量というのが全ての施設・車両となっていますけれども、施設というのは、私の理解で言うと、電力量で排出量が出てくると思います。車両はそういうところで言うと、ガソリンの消費なのですかね。大体施設と車両の排出量の割合は何対何ぐらいになっているのでしょうか。","respondent":"三ツ橋環境課長","answer":"ガスにつきましては約２２％が、この排出量の割合となっております。したがいまして、残りの部分が燃料の合計となっておりまして、約２％程度がガソリンやＣＮＧ等々、全体の燃料となっております。","voiceIndex":106,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうすると、主に電気の使用量の削減に、具体的な取組みとして取り組んできたというところは、的を射てやられているのだなというところを再確認させていただきました。議会というのは、我々も議会棟、各控室も使わせていただいていますけれども、こういうところも環境監査というところでは、対象として含まれていたかどうかの確認をお知らせください。","respondent":"三ツ橋環境課長","answer":"監査対象は全庁舎の中の各部門が、その年によって対象となりますので、必ず全課、全所が毎年対象となっているわけではなく、五、六年程度で循環して対応してまいります。","voiceIndex":110,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"ちょっと聞くのを忘れました。以前から私は早くＬＥＤに、計画的にということで、多分３年計画の中で、それが入ってきての数値の目標が出てくるのかなと思っているのですけれども、更にかなり下がりますよね。そこを踏まえると、かなり目標値が新たなものというか、もっと低い値になってくるのかなと思うのですが、そこら辺も含めての計画見直しということでよろしいのでしょうか。","respondent":"三ツ橋環境課長","answer":"ただ、白熱灯とＬＥＤの計量の換算値が難しいことはあるのですけれども、実際に省エネルギーに対して、かなり削減ということが謳われておりますので、そちらの数値目標にＬＥＤ化の部分がどの程度含まれるのかどうかも含めて、来年度の３計画を考えてまいりたいと思います。","voiceIndex":112,"id":"exchange-046"}]},{"id":"topic-06","title":"環境表彰式・環境講演会","agenda":"環境表彰式・環境講演会","exchanges":[{"speaker":"西本委員","kind":"質問","question":"環境表彰式の表彰者なのですが、みどりの顕彰とか、資源リサイクルは何となく選定理由の根拠がわかるのですけれども、環境保全のところでは、選定の理由や方法というのは、どういう形で選ばれているのでしょうか。それと、地域賞で、猫基金グループというのがあるのですけれども、非常に興味深いのですが、この内容を少し教えてください。","respondent":"三ツ橋環境課長","answer":"平成２５年１月から活動をずっと継続していただきまして、週三、四回の清掃。猫用トイレを町内に４カ所も設置する。餌やり禁止活動および清掃により、地域猫のふん尿、悪臭を改善しております。そのような取組みを行っている団体です。","voiceIndex":118,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな活動をされているということなのですが、これは推薦方式なのでしょうか。それとも、どこかで情報をいただいて俎上に上がってくるのか、その仕組みを教えてください。それは非常に気の毒だなと。こういう賞をとることによって、紹介できる方法につながるといいのかなと思うのですけれども、何かいいアイデアがあったら、ぜひ取り組んでいただきたいなと思いますが、そのお考えを教えてください。","respondent":"三ツ橋環境課長","answer":"やはり表彰することで地域に広めていっていただき、この取組みも清掃活動の１つではあると思いますので、引き続き、横に水平展開できればと考えています。","voiceIndex":120,"id":"exchange-048"},{"speaker":"西本委員","kind":"意見","question":"所管が違うというところもありますけれども、多分こういう環境課でやっていることが、保健所のほうもかなりリンクして、いい方向に持っていける可能性があるので、そこは横で連携していただいて、情報を交換しながら、いい宣伝になっていただくように、啓発活動ができるようにお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-049"}]},{"id":"topic-07","title":"平成２８年度区内一斉防災訓練の実施結果","agenda":"平成２８年度区内一斉防災訓練の実施結果","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"アンケート集計結果なのですけれども、回収率は、基本的に書面で回答を得たものを集約しているということでしょうか。会場で、当日終わった後に反省会みたいなことをやって、そこでも結構意見が出たりしているところがあったかと思うのですけれども、そういうものは、この中に含まれているのか。あるいは別物として、それはそれとして活かされているのか、そこをお伺いします。","respondent":"黒崎防災安全担当課長","answer":"この後に、反省会などで出た意見につきましては、まずそこで集約をしていただいて、今年の７月以降、各避難所による避難所連絡会議というものが始まってきますので、そこで具体的に区と情報共有し。","voiceIndex":127,"id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"とりあえず最後はみんな参加者が集まって、そこでいろいろな意見を言う場面が少しあったのです。あったのですけれども、やや集約する職員の側からすると、そこでそんなに意見を聞くというつもりはなかったのかもしれなかったのですけれども、そんなにたくさんの意見を求める雰囲気ではなかったのです。そのご意見というのを活かしていくような考えというのは、どのようにされるか。","respondent":"黒崎防災安全担当課長","answer":"来年度につきましては、避難所連絡会議の委員長なり各会長から、皆様どうですかということでご発言があったことについては、区から訓練に参集した職員もきちんと意見を集約できるように、そのような話もきちんとしながら。","voiceIndex":129,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問・要望","question":"東京都防災アドバイザーの方々が来ていただいたということですが、東京都もそういう団体があるのですよね、どういう団体なのかなという確認です。ここの方たちにもご理解を求めて、この日は一斉にやりましょうという形で問いかけていくのだったら、今のうちから言っておかないと、多分行事等々をいろいろと入れてしまうので、１２月というと、結構餅つきとか、非常に行事が町会は入ってしまう。","respondent":"黒崎防災安全担当課長","answer":"となりますと、やるべきことを１つずつこなしていくのですけれども、情報が重複したり、実施したものが未実施になっていたり、未実施だったものが実施したのか、まだ取り組んでいないのかというのが不明確な部分、要は情報の錯綜という部分がございました。","voiceIndex":131,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、一斉訓練ですから、参加を促す意味では、７月では遅いと思うのです。というのは、大体町会の行事が決まるのは総会なものですから、大体４月、５月、６月の間に１年間の予定が決まってしまうのです。最後に、ＨＵＧ訓練ですか、これは多分ご存じない方がほとんどだと思うのですけれども、多分これを実際にやってみると、避難所の初期の対応をどうしたらいいのかということがすごくわかると思うのです。","respondent":"黒崎防災安全担当課長","answer":"これは直接ＨＵＧとは少し違うのかもしれませんが、２つの内容に分かれてくると思いますので、また防災課のほうでしながわ防災学校や防災カフェなどのコースを持っておりますので、そことうまく連携を図りながら。","voiceIndex":133,"id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"この児童生徒の参加なのですけれども、結構垣根を越えて参加しているところと、あとはゼロのところがほとんどなのです。これは、通っている学校と避難する場所が違う生徒もいると思うのですけれども、そうしたことが関係しているのか。それとも児童生徒にはあまり呼びかけられていなかったというか、どういうふうにお知らせがされていたのかなという部分を伺いたいと思います。","respondent":"黒崎防災安全担当課長","answer":"今年の平成２９年度の訓練につきましては、学校が開校日である１２月２日（土）を予定しております。","voiceIndex":135,"id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問","question":"子どもたちも今いろいろ忙しいですから、なかなかその辺の都合を合わせるというところでは難しいと思うのですけれど、そういったところの働きかけを学校としては考えていなかったということなのですが、区としてはそういう位置づけでいいのか。ですので、そういった初動の大混乱を防ぐためというのでしょうか。そういったところでは、区としての考えが何かあるのかどうかを伺いたいと思います。","respondent":"黒崎防災安全担当課長","answer":"区といたしましては、まず避難所の設置は、当然まちの方と協力して行いますけれども、在宅避難というものがまず第一と考えておりますし、また普及啓発をさせていただいているところですので、在宅避難につきまして、またそれに必要な備えにつきましては、今後。","voiceIndex":137,"id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"意見","question":"在宅避難ということですけれども、家が安全でないと皆さんは避難していらっしゃるので、やはり安全な家をつくっていくためにも、予防対策をさらに一層進めていかないと、いつ来てもおかしくないと言われている直下型の地震なので、予防対策を一層進める支援を区としてもしっかりと強力に進めていかなければいけないと思います。そこをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-056"},{"speaker":"高橋（伸）委員","kind":"確認","question":"別紙１の各防災訓練の内容の中で、荏原第３地域の戸越台中学校。これは３町会より９５名の参加が出ていまして、これは単純に６名だとしたら、十五、六人に対して１人の生徒が施設確認の説明をしたということでよろしいのでしょうか、よろしくお願いします。","respondent":"黒崎防災安全担当課長","answer":"ただいまの６名の児童生徒の方のお話です。荏原第３地区でこの５校が参加していただきまして、そこで、戸越台中学校の生徒の方６名がボランティアとして訓練に参加していただいたです。","voiceIndex":140,"id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":46011,"voices":150}},{"id":"h29-20170123-9","meetingId":"h29-cm01","date":"2017年1月23日","dateIso":"2017-01-23","committee":"文教委員会","time":"午後 １時００分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区立しながわ区民公園内認可保育所整備・運営事業者の選定","agenda":"区立しながわ区民公園内認可保育所整備・運営事業者の選定","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"最後の選定方法なのですけれども、それぞれ応募が何事業者ぐらいあって、審査会の中で何事業者に絞られていって、その後ここに決まったという数字を教えてください。","respondent":"大澤待機児童対策担当課長","answer":"３事業者の提案がございまして、そのうちの１者に決まりました。","voiceIndex":10,"id":"exchange-001"},{"speaker":"あべ委員","kind":"質問・要望","question":"せっかくしながわ区民公園内に開設するということですので、ぜひ、この環境を十分活かした保育内容を、事業者に対しても工夫するように要望していただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"},{"speaker":"のだて委員","kind":"提案","question":"選定理由のところなのですけれども、その前に、もう少し詳しい内容の、事業者が提案している資料をいただけたらうれしいのですが、そういった提供を今後お願いしたいのですが、いかがでしょうか。そして、サクセスアカデミーの保育士の離職率と、勤続年数や初任給を教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"保育園と地域の連携ですけれども、こちらの事業者は「地域とともに育つ保育園」ということを掲げておりますので、今後、地域、また、区のほうと相談しながら、地域との事業を進めていきたいということは伺っておりますが、今のところ具体的な提案としては受けていません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"のだて委員","kind":"提案","question":"資料のほうは企業秘密ということなのですけれども、そのものでなくてもいいのですが、提案内容のもう少しわかるような形で出していただけたらと思うのですが、プロポーザルということで、考え方を示したもの、具体的な案が今のところ全体的には示されていないという捉え方でよろしいですか。こういった内容で今後進めていきたいということでよろしいですか。","respondent":"大澤待機児童対策担当課長","answer":"離職率につきましては、私どもも少し高めかなと思いましたので事業者に聞き取りをしましたけれども、自己理由というのですか、例えば、ご結婚されるとか、田舎に理由があって帰るという、そのような個人的な理由で退職される方が全体の七、八割を占めているということで。","voiceIndex":15,"id":"exchange-004"},{"speaker":"のだて委員","kind":"確認","question":"最後に確認ですけれども、離職率は自己理由が多いということですけれども、そうすると、会社の職場環境が悪いとか、働き続けられないという環境で１７.７％になっているわけではないということでよろしいですか。","respondent":"大澤待機児童対策担当課長","answer":"はい、会社としましても、保育士の定着にはやはり力を入れているところで、働きやすい環境を目指しているということで、休憩を必ずとれる体制を組むこと、残業をできるだけしなくても仕事が終わるように会社としてバックアップする。","voiceIndex":17,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"特に、まだこれからかと思いますけれども、区民公園の中の保育園ということで、公園を活かした、また、そこに集ってくる人たちとのかかわりができるような、何かそういう方向性が持たれていくのかどうか、そこら辺もし今見えているところがありましたら教えていただきたいと思います。","respondent":"齋藤子ども未来部長","answer":"現段階ではまだ工事中でございまして、防災まちづくり部公園課ともうまく話をしながら、いい形で公園が使えるようにしたいと考えています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"３点お伺いしたいのですが、３事業者が応募ということなのですが、新規の事業者がいらしたのかどうか。今、民設民営が増えている中で、企業参入がどういう状況になっているのかが知りたいので、その点が１点です。ひろまちの場合は公設民営で建物をリースでやりましたね。ここの場合１０年契約なのですが、事業者が建てるのか、リースとかそういった関係になるのか、その辺も教えてください。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月より早くということですが、公園の工事との兼ね合いもありますので、それは難しいと思っています。平成３０年４月開設ということで計画しております。建物ですけれども、これは事業者が一番最初から建てます。","voiceIndex":21,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"とりあえず開設から１０年予定ということなのですけれども、事業者が建てるのであって、その後は何かお話を聞いていますか。リースで組み立ててリースで壊すのではないのですね、きちんと建てるのですね。その辺わかっていたら教えてください。","respondent":"大澤待機児童対策担当課長","answer":"１０年というのは、都市公園法で公園の占用期間が１０年という制約があるので、予定として１０年となっておりますけれども、占用期間の更新は可能ですので、状況によって延長していくということで事業者とお話しています。","voiceIndex":23,"id":"exchange-008"}]},{"id":"topic-02","title":"目黒駅前地区認可保育所整備・運営事業者の選定","agenda":"目黒駅前地区認可保育所整備・運営事業者の選定","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"先ほどと同じ質問です。７事業者が第一次、第二次でどういう形で絞り込まれていったのか教えてください。それから、既存園において障害児保育や一時預かり事業等に積極的に取り組んでいるとありますが、この目黒での運営に関しても、例えば、障害児保育、一時預かり事業というようなことは、その蓄積を活かして行っていく予定なのか。","respondent":"大澤待機児童対策担当課長","answer":"提案のあった７事業者につきましては、第一次審査、第二次審査とも、７事業者審査をしております。特別支援児童の保育、一時預かりについても、新規園でも実施していくという考えを示しています。","voiceIndex":29,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"障害児を受け入れている保育園は民間でもいろいろあるかと思うのですが、ここに出ているということはそれだけ積極的にやっていらっしゃるのだと思います。それで、１つお伺いしたいのですけれども、今、去年の法改正以来、医療的ケアの必要な子どもたちをどうしていくかということで、大分２３区の中でも進んできている。","respondent":"大澤待機児童対策担当課長","answer":"医療的ケアが必要なお子さんについては、今のところこの園でどうするかというところまでの検討はしていません。区としてどうしていくかは今後の検討課題だと認識しています。","voiceIndex":31,"id":"exchange-010"},{"speaker":"のだて委員","kind":"提案","question":"その下に、保育士養成校への講師派遣をして職員の確保をしているということなのですけれども、夢工房の報告書の中で、卒業校へ職員の配置を強制しているようなことがあったと書いてあったのですけれども、そういったことはないのか確認させていただきたいと思います。工事の配慮で、具体的に配慮が提案されているということなのですが、説明会の実施以外でほかに具体的なところがあれば伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"建物の工事についてですけれども、再開発ビルということでかなり規制がありまして、３階に保育園ができるのですけれども、基本的に３階以上はオフィスになっているので、あまりにも保育園として外観上突出してしまうと困ると言われておりますので、かといって。","voiceIndex":33,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"３階は保育園以外はオフィスだということなのですが、そうしたら、２階などにかえられなかったのかなという思いもあるのですが、そういったことはあったのか教えてください。今、外観の話がありましたけれども、工事の配慮については、この説明会だけなのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"２階まではテナントで、お店になってしまうので、そうすると、保育園とはまた少し雰囲気が違ってしまうので３階になっています。工事の説明会については、今後、再開発組合と保育事業者が中に入って、定期的に相談して進めていくと聞いています。","voiceIndex":35,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区に譲渡された区分所有の建物、駅前でもかなり大きなものなのですが、どこのスペースがどのくらい区に譲渡されたのかわかったら教えてほしいです。大きいオフィスビルの３階ですよね。私としては、なぜ１階にできなかったのかと。それから、３階に保育園だけではないですよね、ほかのものが入るのではないかと思うので、建物がどうなっているのか教えていただきたいのが１点です。","respondent":"大澤待機児童対策担当課長","answer":"最初にお尋ねの区に譲渡されている部分ですが、全体として１,１００平方メートルが譲渡されています。３階のオフィス棟の保育園が入っている部分には、ほかのテナントやオフィスは入っていません、保育園のみになっています。","voiceIndex":37,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどの１,１００平米ということで、これは何階の部分ですか。保育園は３階のワンフロア全部が保育園に使えるということですか。そこをもう一度お聞きしたいです。施設長、１０年の経験って、施設長としての経験はわかったのですが、会社の要綱に資格を問わないという項目があったのですが、私の感覚としては、園長、施設長は、保育士ではないかなと思っているのですが、その辺の確認をさせていただきたい。","respondent":"大澤待機児童対策担当課長","answer":"平均年収ですが、全体として３７０万円と聞いております。職員の平均年齢が３１.８歳です。","voiceIndex":39,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一番の願いは１階にしてほしいのですけれども、店舗が１、２階に入るのですね。最初のスタートがどうだったかなと思いますけれども、ぜひ、子どもの安全を考えたときに、おおもとのところから主張していただきたいと思うのが、これは願いです。施設長のところは、私もきのう調べていて、資格を問いませんという募集要項だったので、少し気になったので、ぜひ確認をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"}]},{"id":"topic-03","title":"生活支援型一時保育（オアシスルーム）施設の新規開設","agenda":"生活支援型一時保育（オアシスルーム）施設の新規開設","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"確認をしたいのですけれども、この水神児童センター内のオアシスルームはなくなるというのは、こちらをオープンするからやめるという発想なのでしょうか。オアシスルーム自体は、なかなか予約がとれないという話もよく聞きますし、ニーズから言えばまだまだ需要のほうが大きいと思いますし、また、定員も増やしていただきたいと思っているところなのですが、水神を残すという発想はなかったのか。","respondent":"齋藤子ども未来部長","answer":"委員ご指摘のとおりでございまして、私ども内部で検討したのですが、水神児童センターはマンションの１階部分で、ちょうど学校で言うと保健室ぐらいの形で狭くて、場所の位置どりも含め、児童センターの利用とバッティングしていた部分もありますので。","voiceIndex":46,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"これは児童センターと類似する公共施設の中だけで考えられるのか、場合によっては、このぐらいの面積であれば民間の場所も含めて設置の検討は行われるのか、その辺の考え方も教えてください。","respondent":"齋藤子ども未来部長","answer":"区でも、施設があれば活用できないか、これからも情報のアンテナを広げていきたいと思います。","voiceIndex":48,"id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"非常にニーズの多い、特に在宅子育て家庭に対する支援というのは、どうしても手薄になりがちですので、ここはぜひ積極的に進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えば、全部私は見ているわけではないのですけれども、遊具ですとか、場所ですとかによって、オアシスルームで違いがあるという声を聞いているのですが、それぞれ規定というか、各オアシスルームでこれは用意しようとか、それは平等に、それぞれ同じような形でされているのか、その確認をさせていただきたいです。そこら辺での安全面の確保をどのようにされているのかお聞かせいただきたいと思います。","respondent":"齋藤子ども未来部長","answer":"地域の偏在につきましてはご指摘のとおりでございまして、５年後、１０年後、子どもの数が今品川区は２番目に増えていますけれども、多少落ちつけば、またもとのとおり保育園でうまく活用できないかと考えておりますが、なかなか難しい点もありますので。","voiceIndex":51,"id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこの少し裏ということですので、誘導をわかりやすい形にしていただくとか、これも要望します。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"体制なのですが、保育士と看護師、事務員などの人数も含めて教えていただけたらと思います。水神児童センターが吸収されてしまうということで、移転の形になると思うのですけれども、そういったところで困る方はいらっしゃらないのか、周知等はどういった形でされているのか伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"体制ですが、正規の保育士２名と、非常勤の時間帯に応じて対応していただける保育士の配置は現体制と変わらないようになっております。","voiceIndex":54,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"事業者は選定中ということでしたので、各オアシスルーム１つ１つ違うということですね。水神児童センターの現在の利用人数は何人ですか。利用状況を教えてください。","respondent":"齋藤子ども未来部長","answer":"水神児童センターの利用の実績のほうから、人数だけですが、平均的には、４月は７０人、一番多い３月は１２８人、トータル延べでは１年間で１,０９９人にご利用いただきました。全体では８０％ぐらいの利用率で、大変混んでいるです。","voiceIndex":56,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"意見","question":"今日は時間がないので詳しくはあれですが、オアシスの事業者はどういう事業者が入っているのかを知りたいので、一覧表などを出していただけると。今ありましたけれども、希望がかなっていないというのは聞いているのですが、利用率がどのくらいで、例えば、平均どれくらいの利用者がいるのか、概要的なことがわかるような資料を出していただけたらと思います。","respondent":"齋藤子ども未来部長","answer":"本日はご用意できませんので、次回の委員会ではご用意いたします。","voiceIndex":58,"id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"要するに、何を言いたいかと言うと、これを見ると、２日間だけのところが結構あるのです。ただ休みがありましたということで、休んだというだけで、どうせ休むのだったら最低３日から４日ぐらい必要なのではないかと去年も言ったのですが、最終的には決めるのは校長の判断になるので、その辺区として学校のほうに何らかの例えば期間とか何かの対応を求めたりすることはあるのですか。","respondent":"有馬学務課長","answer":"逆に月曜日の場合は、火・水・木３日間にしようという形で、その辺は曜日も影響しておりますけれども、原則は３日という考え方は学校にもあろうと考えております。","voiceIndex":66,"id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"意見","question":"３日休んだところは半分ぐらいだと思うのですけれども、教育委員会でそういうお考えだったら、ぜひ、学校のほうにもきちんと伝えていただくようにお願いします。やはり最低３日休まないとあまり意味がありませんので。小学校に関しては、発熱後２日と発症してから５日。幼稚園・保育園に関しては、発熱後、解熱してから３日間ということで１日プラスになっている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"１点。兄弟関係があるところで、例えば、２人いるうちの片方がインフルエンザになったときに、もう一人も休んでほしいと言われるケースがあるそうなのですが、休める場合はいいのかもしれないけれども、もう一人がずれて発症すると、親は延々と休まなければいけない状況で困ってしまうのですが、兄弟関係のところをどのように考えたらいいのか教えてください。","respondent":"齋藤子ども未来部長","answer":"なかなか法上の強制がないもので難しくて、正しい答えができかねるのですが、私どもとしては、子どもさんが菌をまくということは、ほかの子どもたちに感染するので、ぜひお休みしてくださいと、兄弟２回休むことになるかもしれないけれども、自分の子ども。","voiceIndex":69,"id":"exchange-026"}]},{"id":"topic-04","title":"学校改築事業","agenda":"学校改築事業","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"文化財なのですけれども、現段階で文化財としての規模とか評価とか、そういったことは概要としてどんな感じなのでしょうか。","respondent":"篠田学校計画担当課長","answer":"規模ですけれども、試掘調査というのは全体をできるものではなくて、予定されている学校の敷地の中から全部で８カ所ほど、面積にしますと６８平米を試掘しました。","voiceIndex":76,"id":"exchange-027"},{"speaker":"あべ委員","kind":"意見","question":"となると、一応、これ半年間調査することになっておりますけれども、埋蔵物の規模等々によってはこれがさらに延びる可能性があるのかということが１つ。","respondent":"篠田学校計画担当課長","answer":"１つは、工期への影響ですけれども、確かに出方によって影響が絶対に出ないとは言い切れないのですが、今のところ見込みとしましては、深く掘ってまた出たとしても、きちんとした形での記録を残すということで、工期には影響が出ない形でできるのではないかと考えております。","voiceIndex":78,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"図面のほうですが、クラスルームとか多目的室、開校記念室などの位置が変わっていると思うのですが、この変更になった理由を教えてください。","respondent":"篠田学校計画担当課長","answer":"新しい学校のレイアウト図の変更になった部分ですけれども、こちらは、前回の決算特別委員会でもご質問いただきましたけれども、お隣の天妙国寺というお寺さんがございまして、敷地の境界に大きな木があって、品川区の保存樹にもなっているということで、そちらの保存対応で。","voiceIndex":80,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"アンケートの調査なのですけれども、これを学校運営に活かしていくということなのですが、イメージが湧かないのですけれども、具体的にどういった活かし方があるのか、あるいは実際に活かされた例があれば教えていただければと思います。","respondent":"有馬学務課長","answer":"中学校につきましては、「友人関係」ですとか「クラブ活動」という傾向があり、「学校が近い」は上位にある、こういう傾向をつかみまして、特に小学校におきましては、「教育活動に魅力がある」が傾向として出ておりますので、学校説明会ですとか、学校公開ですとか。","voiceIndex":86,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"調査のほうですけれども、義務教育学校と小学校・中学校別々のところと集計を別に出しているようなことはないでしょうか、多分、違いがあるのではないかと思うのですが、そういうことはしていないかどうか。義務教育学校については、その特徴を理由に選んでいる方もいると思うのですが、項目の中に小中一貫校だから選んだとか、どうしてそういう項目がないのか疑問で仕方がないのですが、その辺が１点です。","respondent":"有馬学務課長","answer":"今後の見込みですけれども、まず中学校につきましては、これから動きが出てくるものと考えています。最終的にはどうかということですけれども、そこはまだ今後の様子を見ないと何とも言えないと現時点では捉えています。","voiceIndex":88,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、そろそろ選択制の見直しのお考えなどないのか。希望のところも、言ってみたら、それぞれの学校の教育活動の魅力があるところを選ぶことにおいては、地域の学校が地域の要求をどうかなえていくのかという努力が問われているのではないか、それこそ公教育の責任ではないかと考えているのですけれども、その辺のお考えをお聞かせいただきたいと思います。","respondent":"有馬学務課長","answer":"ただし、今言われたように、兄弟枠で入れないとかそういうこともありますので、その部分については、今回つくった学校案内パンフレットにもきちんと説明しましたけれども、今後またさらにそれは進めていく必要があると考えています。","voiceIndex":90,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、公の教育の責任という意味において、大事な時期のこの子どもたちに与える影響というのが、こういう影響を与えることが教育的なことなのかという観点でも、ぜひ、検討していただきたいし、私たちとしては、ぜひ、この選択制は見直しをしていただきたいと強く求めていますので、今日は意見だけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"その結果、何に重きを置くかによって選択をするとか、自分の本来の学校に行くか、その辺のプロセスなども知ることによってまた見えてくるものもあるのではないかと思うのですけれども。でなければ、選択を、つまり、学区外を希望していない保護者の声もあわせて聞いて比較することもあっていいのではないかと思うのですが、教育委員会としてはいかがお考えでしょうか。","respondent":"有馬学務課長","answer":"まさしく委員が言われたとおり、そういった声が重要だと認識しておりまして、毎年ちょうどこの時期になりますけれども、保護者向けのアンケートを行っております。","voiceIndex":93,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、そのアンケートとこのアンケートはどういう関係になるのでしょうか。一部重複しつつ、外を希望した人だけ少し詳しい調査をとっているということなのでしょうか。まとめるなり、比較できる形にするなり、何かもうひと工夫あったほうが次につながるような気がするのですが、いかがでしょうか。","respondent":"有馬学務課長","answer":"要はアンケートが２つあるということになります。１つは、学校選択を希望した人には、その選んだときのリアルなタイミングで、何を理由に学校を選択しましたかを聞きましょうと。","voiceIndex":95,"id":"exchange-035"},{"speaker":"あべ委員","kind":"意見","question":"今日は時間の制約もありますし、これ以上突っ込むつもりはないのですけれども、こういう調査もしました、ああいう調査もしましたということだけではなくて、何を比較して、何に活かしたいかということの観点から、アンケートをどのような形で誰に対してとるかというのはさらに精査していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"意見","question":"１つだけ。わかればなのですけれども、中学校の１２番の「クラブ活動の状況」で、アンケートの回答では何部かというのは書かないことになっているのですけれども、もし何かの状況から何部かというのがわかれば、もしなければまた別の機会に聞きますので。","respondent":"有馬学務課長","answer":"このアンケートにつきましては、保護者に負担をかけないということで、この資料の４ページ部分をつけていますけれども、そのマークシートしかございませんので、それ以降のどのクラブが魅力があるというのは、この段階ではとっておりません。","voiceIndex":98,"id":"exchange-037"}]},{"id":"topic-05","title":"平成２９年度品川区立学校における土曜日の授業の実施","agenda":"平成２９年度品川区立学校における土曜日の授業の実施","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"昨年も合計１４日だったのですが、この１４日というのは何か基準、決まりがあるのか。この土曜日授業のあり方なのですが、近隣の区と比べてどうなのか、わかる範囲で教えてください。","respondent":"村尾教育総合支援センター長","answer":"１点目です。１４日になったのは、たまたま１４日になったということで、特に１４日に指定しているということではありません。２点目の土曜授業日のあり方についてですが、少し古い調査しかないのですが、近隣の区でもやはり土曜授業はどんどん増えているという感覚です。","voiceIndex":104,"id":"exchange-038"},{"speaker":"のだて委員","kind":"意見","question":"今回この１４日の中で、第１土曜日にあったり、第３土曜日にあったり、ばらばらになっているところで、いつがこれに当たるのかすごくわかりにくいと思うのですけれども、そういったところで、保護者の方とか子どもたちからの声があるか、そして、区の考え方をお聞かせいただければと思います。","respondent":"村尾教育総合支援センター長","answer":"子ども、保護者からという声は、昨年度も特にこちらのほうには届いていませんけれども、暦の関係上、どうしても学級始め、学級終わりは、土曜日に授業してもなかなか子どもたちが集中できない等、いろいろな条件のもとで、このような形で１４日指定をさせていただきました。","voiceIndex":106,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":29228,"voices":112}},{"id":"h29-20170123-5","meetingId":"h29-cm01","date":"2017年1月23日","dateIso":"2017-01-23","committee":"総務委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"福井県坂井市の美術・文化展の開催","agenda":"福井県坂井市の美術・文化展の開催","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もしおわかりだったら、荒川区とか港区が取り組まれたというのだけれども、どことどのようなことをされているのかというのがわかれば簡単に教えていただきたいのと、それからこれはよく連携事業で共催だというのだけれども、費用負担なんていうのはどういう形で決めていらっしゃるのかなというのを教えていただけますか。","respondent":"柏原企画調整課長","answer":"プラス、先ほど申し上げた坂井市が全国シティセールスストラップのコンテスト、これはちょっと別扱いということで坂井市のほうで費用負担するという流れになっておりまして、こちらのほうは金額がどの程度まで今いくかというのは、細かい数字は把握していませんけれども。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"品川区制７０周年記念式典","agenda":"品川区制７０周年記念式典","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"お伺いしたいのですけれども、出席率はいつも賀詞交歓会は何人に招待状を配って何人ぐらい……。この８００人のうちどれくらい。どうしてこのようなことを言うかというと、区民のほうはこれは応募が多かったらおそらく抽選とかになるのだろうから、そこら辺のところの８００人の読みというか、その辺のところを教えてほしい。","respondent":"久保田総務課長","answer":"ただ、いろいろな役をやって重複していますから、これを実人員といたしますと約１,８００人ほどいらっしゃいまして、それの大体賀詞交歓会に例年４割から５割の方がご出席をいただいていますので、それの見込みから考えますと、大体８００人程度の実績が出ますので。","voiceIndex":11,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこら辺の、今のでお伺いすると実績ベースだからいいのだけれども、この辺何か工夫したほうが。２１日の３時だと、そこで２００人ぐらい減ってしまうと結構空席が見えてしまうのかなと思うので、余りそういう空席がないような形の工夫が必要かなと思うので、どう考えられているのかなというところが。","respondent":"久保田総務課長","answer":"今回は、功労団体で感謝状贈呈式というものもありますので、賀詞交歓会ですと招待状を送ってそれで出席してもらう、してもらわないといっているのですが、今回はそういったいろいろな記念すべき式典でもありますので。","voiceIndex":13,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"その場合の、この間の成人式なんかを見ていても、参加するつもりで来てそこの会場に入れない方へのフォローみたいなのは両方考えておいた方がいいのかなと思うのですが、その辺はいかがでしょうか。","respondent":"久保田総務課長","answer":"両方考えられるということで、私どもも多ければ多いほうがいいのでいろいろ声をかけるのですけれども、もしも会場があふれたときのために、７階のイベントホールにサブ会場というのでしょうか、モニターからの観覧というふうになってしまうのですけれども。","voiceIndex":15,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"あふれてしまう心配がもう一つ。人権のつどいのときなんかも、映画があったり講演会があったりするせいか、すごく皆さん参加が多い。だから、第一部と第二部のご招待をどうするのかということと、第一部のほうにもたくさん来ていただきたいし、その辺の、ちゃんと全体に盛り上がった形で成り立たせるためのそういう工夫というのはどのようにされているのか伺いたいと思います。","respondent":"久保田総務課長","answer":"やはり今まで区政に功労のあった団体の方々と、また区民の方と一緒になって７０周年をお祝いしたいと考えていますので、私どもとしましては、できるだけ多くの方にご参加いただきたいと思ってあります。","voiceIndex":17,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"そういう点で、この区民の公募というのがなかなか先ほどの方のご質問の中でも参加しにくい時間帯だということもあるので、その辺区としてはどういうふうに考えているのか、いろいろな区民の方にそれこそ公募して積極的に参加をしていただくというスタンスでこういうふうな企画をされていると思うので、とりわけそこのところはよく聞いておきたいなと思っています。","respondent":"久保田総務課長","answer":"そうした中で、平日の火曜日の午後ということでご指摘があったわけですが、できるだけこういった機会にご参加いただきたいと思っているところですので、そういった機会を設けるとともに、これだけではなくて、例えばいろいろとＰＲ等もしてきたところですし。","voiceIndex":19,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"したがって、公共施設の利用を区のほうが何カ月も前からとってというところでは、区民とのいろいろな関係が出るかもしれないけれども、土曜日なり日曜日の選択というのはなかったのですか。","respondent":"久保田総務課長","answer":"私どもいろいろと日程のほうの調整をさせていただいて、土曜日、日曜日ということも考えてきたところではありますけれども、全体的な判断の中で、今回は３月２１日ということで日程を決めさせていただいたというものです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"ちょっとしつこくてごめんなさい。全体的な判断の中でというのは非常にファジーで、よくわかりません。したがって、どのような角度でどのような考え方のもと、会場をとるのは区が先に押さえてしまうのはいろいろ問題があるとかそういうことも含めて検討の上選択したのかなというのはちょっとよくわからないので、その辺を少しわかるように教えてください。","respondent":"久保田総務課長","answer":"そうすると、その前後でということで日程調整を、会場の都合等もあるのですけれども、考えていた中で土曜、日曜ということで３連休もありますのでなかなか会場を通して使うということが難しいということもございました。","voiceIndex":23,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"７０周年というのは今年しかないわけですから、来年以降そういうことを例えば土日で開催できるように努力してということは言いにくいことなので、それは言いませんけれども、しかしやはり区民の皆さんと品川区の歴史を振り返って、これからの品川の発展のために自分が暮らしているいろいろな地域の方々とのかかわりも発展させていくと、そういうスタンスで区制を祝っていくというスタンスから見ると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"つる副委員長","kind":"質問","question":"当日何か参加者に記念品的な、持ち帰りできるようなものとかというのは用意してあるのかどうかということと、それから目的の最後のほうにある区全体で祝う機運、これまでも冠事業ということでさまざまされてきた中で、ただ節目の式典でありますけれども、先ほど来話のあった、例えば全体という部分で、恐らくケーブルテレビとかでニュースでの報道というのはあるのでしょうけれども。","respondent":"久保田総務課長","answer":"当日の参加につきましては、私ども前提は事前に申し込みいただいた方というのを基本としていますが、当日の会場の入りとかも考慮しながら、もしそういったことがあれば、そういったことにも対応できるかどうかこれから検討していきたいと考えています。","voiceIndex":26,"id":"exchange-010"}]},{"id":"topic-03","title":"天王洲公園Ｃ面他改修工事請負契約","agenda":"天王洲公園Ｃ面他改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"すみません、支出科目の中で、都市計画費ということで記載されているのですが、今回天王洲公園Ｃ面他改修工事となっていますけれども、これと都市計画費というのがどういうつながりがあるのか、簡単に説明を。","respondent":"秋山財政課長","answer":"予算の立て方の中で、都市計画費につきましては、土木費の中にございまして、その中で公園の改修ということで、公園新設改良費という目から支出していると、そういう関係です。","voiceIndex":32,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"単純に見て、天王洲公園Ｃ面の改修工事ではないですか。そこに都市計画費ということが支出科目で入っているのですが、ちょっと意味がわからない。公園新設改良費とか工事費その他、土木費は分かれていますね。何かどういうふうに理解したらいいのか。","respondent":"中山企画部長","answer":"各課ごとの目みたいなものの設定と、１つ目の項の、どちらかといえば組織をその段階でつくった中に、まちづくりに関するものについては都市計画費という項の名称にして、その中で公園関係もまちづくりのインフラだという位置づけでそういうことにしています。","voiceIndex":34,"id":"exchange-012"}]},{"id":"topic-04","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"債権の放棄については了解をしました。ちなみに、こういうふうに国民健康保険の資格を外れた人は同じように名称としては不当利得ということになるのでしょうけれども、そういうものが発生して、正規の手続でどれくらいの人はちゃんと金額の修正というのをして、どれくらいの割合の人がこういうずっと不当利得のまま通ってしまうのか、その辺もし把握が。難しいですかね。教えていただきたいなと思ったのです。","respondent":"福島会計管理者","answer":"そういった形ということですので、詳細に何％というのはわかりませんけれども、多分それほど多いケースではないのではないかと考えています。やはり全く住所が１年以上わからなくなっているということになっていますので、その辺でご理解いただければと思います。","voiceIndex":43,"id":"exchange-013"},{"speaker":"吉田委員","kind":"確認","question":"だから、確認ですけれども、中にはそういうふうに、もちろん住所の変更というか転出先を知らせないで出ていったということについては手続的に問題があるけれども、海外に行ったりした人で、自分がそういう扱い、不当利得ということになっていることにも気づいていない人もいるというふうに理解してよろしいでしょうか。ちょっと確認だけさせてください。","respondent":"福島会計管理者","answer":"ただ、そこの宛先に送ってもそのまま住所不明という形で、転居先不明で返ってきてしまうということで、１年かけてそれから先も追ってはいるのですけれども、その先がやはりわからなくなってしまったと。そういう形で年数がたってしまったというケースです。","voiceIndex":45,"id":"exchange-014"},{"speaker":"須貝委員","kind":"確認","question":"今の本人の住所確認できないということですが、今マイナンバーが今後ほとんど普及されていくのですが、そうするとやはり名寄せができるようになってくるのかなというふうになってくると、扱い方も変わってくると思うのですが、今後はその住所確認がより確実にできるようになってくるのでしょうか。","respondent":"福島会計管理者","answer":"確かにマイナンバーが完全に機能すれば必ずどこにいるかというのはわかるかと思います。","voiceIndex":47,"id":"exchange-015"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"意見","question":"最初に、どうしてもよくわからないのが、この新公会計制度を導入した後、今までの財務処理を続けるという関係性がよく理解できないのですけれども。もう一回説明していただけますか。","respondent":"福島会計管理者","answer":"国のほうの方針として、現行の予算・決算体系は続けて、それプラス企業手法も取り入れるという形をとっておりますので、品川区独自で全てを企業会計方式に変えるということはできないということになってあります。","voiceIndex":53,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の制度が変わらないということでわかりました。これ、すごくわかりやすくなる一歩が区の資産が明らかになる。品川区は今どういう方向で検討しているのかということと、途中から、試算は既にあって老朽化も進んでいる中で、これから今評価をして減価償却をしていくというと、そのときの評価をどういうふうにしていくのかな。その辺のことを教えていただきたいと。とりあえず、それで。","respondent":"福島会計管理者","answer":"減価償却につきましては、取得価格から何年たっているかというのを計算しまして、それで今は平成２７年度に１回つくってはいるのですけれども、その年までの減価償却を載せた開始時期の資産をつくっていくです。","voiceIndex":55,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"それを今現在は貸借対照表があって減価償却という言葉が出てきているけれども、償却されていないわけですよね、実際に経費としてそれで落ちているわけではないので、その辺を国の制度は残しながら新公会計制度を取り入れるということで、その辺はどういうふうに資産の金額は減らしつつ、それをバランスさせるために現金というか、どういうふうに処理するのか教えてください。","respondent":"福島会計管理者","answer":"それを示すことによりまして、区の資産が今どうなっているのかというのは、その時点でのものがわかるようになるというものですので、あくまでも会計的な手法にのっとって行って説明をしていくというものになってあります。","voiceIndex":57,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、わからないところを教えていただきたいのですけれども、項という部分を多分いじらないのだと思うのですね。編成の段階で課が変わってしまったらどうするのというのもあるではないか。継続性というのがあるのだけれども、今まではさっきちょっと質問が出たように都市計画費か、何かでちょっとくくっておいて、あとは課が横断しているみたいなところもあったではないですか。もしわかったら教えて。","respondent":"福島会計管理者","answer":"これはあくまでも会計的に減価償却がどのぐらいになっているとか何年減価償却になって老朽化がどのぐらいになっているのかという基礎的な材料を提供するのが今回のものですので、それに基づいてほかの部門が、あるいは所管がどうそれを活用して施設を変えていくのかだとか。","voiceIndex":59,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう事項別明細みたいな形は、これでいくとここ、一つずつやっていくということなのだけれども、それももっとオープンにしていこうという考え方なのか、今のやり方と余り変わらないと理解しておいたほうがいいのか、そこら辺はどうなのですかね。もちろん事項別明細までわかるということはないと思うけれども、そういう形はどういう形でお考えかなというところ。","respondent":"福島会計管理者","answer":"最初のほうで説明しましたように、こちら会計の見える化といいますか、説明責任を果たしていくというのが大きな目的です。そういった意味では、よりわかりやすいものですので、こういった決算書もなるべくわかりやすいものということで見える化を進めていこうと思っています。","voiceIndex":61,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"だから、割合でいったら使う頻度が４対６だと、４対６で分けて減価償却していくのでしょうか。民間は同じ施設をだんだん減価償却していくからわかりやすいのですが、その辺どうなっていくのですかということと、あと、減価償却方法は定額法と定率法がありますけれども、これは一般的に定率法でやって、民間と同じような償却年数というふうに考えていればいいのでしょうか。これについてお聞かせください。","respondent":"福島会計管理者","answer":"減価償却率のほうですけれども、そちらにつきましては、やはり国ですとかとの基準等がございまして、それに合わせる形で今検討していますし、全てが１つの方式ではありませんので、それに合わせる、やはり全国共通なものが多いので。","voiceIndex":63,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"私の質問が悪かったのかもしれないのですが、１つの所管では社会福祉、そちらで高齢者福祉で使っていて、もう一つは例えば地域活動の分野でここのスペースを使うというときに、民間って１つの施設は必ず１つということで償却していきますけれども、款が分かれたらそこ、いわゆる一つの施設っておっしゃいましたけれども、出している資金、最初の資金ですか。","respondent":"福島会計管理者","answer":"そういう意味では案分します。施設全体で減価償却して、それを分けていくという形になります。それは減価償却の費用負担につきましても、全部案分です。","voiceIndex":65,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":24622,"voices":70}},{"id":"h29-20170124-14","meetingId":"h29-cm01","date":"2017年1月24日","dateIso":"2017-01-24","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時４０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年請願第１８号、国交省の羽田空港増便計画による「航空機の都心飛行、品川低空飛行ルート計画」の白紙撤回を求める請願","agenda":"平成２８年請願第１８号、国交省の羽田空港増便計画による「航空機の都心飛行、品川低空飛行ルート計画」の白紙撤回を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"意見陳述は必要だと思います。質疑の前にぜひ伺わせていただきたいと思います。そういうときに、こうした機会を退けるというのは、私はあってはならないと思いますので、ぜひ必要だと思いますし、もし必要ないという方は区民の意見表明の権利をどう考えているのかと逆に伺いたいぐらいなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"基本的には従来どおりというような考え方の中で質疑応答等があって、それから意見陳述をどうするかという話だと思うのですが、このタイミングでちょっとそういうことが出てきましたのでどうしようかということで、態度を表明するのであれば、確かに区民の方々の意見を私どももさまざま聞いている中で、これも１０本目でしょうか、同性質の請願ですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-002"},{"speaker":"若林委員","kind":"意見","question":"さまざまな町場においても私どもは皆さんの意見を聞いているところでもありますし、何かここで意見陳述を聞かないということが住民の参加を妨げるとか、そういう意見にはちょっと賛成しかねます。したがって、これまでどおりしっかりとまずは委員会審査を行い、また理事者の答弁もいただきながら審査の後、判断をするということで結構だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"ただ、今この場で決めるというよりは、むしろ審議を行った後に、さらに意見陳述の必要があるかどうかということで改めて議論を行い、その後に、それでは行うということになれば、いつどのようにということで決めていくというのが手続かなと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"審議に入る前にぜひ住民の方のお話を聞くということが審議を深めるためにも必要だと思いますので、審議の前に意見陳述をやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"詳しい騒音や高度などの説明は以前と変わりませんでしたが、前回この委員会でも伺ったのですが、品川区で言うと３カ所しか明らかにしていないのですけれども、せめて目黒駅や大崎駅や立会川駅などの主要駅ですとか、あと八潮団地に関しても高度や騒音について明らかにすべきではないかということでお伺いしましたが、そういったところは特に説明会ではなかったわけですが。","respondent":"中村都市計画課長","answer":"そういったところで、ただ航空機も輸送能力に限界がありますので、今以上に機能を強化して輸送力をアップするということであれば、それに応じた航空機の利用というものは見込まれると思いますが、物理的にはそれ以上のものは無理ですので、この訪日外国人が増えた場合にでも。","voiceIndex":22,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"何というか、品川区、どっちがひどいのか。それはどうでしょうか。ですから、２,０００万人、４,０００万人、６,０００万人とありますが、このうちどれぐらいを羽田空港で賄っていくのか、だって、それを理由にして新ルートをやると言っているわけですから、どうこの増便とリンクしてくるのかというのがいま一つはっきりしないので、そこら辺をちょっと説明していただきたいと思います。","respondent":"中村都市計画課長","answer":"しかしながら、このテロの危険性は少しでも排除していただくように国のほうへは求めていくと同時に、羽田空港の機能強化に関連しても、区のほうからもそういったお願いもこれからしていきたいというふうに考えてあります。","voiceIndex":24,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。都心新ルートのための予算措置を講じたということをまさに書いているのですけれども、伺いたいのは、区は予算措置に対して理解をしているというふうに言っていたと記憶しているのですが、しかし、現在国が示す都心の上の新ルートに対しては賛成していない、理解していないというような説明をされていたと思うのですけれども、こういう立場だったでしょうか、まずその確認をお願いします。","respondent":"中村都市計画課長","answer":"そういったところからいきますと、機能強化に対する理解はあるけれども、上空を飛ぶことに対してはさらなる詳しい説明を求めるという状況です。","voiceIndex":28,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"今の説明ですと、ちょっとさらに一歩進んでしまったのかなと思ったのですけれども、新ルートについても、機能強化はもちろん理解すると。新ルートについては、国からの案が具体的ではない。それでいいということでいいのでしょうか。それというのはとんでもないことだと思うのですけれども、もう一度説明をお願いします。","respondent":"中村都市計画課長","answer":"現在、具体的になっていない現在においては判断ができないということで、これが国から示された案、これがどういったものでも、では賛成するのかというとそういうことではなくて、これは詳しい説明を聞いてからでないと何事も判断ができないという意味です。","voiceIndex":30,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"ですから、計画そのものには品川区は反対表明していないわけですね。増便には賛成していますけれども、新ルートの計画そのものには反対表明はしていないと。一方で、防音工事の拡大などの交渉を進めているということは、この都心ルート計画を進めることにオーケーのメッセージを相手に送ることになるのではないですか。そこはいかがなのでしょうか。","respondent":"中村都市計画課長","answer":"国がその対応策を環境影響に配慮した方策を示すにあたりまして、区としてもただそれを待っているだけではなくて、やはり対策としてはこういったものもありますよね、ああいったものもありますよねというところで。","voiceIndex":32,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"何というのでしょうか、どんどん国のペースにはまっているという感じがしますね。あわせて、こうしたことを進めれば進めるほど、国には品川区は新ルートの条件によってはいいですよ、仕方ないですよというメッセージを既に送り続けていることになっていると思うのですけれども、私の認識は間違っているのでしょうか。","respondent":"中村都市計画課長","answer":"今こういった国の方策について求めているということは、判断材料としてやはり区がどういった対応をしていただけるのかというところを知りたいというところがありますので、これが出たら賛成、あるいは反対、こういった何がなんでも賛成とか。","voiceIndex":34,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"でも、弾力化といったら、ほかに弾力化しなくてはいけないところというのはあると思っていまして、それが前回の請願審議でもありましたけれども、アセス、これだけの大きな区民に対する影響があるにもかかわらず、アセスは今回新滑走路の増設、新設ではありませんので対象ではないということでありますが、大気汚染や騒音などの具体的影響が全く明らかになっていない状況なので。","respondent":"三ツ橋環境課長","answer":"しかしながら、区といたしましても、具体的にアセスと同様のものの実施ということも考えていかなければいけないと考えています。それにつきましては、具体的なものは国からは示されてはおりませんが、区としては求めてまいります。","voiceIndex":36,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際どういう影響があるのかというのを区民が知りたがっているし、それを不安に思っているわけですから、少なくともこの計画自体は、私はさまざまな面からやるべきではないという立場ですが、少なくともやはり計画前に、そういったことが具体的にわかるようなアセス的なものをやらせるというのは、最低限のこれは議会としてもそうだし、行政としても責任だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"時間枠が守られていない中で、住民の方々が自治体に対しても守られてはいないではないかということで、さまざまに強く要望を出しているというふうにも聞いていますし、自治体のほうでも努力はしているけれども、一度できてしまったものについては、時間枠を守らなくても結局自治体が文句を言ってもと言ったらいいのですか、いろいろ要望などを出しても。","respondent":"中村都市計画課長","answer":"そういったところでは、なぜそうなったのかという説明を聞いた上で判断するということになると思いますけれども、時間帯を守らなかったこと、これについては、航空会社、ひいては国の責任だとは思いますが、ただ区としましても、当事者として。","voiceIndex":39,"id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"強く申し入れをするとか、先ほどの説明の中でも強く抗議をするとか、予防するとかあったのですけれども、なかなか強く働きかけをした結果というのが国から今も返ってきていないし、他の自治体でもその成果がなかなか得られていない中で、いろいろ今国は実施前の段階ですから、さまざまに限定的な条件の中でやるのだということをおっしゃいますけれども、それが現実にやってみると。","respondent":"中村都市計画課長","answer":"委員から飛行経路だとか時間帯の話が出ましたが、話を広げるわけではないのですが、その他安全性ですとか、あるいは騒音ですとか、さまざまな問題で国がこうするように今考えているとか、そういった提案があって、これからそれを具体的な提案として考えていくですけれども。","voiceIndex":41,"id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"そのような交渉の仕方というのは、されているのでしょうか。","respondent":"中村都市計画課長","answer":"恒常化するものについては、これは別のまた国からの説明があるでしょうから、それはそれで対応していかなければいけないと考えますが、現時点では国としてはそういう予定がないというふうに考えておりますので、委員のご指摘はごもっともだと思いますけれども。","voiceIndex":43,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"もう１点お伺いしたいのですけれども、このたび品川区内から成田と羽田へのリムジンが新たに運行されました。あれは品川区の上空を飛ぶこととの何か反対給付といいますか、ざっくり言えば、手土産的な要素があってのことだったのでしょうか。","respondent":"中村都市計画課長","answer":"区といたしましては、この羽田空港の機能強化のいかんに問わず、やはり訪日外国人の方あるいは日本国内の方も品川区にたくさん来ていただくということから考えますと、こういった公共交通の施策というのは非常に重要だと考えておりますので。","voiceIndex":45,"id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"羽田については全く空港でほかのものは切り離して議論されているというのは、ちょっとつじつまが合わないのではないかと思いますが、一応確認をさせていただきたいと思います。","respondent":"中村都市計画課長","answer":"今品川区では、観光施策に非常に力を入れております。そういったところと、それから羽田空港の機能強化とは全く関連がございません。","voiceIndex":47,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"観光に力を入れて、リムジンバスが欲しいと言っているのはどの自治体もそうなのですよね。長くなってまいりましたので改めて申し上げます。本当はそもそもこの計画自体、やはり私は品川地区内に非常に大きい影響があるものですから、できればこれは飛ばしてほしくないというのが前提にありますけれども、そうでなくても、ずっとこれを飛ばすのではないということをぜひ強調していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"したがいまして、今時間延長のおそれ、一度認めると時間が延長されるとか、約束が破られるという可能性もありますので、一度これを認めるとなかなか取り返しがつかないことになりますので、この新ルート案、上空を通るというルート案でもって、その時点でもって私は認められないものだと考えておりますので、品川区としても品川のまちの魅力を守る、また区民の安全・安心をしっかり守っていくという点で。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、今現在はまだ国としてもこの飛行経路は決定ではないというふうなことで説明を受けているわけですけれども、決定でないのなら、その方策についてどんなものがあるのか、こういったものを具体的に示してほしいというところで今交渉中ですので。","voiceIndex":50,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"ということと、先ほど述べました都市ランキング、東京の魅力向上ということについても、これは東京都も非常に深い関係がある話ですので、東京都とも連携をとりまして、国に対してまちの魅力にはバランスが必要であると、この新ルート案は、まちの魅力を下げることしかないということで、東京都とも連携をとって、区も国に対して反対の行動をとっていただきたいと考えておりますけれども、以上。","respondent":"中村都市計画課長","answer":"品川区もこの魅力のランキング、そういったさまざまなランキングがいろいろなところでなされていると思いますけれども、これは区もランキングを意識するということではなくて、品川区の魅力をみずからどういったことができるのかというのを考えていく。","voiceIndex":52,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-022"},{"speaker":"渡部委員","kind":"確認","question":"請願審査を今行っているわけでして、これからまた態度の表明等もするのですが、私どもの自民党・子ども未来としましては、基本的にはこの３年前に出てきた情報から若干のＡ・Ｃ滑走路の飛行角度が云々ですとか、どの辺から下げてとかの微調整、また本数等の調整があったにせよ、当初出てきたときからの約束事にいまだ変更がないという認識でこれは続いているのですが。","respondent":"中村都市計画課長","answer":"全くもって委員のご指摘のとおりです。","voiceIndex":55,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"その確認がされておりますので、私どもとしましては態度表明しますけれども、やはり同等の請願・陳情ですので、この間も一旦は継続という形で扱っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"一番最初の第１回目のときには、３日ぐらい品川区でもやったと思うのですけれども、今回は１日だけというところで、やはりまだ品川区民の中で知らない方もいらっしゃるというところでは、１日だけでは、その日に行けなかったら、もう行けないということになってしまうので、なぜ１日だけになってしまったのか、区として複数の日数を求めたのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"このオープンハウスの説明会の中でも、大田区のほうで説明会もありましたが、この安全対策についても、地上からの管制や航空機の整備などのさまざまな方策をとっているという説明がありますけれども、こういったものも確実に実行していただいて。","voiceIndex":58,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"本当に技術革新があって、全く落ちませんということにならない限り、あり得ないと思うのですけれども、そんなことが実際あり得るのかということもありますが、そういった状況の中で、現状を見守っていくということになると、やはり区民への影響が多大なものになっていくと、このまま強行されれば大きな影響が出てしまうと思いますので。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、やはり引き続き国のほうには、提案があってもなお、さらにそれ以上のものを臨んで、可能性のある限り臨んでいくべきだというふうに考えてあります。","voiceIndex":60,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"対策については終わりがないというお話でしたけれども、終わりがないのだと、やはり反対表明して、影響が全くないように現在の海上ルートでやっていくというのが一番いい方法だと思うのですけれども、判断材料を示されたときに反対するということもあり得るのか、改めてご答弁がなかったので伺いたいと思います。","respondent":"中村都市計画課長","answer":"区としてはこういった国の方策をできるだけ詳しく示してもらうように今要望していますので、またこの内容がどういう具体策として国から出てくるのかについては、これは今求めている最中ですので、現在この対応策が出てきたところで賛成ですとかあるいは反対ですとか。","voiceIndex":62,"id":"exchange-027"},{"speaker":"のだて委員","kind":"提案","question":"ぜひ受け入れられないような提案が出てきたとき、区民への影響が多大になるものが出てきたときには、反対表明をしていただくように強く要望しておきたいと思います。そして、委員の皆さんには、この請願にぜひ賛成していただいて、この品川区議会から区民の声を受けて、計画撤回の声を上げていきたいと思いますので、ぜひ採択をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-028"},{"speaker":"若林委員","kind":"確認","question":"１点だけ。飛行時間の課題なのですが、３時から７時でしたか。これというのは、誤解のないように言えば、バスで言うと時刻表みたいなものなのですかね。品川区で言えば、この３時から７時というのは、どこら辺まで法的、制度的に、要するにこの時間以外飛んではだめですよという強制力というのがあるのかわからないのですが、そういう性格のものなのかどうか、ちょっと確認だけさせてください。","respondent":"中村都市計画課長","answer":"逆に、それ以外の時間帯は比較的需要も少ないし、その時間帯に絞れば航空需要とそれから生活環境への配慮と両立ができる到達点がこの結果であるというふうな説明を受けております。","voiceIndex":65,"id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"そこにはルーズであったり、人為的なミスもあるのかもしれませんけれども、そういう約束事をしっかりとお互いが守っていく、守るべき立場の者が守っていくということは、一般的にこれはすごく危機管理として大事なことなので、そういう意味では、そういうあり方というのもあるのかなというふうに議論を聞きながら思ったのですけれども、そこだけちょっと何というのですか、意見というか。","respondent":"中村都市計画課長","answer":"細かい話をしますと、１５時から１９時の飛行時間帯とありますが、前後３０分は切りかえ時間ということで、実質は１５時から１９時、４時間の中の前後を切り取って３時間が実際に飛行時間だというような話もありますけれども。","voiceIndex":67,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"今日、やはりこの請願ですが、１０本目ということで、共産党としましては、請願を採択して、品川区にも国にも区民の意識をはっきり突きつけるべき状況だと認識をしているのです。ですから、議会としましては、こうした状況の変化を捉えて、しっかりと請願を採択して意思をはっきり突きつけなければいけないのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほどの質問の中で一つちょっと聞き損ねていたのですけれども、私ども意見書の中でもさまざまな説明をということを求め、また品川区としても国土交通省に対してオープンハウス型だけではない……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"そうなのですか。いや、皆さん、それにご意見がないのだと思ったのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-033"},{"speaker":"あべ委員","kind":"質問・要望","question":"住民説明会なのですけれども、オープンハウス型以外のものの開催もずっと求めてきたと思うのですが、今回国土交通省から公的に示されているものは、やはりオープンハウス型の説明会で、かつ比較的騒音等の影響が非常に大きいであろうところと、比較的それほどでもないであろうところと、同じだけの日数、時間でとられているということなのですけれども、品川区という非常に空港に近いエリアに対して。","respondent":"中村都市計画課長","answer":"このキャラバン方式の今回の１日の説明会も、また今スケジュールに示されているところがありますので、これが一通り終わってからかもしれませんけれども、またさらに品川区も追加でやっていただくようにお願いしてまいります。","voiceIndex":77,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"品川区としていろいろお願いしているのはわかりましたけれども、結局まだこちらからお願いするだけで、結果としては何かプラスしてというものは何も返ってきていないわけですよね。何で品川区という最もこの計画で多大なる影響を受けるだろう自治体が、他の自治体ほどにも説明機会を持たれていないのか、国土交通省は何でこんなに品川区を軽く扱っているのですかね。","respondent":"中村都市計画課長","answer":"そういったところからいきますと、今回も今現在はこういったスケジュールかもしれませんけれども、これからさらに影響の大きな品川区に対して十分な説明をしていただくように、また国のほうでもやはり十分な説明をすると言っておりますので。","voiceIndex":79,"id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"説明会の回数もそうですし、やはり開き方というのも大きいと思います。国土交通省に要望するときには、やはりオープンハウス型だけではない説明会というのを他の自治体と比べても頻回に行っていくという姿勢をまず事実で見せなければ、品川区として国土交通省が品川区の住民に理解を得ようとしている姿勢とは思えないということをぜひ伝えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-036"},{"speaker":"渡部委員","kind":"確認","question":"私どもも確認しなければならないことは確認させていただきましたし、それぞれ地域の方々からお話も伺っています。今回これだけの１時間２０分にわたる議論がありまして、相当語り尽くされた、毎回やっていますので、特段必要ないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひこの議会の場でも区民の方の意見をお聞きしたいと思うので、意見陳述をやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"この請願にかかわらず、請願者から意見陳述の申し出があれば、それは原則として受けていくというのが私は議会の形であろうと考えています。では、それを本日するのか、決をとった上で、ではある程度ルールをお伝えして、次回以降にするのかというのはまた議論だと思いますけれども、基本的には意見陳述の機会というのは私は積極的に設けていいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-039"}]},{"id":"topic-02","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"Ａ３の資料ですけれども、全体にかかわっているのですが、庁内検討会の最新の状況なのですが、何回行って、どんな議論になっているのか、今後の検討スケジュールについてお伺いします。利用料値上げも盛り込まれていたりするのですけれども、こういったことも含まれるということなのでしょうか伺います。統合、集約を安易に行うべきではないと思いますけれども、どう考えているのかお伺いします。","respondent":"柏原企画調整課長","answer":"先ほども事例を出されました大崎図書館云々の件につきましては、そのエリアという部分が確かにあるところはありますので、例えば今芳水小学校の建替えをしている際に、いわゆる学校で言う図書室ですけれども。","voiceIndex":101,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"図書館ですが、基本は今の数のままということでしたけれども、今区としてはなぜそのような考えを持っているのか、なぜそのような方針なのかというのをちょっとお伺いします。公共施設等総合計画ですが。これは案を出した段階で、委員会として意見を入れる場が、そういうタイミングというのはあるのか、そこら辺のスケジュール的なところを区としてはどのように考えているのかお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"今回は、検討状況というのをお話しさせていただきまして、素案という形なのか、案という形かというのはちょっとどこまで煮詰められるかというのはあるのですけれども、一定程度の形といいますか、方針ができたところで。","voiceIndex":103,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。そこで、そこの部分の質問で、幾つか聞いているわけですが、「公共施設の総量についてどのようにお考えですか」という質問に対して、「今ある全ての公共施設は必要なものであり、現状維持すべきである」というのが３９.５％で、「足りていないと思う」と「増やすべきである」というのが２０.７％、あわせて６０.２％の人が現状維持で増やすべきだと。","respondent":"秋山財政課長、柏原企画調整課長","answer":"補助金のことですが、私のほうからお答えします。ここに書かれていない施設での補助金の入りぐあいというご質問ですけれども、まず庁舎につきましては、こちらは全くございません。これもトータルでのことで、どの施設をどうだという聞き方でありませんので、これをもって一概にこうすべきだ、こうすべきではないというのはないと思いますけれども、こういうお考えがあるというのは数字としては出ておりますので。","voiceIndex":105,"id":"exchange-042"},{"speaker":"あべ委員","kind":"質問・要望","question":"私のほうから幾つかお伺いしたいと思います。このことについては、ぜひ品川区として、これは短期には難しいかもしれないけれども、考えて、それこそ再配置ができないか、何か新しいものができるときに、ちょっと荏原地区の基幹館になるような、あるいは大井地区の基幹館になるような施設のものをつくるということも中期的な発想の中では取り入れていただきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"近くに大きなマンションがあって、上から清掃作業が見えるので何とかしろというようなお声もいただいたりとか、なかなかちょっと難しい件でありまして、単純な整理統合という話ではありませんし、清掃事業がやはり区に移管されて。","voiceIndex":108,"id":"exchange-043"},{"speaker":"若林委員","kind":"質問・要望","question":"簡単に、アドバイザー会議が２回開かれたということで、内容を教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"一つは、主な考えとしまして、施設ごと、各所管でのこの施設の今後の考え方とかあり方、状況を検討していただいたものを、集約といいますか、まとめをしたものをアドバイザーの方々にも見ていただいて、議論いただいたというのが一つです。","voiceIndex":110,"id":"exchange-044"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、この公共施設有効活用プランを、今回公共施設等総合計画に発展させて、新たな計画としてやっていくという、大きなそもそもの眼目が施設の老朽化の問題と、大きくはやはり財政上の問題という二つの、その老朽化の中に再配置であるとか、統廃合であるとかということは細かく入ってくるわけですけれども、大きくその二つが最大の課題として今回の計画づくりを進められているということで。","respondent":"柏原企画調整課長","answer":"今ご指摘いただいたとおり老朽化の観点での再配置等々、これは利用も含めてですけれどもという議論、それから財政上の議論というのは、大きな二つのところでの議論は進めさせていただいているところです。","voiceIndex":112,"id":"exchange-045"},{"speaker":"若林委員","kind":"意見","question":"専門家の方にこういうことをお願いすると、やはり非常にエッジが効くというか、その専門家なりの見地がありますので、そこにずっと当然議論が行ってしまうわけですけれども、今課長がおっしゃったように、品川区民にとって本当に必要なもの、それから財政上の課題、これを本当にどう絶妙にバランスをとっていくかということがまさに私たちの本当に仕事なのかなという思いもありますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"区営住宅のところで、大規模改修に伴って集約化、複合化、バリアフリー化していくということですけれども、私のところにも住宅問題の相談が結構あったりするので、やはり区営住宅、都営住宅がこの間全然増えていないもとで、区の中で増やしていくということも必要なのではないかと思っているのですが、いかがでしょうかということと、やはり区民の中でも、９０％以上住み続けたいというお話もありますから。","respondent":"柏原企画調整課長","answer":"図書館に関しましては、財調云々というよりも、我々の考えでは、先ほども若干議論がありましたけれども、図書館の機能はやはり必要な部分でありますが、区ではやはりそれなりの充実した数といいますか、本の数も含めてあるというような認識がありまして。","voiceIndex":115,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"庁舎のあり方については、一体的に考えていくこともあるということでしたけれども、先ほどの質疑の中でも免震構造のところは平成４５年ぐらいまでもつというお話もあった中で、工事をしたときから考えが変わったということなのでしょうか。地域センターのところで、福祉の部分も機能強化していきたいということでよかったということですかね。","respondent":"柏原企画調整課長","answer":"免震をかけたことによって建物が延命されたというよりは、地震に対する備えを拡充させたというところでありますので、建物が老朽化しているのは間違いありませんので、この老朽化についてどう対処していくのかというのは、やはり考えはこれまでと変わっているものではないです。","voiceIndex":117,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど学識アドバイザーの方との会議の話がありましたが、そこで財政問題も議論されているということでした。その前提となっている以前委員会に出された財政における現状と課題、こういった資料を出して議論されているのかどうかという確認です。","respondent":"柏原企画調整課長","answer":"学識の先生方とのお話は、今委員がおっしゃっていただいた区で取りまとめている今後かかる費用の状況であるとか、そういった資料は当然お見せしまして、その中身を見ながらの検討ということをさせていただいてあります。","voiceIndex":119,"id":"exchange-049"},{"speaker":"安藤委員","kind":"確認","question":"今回はやめますけれども、ここは大事な数字だと思うのですよ。財産にかかわる問題なのでね。なので、ちょっと研究もしていきたいと思うのですが、ちょっと１点だけ。将来のところの８０.４億円のところに、いわゆる減価償却費とか退職給与費というのは計上されているのかどうかだけちょっと確認、質問します。","respondent":"柏原企画調整課長","answer":"この数字の中にはその考え方は入ってございません。","voiceIndex":121,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6022#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":49719,"voices":126}},{"id":"h29-20170125-18","meetingId":"h29-cm01","date":"2017年1月25日","dateIso":"2017-01-25","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"この要望一覧にも書いたのですけれども、文化庁の文化力プロジェクトが内閣官房に吸収されたというご説明を私も受けまして、残念というか、どういう方向性になるのかという不安な気持ちはあります。何点かお伺いしたいのですけれども、委員長、内容についてもそうなのですけれども、大前提として何を目指していくのかというところで、今ご説明があったところも伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区としては、何か手を挙げているものが既にあるのかどうかというところを確認させていただきたい。その中で、これに当てはまるものがあれば申請をしていくのだという考えなのかというところ。そこら辺について整理をしたいので、教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"もう一つは、後でご紹介をするつもりでいたのですけれども、３月４日にパラリンピック啓発講演会というものを実施する予定でございまして、こちらについては、既に認定を受けまして、マークを使用する予定になってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"そこに果敢に挑戦していくことももちろん大事だと思うのですが、先ほど私が申し上げた趣旨というのは、こういうマークに関係なく、先ほどロンドンの１７万件から１８万件をやったという例は認定されたものだけではないというご説明がありましたけれども、そのような形で、品川区としては盛り上げていくという方向性でいいのかを確認させていただきたかった。もしわかれば教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"品川区といたしましては、こういったマークを使おうが使わなかろうが、いろいろな部分で区民の方々が主体となって文化プログラムを展開していただける環境づくり、周辺整備をしていくことが実際には重要だと考えておりまして、このマークにこだわるということではなく。","voiceIndex":9,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、本数がそれなりに出ている。とはいえ、大会間際とか、あるいは大会の１年前とか、大会に合わせてもいいとは思うのですけれども、象徴的なものについては、こういうもので１つとれるものがあるのであれば、ぜひ、それは挑戦をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"提案","question":"これだけの項目、７７番から１０１番まで結構あるわけだから、全部が全部できるものではないとは思うのだけれども、私たちのものとしては、品川区のさまざまな団体や個人に協力をしていただいて、文化プログラムを推進していただきたいと思うわけであるので、こういうことを提案した後、品川区は国や東京都、それから組織委員会の方向を見ながら、もしタイムスケジュールがわかれば。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうしたことが明らかになった段階で、いろいろな町会ですとか商工会議所、商店街連合会等には丁寧に個別に対応し、説明をしていきたいと今のところは考えている状況です。","voiceIndex":12,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"気運醸成という観点からすれば、非常に大切なことだと思うのです。そちらのほうが、実は品川区にとっては大きな方向性だと思うのです。私としては、こういう要望を議会からさせていただいたけれども、むしろ、そういうことを総合的に判断してまとめてあげていくことのほうが品川区の責任は大きいと思うので、頑張ってくださいということと、改めて、その方向性だけ教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"まだ明らかにお話はできませんけれども、そういったことも、組織委員会の動きを待つだけでなく、区としてもいろいろな検討はしているということで、ご理解をいただければと思います。","voiceIndex":14,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"大枠だけでも知りたいと思っています。どれだけのものが出せるかはわからないけれども、これからの議論ですが、そういう方向も持っているのかどうか、そこを確認したいと思ったのです。先ほどの冒頭の委員長のご説明では、そういう方向性があるのかと思ったのですけれども、改めて、これの扱い方をもう一度、確認させていただきたいと思います。","respondent":"鈴木文化観光課長、渡辺委員長","answer":"並行しまして、区内の文化芸術関係の団体の皆様にお集まりいただきまして、今後のそれぞれの団体の活動や、オリンピック・パラリンピックに向けた文化プログラムへご協力いただける内容についての意見交換や懇談会のようなものも。効果は、もう既に南委員のご発言同様、要望として区では受けとめていただいて、検討に入られている部分も多々あると思います。そういう意味で、項目でまとめることで、施策に反映させやすくする。","voiceIndex":16,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"区でも、もちろんそれなりに進んでいるということは思ってはいたけれども、どこまで、どういうものがというのが全然わからないまま、こういうものを議会だけでやっていっても、のれんに腕押しみたいな感じがしたので、質問をさせていただきました。ぜひ進めていただきたいし、できるだけ幅広い方が、それぞれの力に応じて参加できる状況をつくっていただきたいということを改めてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"提案","question":"都民も品川区民もそうだと思うのです。長くなってしまいますけれども、例えば識者の方で、こういう提案をしている方もいるのです。これは１つの例です。それをしてくださいと言っているわけではないですけれども、まさにそういう区民参加型のものを品川区として提案をしていただきたい。これはこれからの話だとは思いますが、もし、今の話を聞いて何かお考えがあれば教えていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それが開会式に合わせられるかどうかということもありますけれども、ロンドンでもいろいろな取組みをされておりましたので、そういったことも踏まえて、区としては、これからまさに検討していきたいと思っているところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"質問というよりは提案だったのですけれども、今やっているものを、情報を集めて、集大成としてカウントしていくというのも１つだとは思うのですが、新しい、全員が参加できること、区民が参加していくというところがやはりオリンピックの魅力だと思います。それは終わった後のレガシーという面でも、そのほうがいいと思うのですけれども、その点についてのご意見を伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"来年度も、もう既に企画が始まってありますが、品川の文化プログラムの中に入れて、上手にオリンピック・パラリンピックの文化プログラムの流れにも合う形で、ぜひ進めていければと考えているところです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"いながわ委員","kind":"提案","question":"あくつ委員のご質問とご答弁をお伺いしていた中で、１点、提案です。そういうものがあれば、逆に言えば、何か提案がなされたときに、上の３つだと規模が大きくなってしまうので、品川区でできることは品川区でやろう的な、そういった組織、感覚もあったほうがいいという思いがします。それは要らないではなく、１回、ご検討をしていただくことも大切だと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘の品川区としての独自の展開につきましては、今まさに検討をしているところでございまして、今日は、こちらの中に品川区という段を設けることはできなかったのですけれども、そういった認識は十分あります。","voiceIndex":24,"id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"五輪のものもあるのでしょうか。そうしたものを、品川区内であれば、防災行政無線で流して、一斉に３８万区民で踊るとか。これは提案になるとは思うのですが、そうしたことも必要だと思うのです。みんなでそういったことを共有する。１つの目的を持ってやるということは、何かしらいいのではないか。提案ですけれども、もし何かご意見をいただければ、ご答弁いただければと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘の大きな一斉にできるようなイベントといった部分につきましても、既に視野に入っているところです。しながわ音頭のそういった活用についても、十分認識しています。そうしたご提案の趣旨を踏まえて、活かしていきたいと考えています。","voiceIndex":26,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"やり方というのは、当然、主になっていただく品川区でしっかり考えていただきたいのですが、先ほど申し上げたとおり、しっかりと記憶にも残るという部分も、例えばそれがギネス認定されるとか。ですから、そういったことも関連付けながら、さまざまな形で、とにかく１人も残さず、区民の方がそこに参加できるということを何か１つ、しっかりと考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"それはそのとおりだ。いろいろな可能性がある中で、障害者の方々の表現はいろいろあるはずです。その中の１つにあるわけであって、私たちがすごく思うのは、そういう方々のいろいろなものを見た上で考えていくのであればまだわかるけれども、１つの例として議論するのは構わないけれども、品川区の方向性がその方向でいってしまうのは、ちょっと早いのではないかという気がするのですが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"ですから、できるだけ幅広く、その中で障害のある方たちがどういうところに興味、関心を持って、身近な地域でそういった活動が楽しめるか、そういったところも十分考えながら進めてまいりたいと考えております。","voiceIndex":29,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"誤解がないように言っておきますけれども、アール・ブリュットを否定しているわけではないのです。だから、それを広い目で見ていただいた上で考えていっていただきたいという観点です。決してアール・ブリュットを否定しているわけではなくて、１つの要素としてすばらしいものだとは思うのだけれども、今の時点で、品川区がある程度、方向性を持っていくのは、まだ早いと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もちろんオリンピック・パラリンピックは障害者だけのものでもありませんし、さまざまなことを検討していただいた上で、今、品川区が取り組んでいる中で、それをフィーチャーしたというところで、先ほど私は質問させていただいたのですけれども、言っている趣旨は伊藤委員と一緒です。別にそこにこだわるとか、それだけということではありませんので、そこは委員の皆様にもご理解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"１０１番のところにもありますけれども、区民へのアンケートで、文化芸術に関心があるという方が７割いる。これは平成２２年の調査ですけれども、こうした関心がある中で、どこまでできるのか、時間も場所もないということで、環境整備がやはり必要だと感じています。オリンピック憲章のところと環境整備のところではどうお考えなのか伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"環境整備につきましては、もう既にスポーツ施設ですとか文化施設については、区の中でもいろいろ整備はしているところではありますけれども、まだ不十分なところにつきましては、これからまた、そういったことを踏まえながら、所管に相談して進めていきたいと考えています。","voiceIndex":33,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"確かにオリンピック憲章というところでは、わかりやすく、親しめるような伝え方というのは本当に大事だと思いますので、広くそれを伝えていっていただけたらと思うのです。環境整備のところですけれども、今、区民がどういった状況なのか。その上で、環境整備で何が課題かというのがあると思うので、そうした調査やアンケート等の実施を要望したいのですけれども、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"広報の区政モニターですとか、そういったチャンスがあるところにつきましては、これまでも調査をかけてきたところです。その結果を踏まえて、いろいろな次の展開に向けてこれまでもやってきたところですので、そういったことで、今後もやっていきたいと考えています。","voiceIndex":35,"id":"exchange-018"}]},{"id":"topic-02","title":"オリンピック・パラリンピックの推進に関すること","agenda":"オリンピック・パラリンピックの推進に関すること","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"私どもも出させていただいたのですが、ほかの会派の方のところで、あまりなじまなかったので、質問という形で伺いたいと思うのが何点かあります。その３カ所を説明していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"カット日は、コンテナヤードはそのままで、ヤードのカット日なので、締め切り日ということで、そのときにコンテナが集中するので、そうすると空シャーシもあるし、出入りがあるので、輸出と輸入があるので、すごく混むという認識があるので、それに付随するのであれば、そういった並んでいるトレーラーの最後尾には、少なくとも警備員をしっかり配置していただきたいという部分も、ついでに言ってしまいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-020"},{"speaker":"南委員","kind":"提案","question":"わかりました。毎日ではないのですが、ひどく渋滞するというのが、そういう輸出入との関係で荷が集中したときに非常にと。それからあと、１８項目の八潮のところの「近隣住民の利便性が損なわれることがないよう」というところは、私どもが以前出した記憶があるのですけれども、ここをもう少し盛り込みたいと思ったので、新たに提案をお許しいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"だから、委員長の仕切りになってくるのでしょうけれども、「八潮地域の新駅設置や３５７号線は整備しないこと」と言われても、やってしまっているのだから、それをここで書くのはどうなのかというところ。３３番、「ボランティアの参加が押し付けにならないように努められたい」とあるのだけれども、先ほど課長が説明されたボランティア戦略にどう書いていますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-022"},{"speaker":"いながわ委員","kind":"提案","question":"先ほど都市計画課長からご説明いただいた、輸送連絡調整会議の概要についてというところで、１点、確認なのですけれども、品川区としてはどういう立ち位置で出席をされているのか。そして、例えば、ここで３５７号線の話とか、いろいろご提案をさせていただいている中で、品川区がその調整会議で意見を述べたときに、きちんと受けとめて、それを前向きに考えていただける組織なのかどうなのか。","respondent":"中村都市計画課長","answer":"そういった中では、やはり決定することがなかなかできない会議だということで、今回、組織委員会に事務局が移りまして、これは２回目ですが、今後、具体的なものが組織委員会の責任において、いろいろ決定されていくものとして期待をしています。","voiceIndex":48,"id":"exchange-023"},{"speaker":"いながわ委員","kind":"提案","question":"ぜひ、この中項目にある３５７号線、いろいろご提案をさせていただいているのを受けとめていただいて、要望していただきたいと思います。それが３５７号線が開通すれば、比較的すくという話なのですけれども、本当にすくかどうか。逆にいえば、期間中だけでも構わないですけれども、トレーラーが搬入する側はこちら側にという提案もぜひしていただきたいと思うのですけれども、そういうのはどうでしょうか。","respondent":"中村都市計画課長","answer":"ただ、オリンピック・パラリンピックのときもさらに混雑が、そういったところで影響はあるかもしれませんけれども、恒常的な混雑につきましては、オリンピック・パラリンピックの会議の中で意見を言うことも重要かもしれませんが、また別のところで、交通の施策という観点からも。","voiceIndex":50,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"多分、私、繰り返し質問をしていると思うのですけれども、１７番の項目で、特に専用レーンと優先レーンということで、その情報の提供というのがすごく大事だと思っています。そういうのが私は必要だと思っていて、そのためには早い情報提供がどうしても必要だと思うのです。その辺が、事務局がかわったというところで、輸送連絡調整会議の中でイメージが出されたのかどうか、教えていただきたい。","respondent":"稲田都市開発課長、中村都市計画課長","answer":"私からは、リオの視察で得た知見からご説明いたします。報告書の５６ページの専用レーンは、リオの場合、緑色で路面に表示をしてありまして、ここを大会関係者の専用のレーンとして通っていると。ただ、これが２４時間かというと、例えば昼間の開催時だけとか、そういった時間で区切って規制をされるのか、その辺はまだ今後の検討になると思います。","voiceIndex":52,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"専用レーンです。これからということだと思うのですけれども、罰金を設定するとかは、また警察とかいろいろなところが絡んで、罰金が日本の国民になじむのかどうなのかということもあります。ぜひ、もしそういうことであれば、その施策が早く皆様に情報提供されるように働きかけていただきたいと思います。ですので、ぜひ、きちんとスケジュール感を持って進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-026"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これがシャトルバスになるのか、どうなのか。ただ、今はまだ２回目ということなので、これからもっと詰めていかなければいけないと思っているのですけれども、その辺のところをお聞きしたい。本大会は江東区内で開催されるということをお聞きしておりますけれども、これもオリンピック競技になったので、公園課と連携しながら、来年度、そういった啓発活動をお考えになっているのかどうかお聞かせください。","respondent":"中村都市計画課長、池田スポーツ推進課長","answer":"ただ、キャパシティの関係で、これで十分足りるという話になると、なかなかそういうところは難しいと思いますが、その辺は今後の検討の内容と調査の報告を待つということになると思います。スケートボードにつきましては、来年度、八潮北公園で建設をする予定になってございまして、運用の仕方につきましては、今は検討をしているところでございまして、当然、オリンピックの競技種目になってありますので、いろいろな面で。","voiceIndex":56,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"提案","question":"何を言いたいかというと、例えばオリンピック開催期間中は東京都と協力をして、荷物の積みおろしのルートを変更してもらうとか、それから、一定のエリアには入れないということはできないかもしれないけれども、おそらく東京湾からの荷物の積みおろしをしなければいけないでしょうから、要は、あの周囲を通らないようなルートを、まさに先ほどお話があったように委員会で提案をしていただいて、十分。","respondent":"中村都市計画課長","answer":"会場への競技本番のときの輸送を考えたときに、まず、選手村から湾岸道路を通るルートが選定された場合、実際、高速道路を使うとすれば、選択肢はそれしかないのですけれども、そうすると、東京港トンネルをくぐって品川へ出てきて、そのまま３５７号線をずっと南下してきて。","voiceIndex":59,"id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問","question":"ただ、相手があることですし、それから、幾ら大会期間中とはいえ、経済活動をとめるのはなかなか難しいのはわかるのだけれども、はっきり混雑していることはわかっているのだから、もう少し、課長、強く言ってほしいと思うのですけれども、いかがですか。","respondent":"中村都市計画課長","answer":"組織委員会では、輸送計画に関しまして、近隣周辺への影響を最小限にするように検討をしていくと言っておりますので、委員ご指摘のとおり、そういったところを区も強く申し入れをしながら、組織委員会に進めていっていただくようにしたいと考えております。","voiceIndex":61,"id":"exchange-029"},{"speaker":"いながわ委員","kind":"質問","question":"気運醸成で、改めてなのですけれども、例えば外国人へのおもてなしという部分を品川区としてはどうお考えかというのをお伺いしたい。そば屋もそうです。日本に来ているのだから、日本の風習を理解して来てくださいというのか、それとも、日本人があえて、いらしていただいた外国人観光客に合わせるべきなのか、そういう部分で、やはり施策とか事業の展開も変わってくるような気もするので、もし何かあれば。","respondent":"河内協働・国際担当課長","answer":"一律の答えはないかと思うのですが、そういったことをやることによりまして、また、我々日本人の信頼も上がっていき、我々日本、ひいては品川に来てよかったというところで、温かい対応をしていくことが大事かと思っています。","voiceIndex":64,"id":"exchange-030"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これというのがあったとしても、１品、品川巻きが本当にそうかどうかは別にしてもです。ですから、そういうのを創出していくことも必要だと思っているのです。もちろん、これから先、外国人観光客が増えてくるオリンピック・パラリンピック以降も、そのお土産はツールとしてずっと使えるわけですから、その辺をどのようにお考えなのか。お答えできる範囲でお願いします。","respondent":"鈴木文化観光課長","answer":"ただ、ご指摘にありましたように、新しい土産となる商品の創出とかは、基本的にやはり民間事業者の方の自主的なアイデアとか取組みの姿勢が必要ですので、行政はそれを支援して、完成したものは大きくＰＲするというのが役割分担だと考えております。","voiceIndex":66,"id":"exchange-031"},{"speaker":"いながわ委員","kind":"質問・要望","question":"永谷園でも、今回、お茶漬けを買うと、五十三次のカードが付いてくるなんて販売をしています。これから旧東海道を盛り上げていかなければいけないという思いがありますので、そういうのも含めて、呼び水を出さないと、やろうか、やらないかとちゅうちょしている方もいらっしゃると思うので、そこは所管の判断でしっかりやっていただきたいと思います。","respondent":"鈴木文化観光課長","answer":"そこに関しては、そういう地域でのアイデアや新しい事業の提案をいただいたり、また逆に、区で観光のツアーを組むときにご協力を呼びかけてということで、ご指摘があったところについては、ほかのエリアに比べると比較的進んだ取組みがされているところですので。","voiceIndex":68,"id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"まだ３年後と言いながらも、もうすぐ来てしまいますので、ぜひ、そのあたりをわかる範囲で教えていただきたい。僕は今、限定的に清掃と熱中症対策ということで質問させていただいていますけれども、想像力の中でいろいろやっていただきたいと思うのですが、今わかっている範囲、課長が考えているところで、何かご答弁があればお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"東京水のことですとか、背中にしょって紙コップにつぐとか、具体的なご提案もありましたので、そういったもろもろを踏まえまして、清掃や熱中症対策だけに限らず、観客の方をいかに品川区の中に誘導していくかというようなこと、また。","voiceIndex":70,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"品川区が決めることではないのですけれども、９万人のボランティアを確保するというのは、かなり大変な事業ではないかと思っているので、その辺について、どういうふうに捉えているのか、お話を伺いたいのです。条件整備をどういうふうに進めていったらいいのか。その気持ちが大会を成功させる１つの部分にもなってくるということで、その辺の考え方を改めて伺っておきたいと思っています。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ちなみに、ロンドン大会は、大会ボランティアが約７万人、都市ボランティアが約８,０００人ということで伺っております。大会成功に向けては、ボランティアに最大限活躍していただく必要があるということは十分認識しています。","voiceIndex":72,"id":"exchange-034"},{"speaker":"南委員","kind":"確認","question":"わかりました。そういう実績を見たときに可能だろうということなわけです。繰り返しますけれども、そういうところがあって、成功すればいいと思っているのですけれども、なかなかそのあたりが見えなくて、私ども、３３番のところでは、「押し付けにならないように」という形の表現をとらせていただいたのですが、そういう心配はしなくていいということで受けとめていいのかということを１つ、最後に確認です。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区といたしましても、今年度から、しながわサポーターということで、企業や団体の方々に、スポーツイベントを中心にボランティアの団体を募っておりまして、今、約９団体に既にお申し込みをいただいて、これからどんどん活躍をしていただこうと考えているところです。","voiceIndex":74,"id":"exchange-035"},{"speaker":"南委員","kind":"意見","question":"もう既にそういうことが予想されるし、たまたま大井ふ頭中央海浜公園のホッケーの会場の競技開催日とバッティングしないのであれば、それはそれでいいのですけれども、そういうことも予想される中では、やはりできるだけ早いうちにそういうことについて対応してほしいという声は伝えていったほうがいいのではないかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-036"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今お話にあった各派要望まとめの区内競技場周辺整備の１番に絡んでくるところなのですけれども、先日、スポーツ協会の情報誌の新年号の件でご指摘をいただいたところがあるのです。最初に言ったホッケーグラウンドの件に関しては、多目的な利用をこの委員会でも要望していますし、さっき言った１の中には区民の優先利用ということも考えるとある。かわったのか、教えてもらえますか。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"会長も、確かに大井ホッケー場につきましては、多目的で利用するものであることをご認識していただいたところです。東京ホッケー協会につきましてご説明をいたします。","voiceIndex":79,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"両方ともわかりました。バスケットでしたか、何かトラブルがあったのがあったけれども、ホッケー協会はその辺のところがなければいいのだけれども、品川区として対応をうまくやっていただきたいと感じました。たしか濱野区長が名誉会長か何かになっていたのは一般社団法人でしたか。そこら辺の関係もどうなるのか気になったところなのです。お願いします。","respondent":"安藤文化スポーツ振興部長","answer":"すぐに協会の局長を呼び出して、指摘をして、正確にこれは表現をするべきだということで、早速、会長にお電話をさし上げまして、実際に報告をして、経過も一応、説明して、我々がかち取ってきた多目的だというものもお話をさせていただきました。","voiceIndex":82,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前の平成２６年のときに、野球場の代替施設の確保を求める署名では、自民党とともに私どもも協力をした経緯があります。いろいろな経緯があって団体がかわったというところもあると思うのですけれども、先ほどご答弁があったとおり、軽く捉えることなく、訂正をしていただくなり、これはしっかりと対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":47567,"voices":88}},{"id":"h29-20170127-10","meetingId":"h29-cm01","date":"2017年1月27日","dateIso":"2017-01-27","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会報告会の実施","agenda":"議会報告会の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう１点目が、議員個人の見解は述べないと、ここでは委員会の報告についてのことではありますけれども、ワークショップで参加者から、あなたはどう思っているのですかと聞かれて答えることもあるし、それがまた双方向型にもつながってくるので、双方向型は大事かなと思うのですが、とりわけ参加者は、いろいろ意見をお持ちだったり、地方自治への意識が高かったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"７番目の一番初めですけれども、「全議員参加による実施とする」とありますが、前回１月２３日検討会において、我が会派、維新・無所属品川としては、この趣旨に対して賛同できないので、今のところ、参加いたしません。そして、我々は常々言っているのですが、賛同者のみの参加ということで、その場でも、検討会でもきちんと皆さんの前で報告しましたので、それだけは明確にさせていただきたいと思います。","respondent":"鈴木（真）委員長","answer":"検討会の話で、議運に出てきているのは、検討会でまとまったということで来ているので。","voiceIndex":29,"id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"ええ。いや、申しわけありませんけれども、全会一致ということではないので、これはまとまっているという趣旨で記載されていますが、あくまで違うので、それだけ、今日は明確に、ここできちんと言っておこうかなと思いまして、今、発言しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-003"},{"speaker":"たけうち副委員長","kind":"意見","question":"この立場で言うのも何だけれども、前回の議会改革検討会で、須貝委員の会派のご主張に対する結論については、そこでは出さないということになっておりました。それは事実としてお伝えしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"確認","question":"再度、ここの検討会で確認をしたときには、これはこれで、この前の検討会は、今後の部分について、いろいろな組織替えをしていく、またそれをいろいろ分けていく、それについては希望者だけでというお話もいただいたのはもちろん理解していますけれども、それについては座長の中で、１回、そこの部分、今後のことについては、それはそれで棚上げにして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-005"},{"speaker":"須貝委員","kind":"確認","question":"これは前回の検討会でも確認はしましたが、今年３月で２年間の検討会の期間が終了ということなので、そこまでは我々も賛同したということで皆さんと一緒にやっていくという義務はあると思うのですが、今度、それ以降のことになりますので、これは５月の話なので、それに対してはうちの会派としては全議員参加による実施というのは賛同できないということをやはり明確に言っておかないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこの部分については継続してやっていきましょうという確認はとれているわけであって、それ以降の話は棚上げというのは、私も先ほど来何度も言っているけれども、この件については、それ以前にメンバーもその形で実行委員会に移行しながらやっていって、では、そこについては実行委員会方式でやっていきましょうという確認はとれているので、文章もここで変わっているわけではないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"別に実施することに反対は何もしていないので、ただ、今回の議会報告会に対して、我々としては考え方、趣旨には賛同できないので、期限も２年という区切りの中で進んでいるわけですから、今度、名称も変わるのでしょう、だったら、賛同できる方たちだけで今後運営していっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これも全会一致で、だから、議運はちゃんとしっかり議論をするという場だから、別に議運で新たな話をされるのは構わないけれども、それは別にここは議運の場なので、それは必ずここを通すということになっているからいいのだけれども、須貝委員の今のお話は、須貝委員も委員であるので、先ほど来、１２月にはこれを出させていただいて、議会報告会の日程も決まって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"来年度以降の新たな会議体については、これはまたいろいろと議論の余地が確かにあるだろうと思っています。ただ、一方で、来年度以降のところで、例えばこれまで積み残しになっている報酬の話とか身分の話とか、そういうことが議論される余地も十分にあると私は思っているのですが、そこは最初から須貝委員は加わらないという宣言で、議会改革にはかかわらないということでよろしいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"逐一、やはり翌年度までかかわるものもあるだろうということも察して、うちの会派としてはやれません、賛同できませんということは何度も何度も申し上げておりますので、それを石田秀男委員は、いや、須貝委員はこう言ったと言うのだけれども、話した本人が言っていないと言っているのですから、賛同できないと言っているのですから、それは自分自身、何も嘘偽りないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"それが僕らの果たすべき役割でもあるのではないかと思います。ですから、それをここでどうこう議論する話ではなくて、これでやりますよというのは、もともと２年の約束の中でやっているわけだから、それはやるべきではないでしょうか。","respondent":"鈴木（真）委員長","answer":"いろいろご意見をいただいていますが、最初に言った１月２３日の議会改革検討会の中で出た資料ということで、まとまった資料ということで、この議運に諮っている。","voiceIndex":42,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"明確に２年間というお話で進んできて、それで流れてやってきたのですから、やっぱり趣旨に合わなければ、それはどうしたってしようがない。それを無理に言って、そこでどうするのですか、そこでもめごとが起きてもしようがないのだから、それに賛同する方たち同士が集まって実行していくことが本来の議会改革検討会ではないかなと、また、議会報告会ではないかなと私は思います。は堂々めぐりなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、ちゃんと丁寧に、この前も確認、その前、１２月の検討会の前も藤原議員にも確認して、全会一致でこういうことなのだから、藤原議員、それでいいですねと何度も確認をして、藤原議員もそれでいいとおっしゃるから、では全会一致で出するといって、１２月１６日の検討会で話させていただいて、最終的にはこれを議運に出して実行していくことでいいですかという座長の諮りがあって、そのときには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-014"},{"speaker":"須貝委員","kind":"確認","question":"それはきちんと明確に、分科会をやって、その後、検討会で再確認して、どうですかともう一度やります。そこで明確に我が会派は反対だということは何度も何度も申し上げています。これを実施するという、皆さんがやることに対しては問題ないのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"正副で早急にタイムスケジュールを出していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5208#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":16779,"voices":65}},{"id":"h29-20170206-10","meetingId":"h29-cm02","date":"2017年2月6日","dateIso":"2017-02-06","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"要望書（案）","agenda":"要望書（案）","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ここに書いてあるとおり、分娩可能な病院が区内に３つしかないうちの１つであるということとか、あとネウボラを受けとめてくださっている病院であるという意味においては、本当に今後のこと、心配が広まっていると思いますし、地域的に都南病院がなくなった後でもあるということで、関心が高いので、ぜひ、本当にこの要望が届くようにしていきたいなと思っているのと、１つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-001"},{"speaker":"あべ委員","kind":"質問・要望","question":"幾つか、若干。以上は表現の問題なのですけれども、要望の内容として存続を要望するというだけでいいのか、それとも情報提供ですとか、存続ももちろん要望内容なのですけれども、情報の提供と存続、それから医療機関として何らかの形で存続をするというところも含めて考えていくべきなのか、それはまだ少し早いのか、その辺も感じるところであります。","respondent":"大沢議長","answer":"今のあべ委員のご指摘ももっともですけれども、いずれにいたしましてもタイムリミットのあることでありまして、非常に緊迫している、時間的な余裕が、もう今ないような状況ですので、今後これ、最初の要望だけで済むとは私も思っておりませんので。","voiceIndex":12,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"よろしいですか。すごくよくできている要望書ではないかなと私は思います。あまり踏み込むと、またそれは変な話になるし、こうやって、このように我々心配しているということで、強く存続を要望しますで、すごくまとめ方もいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"現時点でこの文章で、この先のことも確かにありますけれども、今はまず東芝に先に求めるということで、この文章でいいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5210#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":3433,"voices":26}},{"id":"h29-20170221-10","meetingId":"h29-cm02","date":"2017年2月21日","dateIso":"2017-02-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他の(2)東京都後期高齢者医療広域連合議会の報告","agenda":"その他の(2)東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今日ご報告いただいた議案の中に入っているかどうかよくわからないのですけれども、特例軽減について、７５歳以上の方で低所得の方の保険料軽減の中身、いろいろ措置があるのですけれども、この間ずっと特例措置をなくさないでほしいという意見があちこちで出ていまして、私たちもぜひそういった発言をしていただきたいと思っておりましたけれども、この間の議会で特例軽減のことが議論されたのかどうか。","respondent":"本多議員","answer":"広域連合が２３区宛てにどういう方法がいいかということをアンケートしまして、全部２３区が回答した資料がその議案説明に入っていまして、それをもって対応をしていくということなので、その資料をまた、今、手元にないのですが、事務局のほうに置いておきますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼副委員長","kind":"質問","question":"この特例軽減については、行政のほうでも、課長会の中でもなくさないでほしいという申し入れとかもされていると思うのです。その資料に書かれているということは、結論が出ているという捉え方でよろしいですか。","respondent":"本多議員","answer":"まだ決定はされていないです。方向づけは出ているのですけれども。","voiceIndex":7,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5212#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":12150,"voices":40}},{"id":"h29-20170224-3","meetingId":"h29-c-budget","date":"2017年2月24日","dateIso":"2017-02-24","committee":"予算特別委員会","time":"午後 ３時２５分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1052#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1969,"voices":17}},{"id":"h29-20170227-6","meetingId":"h29-cm02","date":"2017年2月27日","dateIso":"2017-02-27","committee":"区民委員会","time":"午前１０時００分～午後 ０時２３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１９号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第１９号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"何件かお伺いしたいのですけれども、今、既に品川区で事業としてやっているのが、事業承継センターが港区にあって、そこでいろいろ事業承継について相談を受け付けるという制度があったと思うのですが、これに関連してなのですけれども、大体、そこに相談に行く方はどれぐらいいらっしゃるのかということが１点。","respondent":"山崎商業・ものづくり課長","answer":"事業承継の支援事業につきましては、来年度以降も継続した区の公的な産業支援の一番基本になる領域だと考えていますので、一定程度、この事業については、これからもずっと基本的な施策としてやってまいりたいと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"この間、区民委員会の行政視察で、札幌市の商工会議所の中にある北海道事業引継ぎセンター承継を視察させていただいたときに、非常に熱心にやられていて、それは商工会議所のＯＢ、名士、その人たちが相談に乗っていただいて、どこまでやるのですかと言ったら、銀行の窓口まで行くと。","respondent":"山崎商業・ものづくり課長","answer":"品川区の事業承継支援資金をつくる段階で、信用保証協会とも密に連携をしながらやらせていただいて、より機能する融資制度であり、事業承継支援事業であったりということで努めてまいりたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"保証協会が出さないと言えば銀行だって出さないわけですから、そこをしっかり連携して、メードイン品川ではないですけれども、しっかりこの制度が機能するようにしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のやりとりで、いろいろきめ細かく対応することに努めていきたいというご説明はあったのですけれども、なかなか中小企業の経営も厳しいですから、ぜひ、そこはひとつよろしくお願いしたいと思います。新たな融資の設置と事業活性化資金と団体資金の拡充については歓迎します。先ほども少し、前年度からの流れもありましたけれども、伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今回の融資の周知も含めまして、それから、私ども、中小企業の皆様向けの新たな取組みをする、別の事業のＰＲも含めまして、全体として、基本的にはシルバー人材センターでポスティングをさせていただいている産業ニュースの配布でありますとか。","voiceIndex":10,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"２点伺いたいのですけれども、この事業承継支援資金の申込要件が２つありますけれども、事業承継計画の策定であったり、あと事業計画の策定であったり、この計画そのものが中小企業の方にとっては非常に難しいと思うのです。そこが立てられないから、一歩が踏み込めない部分もあるかと思うので、そこへの支援の仕組みというのはどうなっているのか伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"廃止する転業資金につきましては、実は１２種類の融資があって、いろいろその融資ごとに、年度別に、大体１,５００件ぐらい融資の年間申込みがあって、どの融資が何件使われているのかという分析を毎年するわけなのですけれども、転業資金と申しますのは昭和の時代につくられて。","voiceIndex":12,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"転業資金が廃止されても実質問題はないというお話で、冒頭の説明でも、代替となる、いろいろな融資の活用がありましたけれども、やはり今あるものがなくなるというのはどういうことかとは思いますので、転業資金の廃止にかわる融資や組み合わせ、日々の業務の中で実際の中小企業の判断とか、最後にもう少し、何かその辺の具体的なメニューや事例をご説明いただけますか。","respondent":"山崎商業・ものづくり課長","answer":"こちらの融資は、もちろん先ほどの３年間無利子というフレームは一緒なものですから、小規模の事業所であれば、まず、今ご説明の融資を借ります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"もう一つは、売掛金で、オーナーがかわったら、お子さんだったら現金でと。そんな信用がない中小企業で逆にどうするのですか。融資の問題よりも、ほかのところで問題があるのではないですか。２つの例を挙げてくれたのですけれども、この程度のことで新設をわざわざすることがある、どうしてもしたかったのかというのがわからないのですが、その辺についてお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"事業効果につきましては、先ほど冒頭のように、一定程度、統計的に企業の経営者の高齢化が進展している現状に鑑みれば、必ずしっかり効果はあるものだと思って、この事業を継続して取り組んでまいりたいというのが区の考えです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"さまざま今、議論がされて、何となく理解はできたのですけれども、転業資金の廃止についてもお話を伺って、理解できたのですが、さっき手にしていた資料の配付をしてほしいなと。どうでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"パンフレットはありますので、後ほど配付させていただいて、対応するとともに、委員会資料については、いろいろ対応、検討します。","voiceIndex":18,"id":"exchange-008"},{"speaker":"本多委員","kind":"意見","question":"もう質疑で十分、やりとりでいろいろわかりましたので、意見だけ述べします。先代の社長がこういうものにアンテナを立てて、後継者にこういうのがあると言うのも大事ですけれども、後継者が自分からアンテナを立てて、経営者として生き抜く力を、それを支えていただければと思いますので、よろしくお願いします。","respondent":"石田（し）委員長","answer":"先ほど田中委員から資料要求があったのですが、委員会の資料に関しては、我々、正副で取り決めをして、お配りをすることになっていますので、我々で、出す、出さないも含めて判断させていただいて、後ほど渡すのであれば、我々から資料要求させていただいて。","voiceIndex":20,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"賛成とともに、要望を１点。先ほどの質疑をお聞きして、よくわかりました。いろいろと先ほどのお話で、個別にご案内をしていらっしゃるということですが、予算的には１０件ということで、これから審議に入りますけれども、そうなると、なかなかいっぱい声をかけにくいことも予想されますが、やはり大事なことなので、周知には力を入れていただきたい。そのことを要望いたしまして、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"中塚委員","kind":"意見","question":"私も一言だけ。事業承継支援資金の創設と事業活性化資金および団体事業資金の拡充は、中小企業支援充実につながるので賛成です。そして、転業資金の廃止ですけれども、先ほどからの説明の中で、ほかの融資で補うことが可能だという説明がありましたので、理解しました。よって、今回の条例改正は賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-011"}]},{"id":"topic-02","title":"行政サービスコーナーの民間委託と新規開設","agenda":"行政サービスコーナーの民間委託と新規開設","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"これは本当に狭い部分なので、人もそんなに要らないと思うのですけれども、要するに、３階のサービスコーナーもそういうターゲットに入っているのかどうなのかも含めてお伺いしたい。要は、実際、入力して交付するのは再任用職員がやられるということなのですけれども、これは目黒のサービスコーナーもそういう流れということなのですか。これは確認で、お願いします。","respondent":"提坂戸籍住民課長","answer":"民間委託の導入の検討については、数年以上前から検討を進めていたところです。それから、まず、４月からの大井町サービスコーナーの運営状況を見ながら、本庁舎の窓口についても民間委託ができないかどうか検討してまいりたいと考えています。","voiceIndex":35,"id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"業務的に特殊な業務なわけですから、１つの会社が受けても別にいいのではないかと思うのです。そうすると、１回の研修で全部終わって、ノウハウが身につくわけですから、そうなると、５年後、では、また入札しましょうといったときに、同じ業者が随意契約になってしまうのかというのも危惧されるのですが、どちらにしても同じようなことになると思うのです。その辺はどういうお考えなのか。","respondent":"提坂戸籍住民課長","answer":"今後の事業者選定につきましては、また来年度、簡易型総合評価方式をやっていく中で、今回、約２,９００万円という予算で、指名方式ということで、結果的に４者が指名に応じて、ヒアリングとかを行って、事業者選定を行ったわけです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"いながわ委員","kind":"質問・要望","question":"その社内研修の内容についても、しっかり把握していかないと、どういうサービスを提供するのか、大井町のサービスコーナーと目黒のサービスコーナーで何かちょっとサービスが違うと。大井に行っている人は目黒には行かないと思うのですけれども、やはりそこはしっかり統一性を持った、しっかりと把握できる社内研修、教育をしていただきたいと思いますので、よろしくお願いします。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"重大な問題ですので、幾つか具体的に伺いたいと思いますので、どうぞよろしくお願いします。ここをご説明いただきたいと思います。そこも伺いたいと思います。資料には、２月下旬から人員募集、社内研修、３月には受託者による実働研修と、予算の議決を前に、委員会の報告の前から募集が始まって、実際の導入に向けて既成事実化とは、私は問題ではないかと思うのですけれども、そこも伺いたいと思います。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"経費削減ですけれども、人数的なことも一緒にご説明しますが、従来、サービスコーナーには１０人を超える再任用職員と専門非常勤職員を投入して、その中でローテーションを組んで窓口を行ってまいりました。予算につきましても、当然のことながら、予算特別委員会を経て正式に契約をして、４月１日から執行ということで、こういう予定をしているというご報告をさせていただいたですので、ご理解を賜れればと思います。","voiceIndex":40,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"中身についても伺いますけれども、大井町サービスコーナーの取扱業務というのは、区のホームページで見ると、住民票の写しから、印鑑証明から、戸籍から、身分証明から、全部で７種類と書いてありました。２点目は、人員体制について、現在は三、四人で、今後は区職員が２名で残りが何人かわからないのですけれども、委託業者が何人でやるかも具体的にお任せということなのですか。","respondent":"提坂戸籍住民課長","answer":"具体的な人数につきましては、実際のサービスコーナーの運用状況を業者で把握していただいて、人数を決めていただくという形になります。実際、今４名程度になるという感触は持っております。","voiceIndex":43,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"議決の関係から契約が４月１日になることは私もわかります。会社がここまで動いているわけですから。つまり、伺いたいのは、契約書および仕様書において業務を委託している内容とは一体何なのか、どういう業種なのか、しっかり説明していただきたい。そのことと、接客が得意な方、初心者マークつき、これは、既に区が言っていることと合っているということなのでしょうか。そこを伺いたいと思います。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"業者が決まったのは１月末です。二十何日だったと思います。１月に事業者の選定作業を終えまして、直近の委員会ということで、こちらの区民委員会にご説明させていただいているです。","voiceIndex":45,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"単に工事の契約ではなくて、これは事業の変更ですから、そういう意味では、どうして１月二十何日に決定する前に検討をしていることを議会に報告しなかったのか。ですので、私はするべきだと思うのですけれども、この点はしっかりと伺いたいと思います。どんな仕事を区の職員がやるのか。その仕事の流れでご説明をいただきたいのですけれども、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"報告の時期が今日になったということにつきましては、先ほども申し上げたとおり、執行体制がある程度、固まったところで、具体的なお話ができるということで、今日ご説明させていただいている次第です。","voiceIndex":48,"id":"exchange-018"},{"speaker":"中塚委員","kind":"確認","question":"本人確認を委託業者がやるということで、大丈夫なのかというのを１点伺いたいと思います。本人確認というのはどのように行って交付をしているのか、どういった点に注意をして業務をしているのか、現在の業務も伺いたいと思うのです。具体的に、住民票や戸籍など、申請者に渡すことのできないケースというのが日々の業務の中であると私も伺っております。そこも伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"その辺で確認ができない場合は事業者にお任せしないで、区の職員が引き継いで、本人確認をする形になります。","voiceIndex":50,"id":"exchange-019"},{"speaker":"中塚委員","kind":"確認","question":"本人確認ができない場合は区の職員に相談するということですけれども、本人確認ができないと判断するのはどういう事項なのですか。それはどういうときなのか具体的に伺いたいと思います。本人確認というのはここまでしっかりとやっているというのを４年に１回、本籍地はどこですかとか、住所はどこですかとか、こういう質問を業務でやられているのではないかと。そこを伺いたいのです。","respondent":"提坂戸籍住民課長","answer":"本人確認というのは、事業者にお任せするのは形式的な確認ということなので、運転免許証とかその他の証明書類で確認ができなければ、実質的な確認はできませんので、聞き取り調査とか、その辺は区の職員に引き継いで、区の職員が行う形になります。サービスコーナーの場合です。","voiceIndex":52,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"３階では、どういう質問、どういう聞き取り、そして、それをどういう趣旨でやっているのか。作業手順というのですか。","respondent":"提坂戸籍住民課長","answer":"証明発行事務につきましては、本庁の場合はまだ委託は行っていませんので、区の職員が行うわけですけれども、それこそ運転免許証とかパスポートとか、そういう証明書類をお持ちでない場合は、例えば生年月日をもちろん聞きますけれども、前住所からいつ引っ越してきたとか。","voiceIndex":54,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"形式的に通ってしまったら、どうやって虚偽の申請だったり、渡してはいけないケースだったりを見抜くことができるのですか。つまり、本人確認、そんな大事なことがどうやって担保できるのか、この点をもう少し詳しく伺いたいと思います。実際、交付の事務をする職員が、その書類と、今、目の前の本人が一緒だということをどうやって確認するのですか。そこを２点目に伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"疑義があるような場合は、事業者ではなくて、全て区の職員が行って、さっき事業者から区に相談というお話がありましたけれども、事業者から区に相談ということであれば、区から事業者に指示をしなければいけないので、事業者から相談ではなくて引き継ぎをしていただいた上で。","voiceIndex":56,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"その入り口だけに、そんなに簡単に本人確認を扱っているのか、そこを伺います。区の職員は、本人だと確認せずに交付をするのですか。交付する区の職員は、申請者とどうやって確認するのですか。さっきそれも聞いたけれども、伺いたいと思います。偽装請負について、どういうケースが偽装請負になるのか、ならないのか、全く説明がなかったので、改めて伺いたいと思うのです。品川区はこのことをご存じなのか。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"そういう疑義があった場合、とにかく区の職員に引き継いでいただいて、その後の聴聞とかは区の職員が１００％行って、それで確認ができて、交付の決定とか不決定をして、交付ができない場合はお客様にお引き取りいただいて。ですので、私どもは、今、中塚委員がご質問されているような、そういうところは全てクリアして、法令の範囲内でできることを適切にやりつつ、仕様書でもしっかりと適切にやって、我々戸籍住民課がしっかり管理をして。","voiceIndex":58,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは要望しておきたいと思います。確認なのですけれども、つまり、区は直接、申請者に本人確認はしないということでいいのですね。つまり、もっと言えば、できないということでいいのですね。ここは偽装請負の大事なポイントだと私は思うので、この点を伺いたいと思います。その本人はどういう法律に基づいて、どんな罰則、要するに、どうやって担保をとっているのか、そこを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"委託事業者の対応といたしましても、今回決まった業者の例で申しますと、情報セキュリティマネジメントシステムの国際規格、ＩＳＭＳを平成２２年に取得して、現在、２回目の更新を行っているところです。","voiceIndex":61,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"その典型的な例がひろまち保育園の業務委託の問題なのです。ここを伺いたいと思います。そこを伺いたいと思います。何でそんなことを強調するかというと、要するに、一度漏えいした情報はどこまでも広がっていく、むしろ、ネット社会ですから、もうとめることができない。なので、私はこの民間委託の導入はやめるべきだと思いますけれども、その点、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"それで、万一、個人情報が漏えいした場合、その契約を解除できるかということですけれども、その辺は契約上の約款とか仕様書とかを判断して考えていく問題なので、即座にここで契約が解除できるということは申し上げられません。","voiceIndex":63,"id":"exchange-025"},{"speaker":"本多委員","kind":"質問","question":"それで、事務的に２つ聞きます。条例改正は必要ないのだと思うのですが、そのことと、もう一つは、５２８万円のコスト減というのは、これは計算でいくと、課の中とか部の中だと思うのです。例えば、区の職員定数を削減しない限り、これに伴って区全体の人件費は変わらないのではないのかと思って、ちょっといやらしい質問なのですが、そこだけ事務的に教えてください。","respondent":"提坂戸籍住民課長","answer":"コスト減で、人件費について先ほど申し上げたのは、課の中というお話ですけれども、課の中で定数削減とかを行って、効率的な事務を進め、お客様を待たせないようにしてまいります。","voiceIndex":65,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"私は、地域振興部長が説明してくれた業務内容がよくわかったのですけれども、わかったから、部長、あえて質問しますが、その業務だったら、専門能力活用はあと何があるのですか。そんなスペシャリティな人たちを使わなくてはいけないのですか。投資対効果、これが民間委託です。それほど特殊性を要する業務だったのでしょうか。どういうふうにサービスは向上していくのでしょうか。教えてください。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"先ほど最初の説明のときにも申し上げたのですけれども、民間企業の専門能力活用ということで、自治体での実績だけではなくて、さまざまな国際会議等の通訳、翻訳等のサービス、さまざまな公共サービス。私どもとしては、先行自治体がやっていることですとか、そういうのを研究して、これをきちんと適切にやっていきたいと考えているところです。","voiceIndex":67,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"課が違うので答弁というよりも、でも、今、個人情報が流れたということを伺わないので、出ていないから、ないと思うのです。大井町とか目黒がうまくいって、いいですよとなったら、今度は本庁舎なり、いろいろなところのサービス的業務のところは、もう民間委託にどんどんしていくべきではないかと逆に思うのですけれども、ちょっと将来的なことも思うのですが、その辺についてはいかがですか。","respondent":"堀越地域振興部長","answer":"それについて実施できる方向ということになれば、それは検討していきたいと考えています。","voiceIndex":70,"id":"exchange-028"},{"speaker":"藤原委員","kind":"意見","question":"今、ふと思ってしまったのですけれども、地域活動課長、地域センターに関しても、いずれこういう流れ、本庁の職員がいて、窓口の業務はこういう形でやっていこうと、将来的なことですけれども、なきにしもあらずなのか、今の時点では全く考えていないのか。","respondent":"堀越地域振興部長","answer":"やはり地域のいろいろな町会・自治会の方との部分もありますので、なかなかこの証明発行業務だけを外に切り出すというのも難しい面があると思っています。そこら辺は、もう少し将来的に研究をする必要があると思っているところです。","voiceIndex":72,"id":"exchange-029"},{"speaker":"こんの委員","kind":"質問・要望","question":"今までのやりとりで、民間委託に移行していった流れの考え方は確認させていただきました。今後、やはり区民サービス向上というところでは、そういったところも改善をされて然りだとは思うのですが、その点はどういうふうに向上させるということなのかというのが１点。だからこそ、皆様の中できちんとされている業務をより危機感を持ってしていただきたいと思いますが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"疑義があった場合、中で相談するといっても、ほかのお客様がいらっしゃる場合も多々あるので、なるべく奥のほうで、聞こえない形で、小さな声を出すとか、筆談という形で、個人情報が漏れないような形で対応していきたいと考えています。","voiceIndex":74,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほどの疑義の点ですけれども、ちょっと大変ですが、確かに筆談、小さな声で。その疑義に対して大きな声でされた。今後、それを考えていただきたいところが１点です。窓口は民間業者の方がやる。そこは一定のやりとりを。何か発生した場合は、本当により丁寧に細かく、寄り添う形でということが必要だと思うので、その点、いま一度、お願いしたいのですが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"窓口でそのお話をすると、ほかの方にも当然聞こえてしまいますので、事務室の中の隠れたスペースで、テーブルもありますので、ほかのお客様の耳に入らない形で、プライバシーに配慮しながら対応していきたいと考えております。","voiceIndex":76,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"窓口が混雑してしまったときに、お客様から、早くしろとか、そういうトラブルが発生してしまった場合、窓口のカウンターの方は事業者の方ですね。そうやって暴れてしまって、トラブルが起こった場合は、どう対応するのでしょうか。","respondent":"提坂戸籍住民課長","answer":"一義的に事業者の方がそれに対応できるのであれば、それに越したことはないですけれども、それではとても対応できない場合は、最終的に区の職員が対応をします。お隣に交番もありますので、危険を感じる場合は交番に助けを求めるということも考えなければいけないと考えています。","voiceIndex":78,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"再任用の職員の方が、そこで助けてしまった場合は、偽装請負にならないですか。それは大丈夫なのでしょうか。","respondent":"提坂戸籍住民課長","answer":"それは証明発行業務の本質的な問題とは違うので、それは問題ないと考えます。","voiceIndex":80,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"情報漏えいはもちろんなのですけれども、ＤＶ被害者の方の情報が漏れてしまうことをとても危惧しています。ここでいつ報告されるのかと思って、いつも待っていました。今日、このタイミングで、私も伝聞であるので、今日まで発言することを悩んでいたのですけれども、ＤＶ加害者の方に情報が漏れてしまったというトラブルがあったと思うのですが、どうでしょうか。","respondent":"提坂戸籍住民課長","answer":"具体的にどういうケースなのでしょうか。","voiceIndex":82,"id":"exchange-034"},{"speaker":"田中委員","kind":"意見","question":"２０１５年７月に、本人以外は住民票が取得できないようにＤＶ被害者の方が申請をしました。しかし、２０１６年２月ごろ、本人以外というか、加害者に住民票が交付されてしまい、戸籍住民課から詫び状を送ったという情報が、伝聞ですので正しいかどうかはあれですけれども、そういうトラブルがあると聞いています。","respondent":"提坂戸籍住民課長","answer":"ご指摘の件については把握しておりませんけれども、ＤＶ被害者の方の住民票の請求があった場合、画面を開くと発行制限がかかっていますので、窓口でも、当然、ＤＶの支援措置の担当者が対応しますし、例えばサービスコーナーにそういうケースの方が来られた場合は、当然。","voiceIndex":84,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"把握していないというのは、戸籍住民課から詫び状が送られているので、ちょっとと思うのですけれども、サービスセンターは、とにかく住民票とか個人情報、大事な情報を扱うところではないですか。私たちとしては、報告だとしても、これは絶対に反対をしなければいけないと思っています。ですので、ちょっといやらしいと思ってしまったのです。","respondent":"提坂戸籍住民課長","answer":"目黒のサービスコーナーの件について、確かにちょっとわかりにくい面がありますけれども、今後のスケジュールの中で、簡易型総合評価方式による事業者選定等と明記させていただいていますし。","voiceIndex":86,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"先ほどのトラブルの件なのですけれども、聞き漏らしたので、何て答弁されたのかをもう一度聞きたいということと、あと、中塚委員もおっしゃっていましたけれども、これは報告事項に出されることがスケジュール的にも無理があるというか、いい言い方が出てこないのですけれども、議会が軽視されているのかとも思ってしまいます。いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"決して議会を軽視しているということはございません。１番の民間委託の導入については、先ほど申し上げたのですけれども、方向性が定まったところで、２月にご報告させていただいたということです。","voiceIndex":90,"id":"exchange-037"},{"speaker":"田中委員","kind":"確認","question":"住民票が交付されていないということですか。わかりました。詫び状が送られて、その被害者の方はそういう事態があって、すごく困っていたということはあったので、では、確認していただいて、再発防止を徹底してほしいです。そして、２度目になりますが、このサービスコーナーの委託には反対です。","respondent":"提坂戸籍住民課長","answer":"再発ということではなくて、ＤＶとか、さまざまな発行制限ということは、ご相談というケースはありますけれども、それについて、区民の方の個人情報とか安全を守るために徹底して内部で、周知徹底を図ってまいりたいと考えております。","voiceIndex":92,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"ＤＶの被害者、加害者方がすぐに手続のときにわかるような、そういう対応のところを詳しく教えていただきたいのですけれども、どのような対応をされているのか。","respondent":"提坂戸籍住民課長","answer":"それで、そのまま出さない形になっておりますので、その辺で個人情報の保護が図られていると考えております。","voiceIndex":94,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"その徹底がされていたはずだったのですね。民間の事業者の方が窓口で、そういうＤＶの方の発行をしてはいけないというのが出たときには、対応はきちんとできるのでしょうか。","respondent":"提坂戸籍住民課長","answer":"今後、事業者に委託した場合は、そういう表示が出た場合は、事業者が判断しないで、すぐにこういう画面が出ているということで、区に引き継いでもらう形になります。","voiceIndex":96,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"後ろのほうで、それは再任用職員の方が事業者の画面を目視してチェックをしているということですか。","respondent":"提坂戸籍住民課長","answer":"発行制限がかかっていると、交付の処理ができない形になっているのです。そこでストップしてしまう形なので、絶対に出せない形になっております。機械処理上、そういう形になっていますので、その上で、民間事業者から区に引き継いでいただいて、それで判断します。","voiceIndex":98,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"わかりました。本当に情報が漏れないようにということと、私もずっと気になっているのが、偽装請負がどこから偽装請負になるのかということ。ＤＶに関してのそういうトラブルの発生時に、どこまで事業者の方が対応できるのかということ。そういうことは考えられているのでしょうか。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"今申し上げましたように、画面上に発行制限という赤い表示が出る場合、もうそこで事業者は仕事を行わないで、そこで区に引き継いで、責任者が対応するところです。一般的に、窓口の担当者が並列的に配置をされているわけではございませんで、その上に責任者を配置して、その責任者の指導のもと、実際の業務に当たるということですので、偽装請負にならないような形で。","voiceIndex":100,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"その責任者の方は、そういったトラブルのときの対応もしっかりされているということで大丈夫なのですか。","respondent":"堀越地域振興部長","answer":"責任者が対応いたしますので、それも含めて、委託の業務の範囲内に含めている、そういうことです。","voiceIndex":103,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2774#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":40898,"voices":109}},{"id":"h29-20170227-7","meetingId":"h29-cm02","date":"2017年2月27日","dateIso":"2017-02-27","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第２２号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"第２２号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"確認を１つと質問です。確認としては、平成２７年度に４％分の６,０００万円を取り崩しておりますが、まだ１３億８,０００万円残っていたということで、今回、残りの９６％分を取り崩し、この基金自体がなくなるということで、条例改正ということだったと思うのです。それでいいのかということです。おそらく、ご本人のご希望なのだろうと思うのですけれども、そこを確認させていただきたい。","respondent":"大串福祉計画課長","answer":"ただ、玄関の脇に小さなプレートですけれども、この施設は寄附によりつくられましたということで、その証拠として設置しています。今度６月から開設いたします上大崎特別養護老人ホームにつきましても、同じような形をとらせていただこうと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここに、高齢者福祉への活用のためにということだけが書かれているのですけれども、その中身については、全て区に任せるということで、こんなところにという用途のご希望は、ご寄附をいただいた方からはなかったのかということを確認させていただきたいと思います。私は、この特別養護老人ホームという形で使わせていただくというのは、とてもすばらしい、いいことだなと思っています。","respondent":"大串福祉計画課長","answer":"この多額の寄附金をどこに使うかといったところで、我々としてもいろいろ検討を重ね、また、遺言執行人ともご相談した中で、ちょうどその当時、上大崎特別養護老人ホームの整備計画が出てまいりました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"高齢者福祉への活用のためということでお伺いしたのですけれども、こちらの寄附者は、なぜ高齢者福祉の活用と限定されたのでしょうか。もし寄附者の思いですとか、どうしてというところをお聞きになられている部分がございましたら、ご説明いただけたらと思います。","respondent":"大串福祉計画課長","answer":"そういったところで、ぜひ品川区の高齢者の役に立つようにということで、寄贈をしていただいたところです。あまり詳しいところを申し上げるのは難しいところです。ご容赦いただければと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤副委員長","kind":"質問","question":"資料の４番目の活用理由のところで、高齢者福祉施設の空白地区である大崎地区への介護基盤整備とありますが、大崎地区への空白というのは、これで克服されることになったのか。それと、ほかに空白地区はまだ残っているのか。その辺を関連して伺いたいと思います。","respondent":"大串福祉計画課長","answer":"それ以外の地区というご質問がありましたけれども、区内を１３の生活圏域に分けて、さまざまな形での整備を行ってきております。さまざまな施設の整備を行いながらも、各地区への拠点整備については、今後とも検討、また、実施をしていきたいと考えているところです。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"第２３号議案、品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"第２３号議案、品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば、この総合事業というのは、品川区は平成２７年から始まって、要支援の方の訪問介護と通所介護を総合事業に移行するということで、緩和型Ａという形のサービスに変えたと思うのです。それを規定するということだと思うのですけれども、そういうところまで説明をしていただきたいというのが１点です。なぜ、このように変えるのかということについても、お聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第１号通所事業のことですけれども、介護保険法で定められている第１号通所事業につきましては、通所のＡからＤまで、全部１号の中に決められております。緩和型もその中に含まれるし、住民主体のものも第１号通所事業に含まれているものです。","voiceIndex":23,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、緩和型のサービスＡではなくて、国の介護報酬と同額の現行相当サービスとしているところが、２３区の中では多いと思うのですけれども、そういうものも全部第１号通所事業になるということでいいのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"国が、どうしてこの規定を変えようかという根本的なところを考えたときに、これを後に延ばすことによって、区民にとってマイナスになるのではないかと品川区では考えております。そのため、区では、いち早く対応していたということになります。","voiceIndex":25,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点では、介護報酬そのものが、平成２７年度からかなり下がったという問題がありますし、また介護の現場というのは、本当に劣悪で、介護士のなり手がいない品川区であっても、介護福祉専門学校が定員割れをしてしまうという状況になっているところです。一定所得の方の自己負担が、２割になった。一定所得の方といっても、合計所得１６０万円ですから、そんなに高額というわけではないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-007"},{"speaker":"たけうち委員","kind":"確認","question":"今、鈴木ひろ子委員からありましたけれども、確認です。品川区では、もう既に２年前からやっていらっしゃることについて文言を整理した。国の流れに合わせて、文言を規定したということで、サービスの内容が２年前から変わるのか、また利用料金が変わるのかというところは、変わらないという認識でいいかどうかだけ確認したいのです。","respondent":"永尾高齢者福祉課長","answer":"品川区の場合は、平成２７年４月１日から移行しております。今回の条例の改正によって、内容や利用料についての変更はございません。","voiceIndex":29,"id":"exchange-008"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"実際、現行の介護相当サービスに改正した区というのは、２３区で何区なのかというのを教えていただきたいと思います。あわせて、先ほど、ほかの区に対する品川区の評価など答弁がありましたけれども、なぜ現行の介護相当サービスにしなかったのか。品川区としての考えをもう少し聞きたいと思います。","respondent":"永尾高齢者福祉課長","answer":"これは、地域支援事業なので、各区によって事業者の数も違えば、成り立ちも違いますので、一概に何という評価はできないものです。それで、何区かというところも、実際には、区として数を知って比較する意味もないので、現状の直近の数字は、まだわかっていないところです。","voiceIndex":32,"id":"exchange-009"},{"speaker":"安藤副委員長","kind":"意見","question":"今の答弁ですと、品川区としては、独自にサービスを作って、実態は下がっていないような印象を受ける内容だったのですが、実際に、私も短時間のデイをやっている事業所にも行きましたし、お話も聞いています。やはり品川区の今の答弁のような実態とは言えないという状況を聞きました。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はデイサービスが「いきいき活動支援プログラム」を組み合わせてやれば、介護報酬よりも引き上がるというのが品川区の実態だと思います。そういう点では、今後に向けて、ぜひ実態から事業所がやっていけない状況にならない対策、報酬ということを、ぜひともしていただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。この総合事業そのものが、やはり要支援の方々を、今までの現行サービスから介護報酬を引き下げたり、ボランティアに置きかえるというところで、サービスを大きく減らしていく。低額に抑えていくというところから来ている総合事業の条例かということで、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改正の理由のところに、厚生労働省令が改正されたことに伴いとあります。省令が改正されたのはいつなのかということを教えてください。それから、省令が改正されたら、続いて条例も改正しないといけないという決まりがあるのかということについても、お聞かせいただきたいと思います。そういうことで言えば、２３区、どこでもこの条例が出されているのかについてもお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"この省令につきましては、日にちは手元にないのですけれども、昨年の３月末に改正がされております。実際には、地域密着型通所介護については、昨年４月１日に新設されているものです。","voiceIndex":48,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昨年３月末改正により、４月１日には間に合わなかったということで、来年度からの４月に間に合うようにされたということなのです。それから、こういう施設が区内でどんな状況になっているのかということもお聞かせください。そして、小規模多機能型居宅介護事業所と指定地域密着型介護予防サービスの職員体制がどういうふうになっているのかについてもお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"そういう見込みも現在のところありませんので、すぐに改正はしていないのですが今後、そういう事業所が出てきたときにすぐに対応できるように、今回改正するものです。小規模多機能型居宅介護事業所については、２９人以下の定員になります。","voiceIndex":50,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"小規模多機能型居宅介護事業所にしても、地域密着のデイサービスにしても、看護師１人以上という定めはされていて、その介護職員については、人数などに合わせてということになるのだと思います。その確認をさせていただきたい。厚生労働省がこれを改正した理由というのは、どういう理由で改正したのかということについてもお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"そういう場合、基準としては減らすことは可能になります。厚生労働省令の改正の理由になりますけれども、こちらにつきましては、厚生労働省令で言っている言葉をそのまま使いますと、効率化を図るためという表現になっております。","voiceIndex":52,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。兼務ができるということで、１人減ってしまうことになると、それだけサービスも減ってしまうということもあると思います。そういう点から言うと、健康管理とともに、いつ、どんなことが起こるかわからないという状況もあると思うのです。そういった理由から、同一敷地内にあるということだけで、兼務することができるというのは、サービスの低下になるのではないかということで反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-016"}]},{"id":"topic-03","title":"国保料引下げと過酷な差押え中止を求める請願","agenda":"国保料引下げと過酷な差押え中止を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これを経年的に１０年、２０年単位で見ると、本当にすさまじい値上げだというのがわかります。そういう状況の中での国保料だということが、改めて今確認されたと思うのです。その中で、改めて、国保加入者の品川区の実態がどういう状況になっているのかということについて、もう少し詳しくお聞かせいただけたらと思うのです。２１％になるのかどうかも確認をさせていただきたいと思います。","respondent":"高森国保医療年金課長","answer":"短期間の就労者、短期間労働者の方がお入りになられているということですので、平均課税標準額についても、低いという状況だと認識しております。滞納世帯数です。平成２７年度末の滞納世帯数が、１万３,１３７世帯です。滞納世帯割合につきましては、１７.１３％です。","voiceIndex":68,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平均課税標準額なのですけれども、国保の全国平均では１１２万円というのがいろいろな資料で出ているのです。これは、品川区としても、今、旧ただし書き所得で計算をしているわけですから、そういうところで言えば、品川区としてどれくらいの所得の方なのかというのは計算しようと思えばわかるのではないかと思うのですけれども、そこのところはどうなのでしょうか。","respondent":"高森国保医療年金課長","answer":"これを加入者の８万９,０００人ほどで割りますと、自ずと平均保険料額が出てくるという形になります。課税状況がどうなのかというご質問ですが、これは持ち帰りまして、ご意見として受けとめた上で、今後考えていきたいと思います。","voiceIndex":70,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"請願に挙げられている事例の方ですと、国保料が４８万７,０００円です。所得３００万円の方からこれだけの社会保険料が負担になっている。そういうところで、これも６年前は２３万７,０００円だったのが、一気にこれだけ上がったわけですから、食べ盛りの子どもを抱えて、さらに教育費がかかってくるとなったら、どうやってやりくりできるかというのが実態だと思います。改めて伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"国民健康保険制度には、均等割額の軽減ということで、７割、５割、２割という減額を行う制度があります。平成２７年度で見ますと、おおよそ４７.５％の方がここに該当しているという状況です。","voiceIndex":72,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"構造的な問題で負担が重たいということは、課長も厚生労働省もそのように出していますし、厚生労働省が負担が重たいというのは、国保の特徴として、何度も出しているではないですか。それであれば、高過ぎるということがずっと問題になっているにもかかわらず、なぜ国保料を引き下げるのではなくて値上げをしていくのかということについて、改めて伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"やはり私どもは、国が決めた国民健康保険制度を維持する運営を任されている立場です。さまざまな状況を勘案しながら対応しているというのが現状です。","voiceIndex":74,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところが一切勘案されない算定方式に変えてしまったというのが１点です。それから、高いところをとってきてと言いますけれども、４８万７,０００円というのは、４人世帯であれば平均です。大体１人あたりの平均が１２万円なのですから、１２万円掛ける４人だったら、４８万円になるではないですか。それは、１人あたりの保険料に直すと、幾らになるのか。その金額について伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"２年実施しまして３年目に、やはり保険料が２５％入れるとかなり高くなるという状況と、結果として都道府県化が１年延びまして、５年間で算入していくという状況です。平成２８年度までで６７％を算入しているという状況です。","voiceIndex":78,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高額療養費の税金投入をしていて、それを全部引き揚げるわけです。その総額、１００％は２０１８年度になりますので、２０１８年度の高額療養費が幾らかというのはわかりませんけれども、わかる最新の分で、高額療養費分が総額幾らになるのか。その総額を保険料に置きかえるわけですから、その保険料は１人あたり幾らになるのかという額をお聞きしましたので、お願いします。","respondent":"高森国保医療年金課長","answer":"平成２８年度の高額療養費は、８,９００円ほどと理解しています。","voiceIndex":80,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高額療養費のトータルです。１人あたりではなくて、総額幾らなのか。そして、２０１８年度に、その総額を１００％保険料で賄うことにするわけです。そうすると、それは１人あたり幾らになるのかということをお聞きしています。","respondent":"高森国保医療年金課長","answer":"平成２７年度の資料によりますと、高額療養費は、２７億１,２００万円ほどです。この５０％を算入するという形で、平成２５年度、平成２６年度から進めているものですから、総額を入れるということであれば、１３億５,０００万円というのが総額になるのかなです。","voiceIndex":82,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その１３億５,０００万円を、本当は、今までは保険料負担を減らすために税金で賄っていたものを、全額税金を引き揚げて、今度は保険料の値上げで賄うようになるわけです。だから、この１３億５,０００万円を１人あたり平均で保険料で賄うということになったら、１人あたりの保険料は幾らになるのか。","respondent":"高森国保医療年金課長","answer":"１３億５,０００万円を８万９,０００人ほどで割るということになりますので、１万５,１６８円になります。","voiceIndex":84,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。今、課長からありましたように、今まで保険料の負担が重いから、その保険料を抑えるために区の一般財源として１３億５,０００万円を入れていたものを、今度は全面的に引き揚げて、その分である１万５,１６８円を保険料の値上げで賄いますと。１万５,１６８円が１人あたりの平均ですので４人世帯だったら、６万円ではないですか。とりあえず、一旦終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-025"},{"speaker":"安藤副委員長","kind":"質問","question":"保険料のところです。区としては、上がらないように努力をしなくてはいけないと思うのですが、都道府県化で上がるのですか、下がるのですか。見通しがあればお伺いしたいというのが１点です。それと、滞納の取立てのところです。ご事情がある方は相談してと言うのであれば、こういったやり方は、私は不適切ですので、やり方は改めるべきだと思うのですけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"滞納処分というのは、国税徴収法に基づく法律ですから、滞納処分をした以上は、しっかりした形で対応していくというのは、やむを得ないです。","voiceIndex":88,"id":"exchange-026"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"差押えのところは、いきなりではないということです。それはそうなのですけれども、受け取り方です。受け取られる方が、やはり通知を送っているとはいっても、突然という感覚になるわけです。ですから、その辺に関して、区としてはどのように考えているのか。これで、そうした方が出てしまったらどうするつもりなのか。その辺をもう一度お伺いします。","respondent":"高森国保医療年金課長","answer":"窓口においでになったお客様には、分割納付のご相談時に、もし分割納付のお約束が一方的に守られなくなる場合ですと、預金の差押え、給与の差押え等々が実施となる場合がありますから、ご承知おきくださいということで、ご相談に来ていただいている方には。","voiceIndex":90,"id":"exchange-027"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"なかなか人員もない中で大変だとは思いますけれども、やはり滞納の状況や、いろいろなところから見えてくるその人の生活があると思うのです。本当に深刻だと思えるところは、ぜひ訪問なども含めて、実態をつかむということを行う必要があると思いますし、ぜひそのようにしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"ご相談においでになった方につきましては、生活状況を伺いまして、執行停止等の法的な処分で、請求を一時とめるなり、新しい保険料を納めていただきながら、納付を確認するなり、さまざまな形で対応しておりますので、繰り返しになりますけれども。","voiceIndex":92,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にぎりぎりでどうにもならないような方というのは、品川区に相談に行っても、品川区と信頼関係ができていないということになると、案内を一切開かないという状況に追い込まれている人もいるわけなのです。そこのところを１点お聞かせください。この差押禁止額というのは、今、１人世帯の場合は幾らになるのかについて、お聞かせいただきたいと思います。","respondent":"高森国保医療年金課長","answer":"税金等の法定控除分も該当いたします。扶養がいれば、１人プラスで４万５,０００円というのが、国税徴収法上の差押禁止財産、給与差押えと認識しています。","voiceIndex":95,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この差押禁止額というのは、現在は１０万円プラス４.５万円、プラス生活費の加算額２割という状況になっているのです。これ以下の方、年金もこれに準ずるということになります。そういうところで、これを残すということを品川区はやっていますか。","respondent":"高森国保医療年金課長","answer":"先ほど来、申し上げているとおり、預金につきましては、預金債権です。給与については、当然差押禁止額を反映させた形での差押えを行っているところです。","voiceIndex":97,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"給与そのものを差し押さえるというよりは、ほとんど給与は振込みになっているわけではないですか。以前から課長が預貯金に入った場合というのは、給料なのか、年金なのかがわからない。これは違法だということで、高裁の判決が出て、児童手当相当額の返還を命じられて、鳥取県は２０１４年４月に滞納整理マニュアルの改定をしています。その点についてもお聞かせください。","respondent":"高森国保医療年金課長","answer":"私どもは、児童手当の口座を間髪入れずに押さえたことはございませんし、そういうことは十分配慮しています。","voiceIndex":99,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"児童手当は差し押さえていないということですけれども、これは、児童手当だけではないのです。私は、こういう差押えは、本当にやめていただきたい。このことを改めて伺いたいと思います。そして、平成２７年度の差押えの件数は、８１１件です。平成２６年度よりさらに増えているということに私は驚きなのです。その差押え額が幾らになるかについても、お聞かせください。","respondent":"高森国保医療年金課長","answer":"差押えの金額というのは、平成２７年度は全体で言いますと１億１１５万４,０００円余です。申し上げているとおり、預金については、預金債権という扱いで私どもは対応しております。これについては、判例が出れば、その判例に従う形で考えたいと思います。","voiceIndex":103,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"「その差押え、違法です！」という本も出ています。区としては、その考えはございませんという答弁でしたけれども、私は２３区でぜひともここのところを品川区から求めていただいて、一致して保険料引き下げにしていただきたい。そして、これは１人あたり４,０００円引き下げることができるということですから、少なくとも保険料引き下げに使っていただきたい。改めて求めたいと思いますが、いかがでしょう。","respondent":"高森国保医療年金課長","answer":"ただ、３億７,０００万円の保険者支援のための財政支援という形で、今回お金が入ってきているものにつきましては、既に軽減等々で被保険者の方に法定外繰入金を入れておりますので、そこに充当させていただいたです。ご理解をいただければと思います。","voiceIndex":105,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"品川区が高額療養費分を１３億５,０００万円引き揚げました。さらに、新たな公費として、３億７,０００万円余が入りました。あわせて１７億２,０００万円です。１７億２,０００万円が国保で浮くことになるわけです。そういうことであれば、この１７億２,０００万円というのは、品川区の財政としては、国保から新たに浮くことになるわけです。これは、どう考えるのでしょうか。","respondent":"高森国保医療年金課長","answer":"１７億５,０００万円というお話ですけれども、実はそういうものに使われております。実際、法定外繰入金が平成２７年度は幾らだったのか、平成２６年度は幾らだったのかを見ると、おおよそ２億円弱増加しており、全部、総医療費の中に飲まれているという状況です。","voiceIndex":107,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう中で、やはり国保の引下げに国の政治そのものが、社会保障削減の方向に行っているということが大もとにはありますけれども、その中で地方としてできることは、少なくとも新たな公費は、保険料引下げに使えるわけですから、そういう方向にさせていくべきではないかと思うのです。これは請願審査ですので、ぜひ皆様のご意見もお聞かせいただけたらと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"結論を出す。そして、不採択。そして、そのような中で、それぞれの事情はあるにせよ、この場合で言う、差押えありきではなくて、個別案件ですから、段階的に、あるいは相談、配慮が十分かどうかは別として、個別に対して配慮がなされているのが、これまでの経過だと思います。そして、もう一つ、国保料の値上げではなく、引下げという観点は、誰もが全国的に課題として捉えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問","question":"本日、結論を出していただくことで、お願いします。不採択でお願いします。その上で、できる範囲でいろいろ工夫していただいていると思います。それから、２点目の滞納については、我々もいろいろご相談をいただきます。正直、この請願の２番にあるように、過酷な差押えで困っているというご相談は、私自身は、またうちの会派も、あまり受けていないと考えています。いずれにしても、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"採択でお願いしたいと思います。そのところでは、厚生労働省の通知にありますように、直接実態を把握すべきです。それから、差押えの禁止額は、差し押さえてはならないということで禁止額が決められているわけですから、その差押禁止額まで差し押さえるというやり方は、絶対にやめるべきだということを強く申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-038"},{"speaker":"松永委員","kind":"意見","question":"本日、結論を出す。不採択とします。もちろん、国保料を引き下げてほしいという気持ちはわかりますけれども、国も区も現状を把握して、現状を維持していく対策もとっていて、今後の課題であるのかなと私たちは思っております。差押えされる前に、払えない方に対してきちんと相談を行っていることから、今回の請願に関しては、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-039"}]},{"id":"topic-04","title":"平成２９年陳情第２号、精神障害者も心身障害者医療費助成制度（マル障）の対象とすることについての陳情","agenda":"平成２９年陳情第２号、精神障害者も心身障害者医療費助成制度（マル障）の対象とすることについての陳情","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"請願項目については、私たちもさまざまな方法やルートで、働きかけや要望も含めて、関心が高く、私たちも取組んでまいりました。文面にあるように、東京都への請願等があった中で、報道や私たちの独自のいろいろな調査の中では、東京都でいろいろな動きが見込めると。その辺、もし理事者のほうで最新情報的なものを把握されているものがあったら教えてください。","respondent":"中山障害者福祉課長","answer":"この中で、全会一致で採択されたと聞いております。この後の東京都の動きになりますが、この結果を踏まえ、一定で審議、議決を経て、実際に精神障害の方の追加の詳細については、今後、都で検討することになると思います。","voiceIndex":123,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都議会で２月１７日に全会一致で採択されたということです。その中身について、もう少し教えていただきたい。マル障の場合は、非課税は負担なし、課税は１割で、精神の方の自立支援の場合は、通院だけが１割で、非課税の方は負担なしということになりますと、マル障が精神の方に適用されるということになると、通院だけでなく、通院と同じ負担が入院の場合もできると考えていいでしょうか。","respondent":"中山障害者福祉課長","answer":"そうしたところも、今後、東京都がどうされるかということになると思うのです。基本的にマル障の制度は、自立支援医療から外れる部分になります。精神以外の通院、そして、入院を対象とするかどうかというところになろうかと思います。","voiceIndex":126,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"マル障の方の場合は、全ての医療費が、今の負担になるわけですね。だけど、今の自立支援だと、通院というのは、精神の場合しか使えないけれども、同じような形でのマル障になると、精神のところだけではなくて、全ての病気に対して通院も入院もということにしてほしいという陳情であり、マル障ということで、同じ制度になれば、そのようになると考えていいでしょうか。","respondent":"中山障害者福祉課長","answer":"この陳情には、そこまでは書かれていないのですが、マル障の制度そのものが自立支援医療以外のものということになっております。例えば、精神科の入院は対応にならないと考えていいのかと考えています。","voiceIndex":128,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的な中身はこれからの検討になると思いますが、改めて、精神障害者の保健福祉手帳所持者の方というのは、品川区の福祉にも書かれているのですけれども、平成２７年度交付数が９５４人で、平成２６年度が９０７人で、２年間有効だということなので、これをあわせて１,８６１人が手帳を持っている方と考えていいのでしょうか。","respondent":"中山障害者福祉課長","answer":"おそらく、ここも東京都が今後、１級のみとするのか、１級・２級とするのか、その辺のところは、考えるところかなと考えています。ちなみに、品川区の１級の所持者の方はおよそ１００人、２級の方になりますと、約９００人弱という数字になってあります。","voiceIndex":130,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１級・２級であわせて１,０００人ということですが、今年度申請した人ではなくて、手帳を持っている１級・２級の方と考えていいでしょうか。","respondent":"中山障害者福祉課長","answer":"今申し上げました数字は、平成２６年度と平成２７年度の手帳の認定の数を足したものということで、今現在、何人の方が手帳をお持ちかというところは、なかなか数字が難しいところですが、あわせた数で大体推測できるところと考えております。","voiceIndex":132,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、陳情の２番目のところには、東京都も請願を全会一致で可決されたということなので、ここに踏み出していくのだと思います。これが、もしも実施するとしたら、どこから、どこまでにするかということにもなるのかもしれないのですけれども、財源措置というのが、こういう場合だったらこれくらいと想定されるものがあったら、少しお聞かせいただきたい。","respondent":"中山障害者福祉課長","answer":"それを、仮に今の精神障害者の手帳の所持者の数にあわせますと、１級だけであれば、１,４２０万円程度。これを２級まであわせるとなると、１億３,０００万円を超えた数字となってきます。","voiceIndex":134,"id":"exchange-045"},{"speaker":"安藤副委員長","kind":"質問","question":"今回は、医療費の支援ということなのですけれども、精神障害に苦しむ当事者や家族への支援の必要性というのは、品川区として改めてどのように考えていらっしゃって、またどんな支援に重点を置いていくというのが区の考えなのか、この機会に改めてお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"生活全体を見ながら、ご相談に乗りながら、そうしたことを行うことが大事ではないかと考えております。","voiceIndex":137,"id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問・要望","question":"自民党は、結論を出す。そして、見解なのですが、今の議論の中で採択。理由としましては、これまで私たちも応援してきた立場から、制度の対象に含まれるように、タイトルと同様、請願項目の１にあります。そういった観点から考えております。２番目のところも、品川区の動きにしましても、当然ながら、東京都制度の中で速やかに品川区が対応できるような準備、想定を含めて、議会としても要望してまいりたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-047"},{"speaker":"たけうち委員","kind":"質問","question":"結論を出すということです。態度については、趣旨採択です。内容は同じになりますけれども、１番については、２月１７日の厚生委員会で、全会一致で採択されたということで、私どもの品川選出の都議会議員も紹介議員になっていると伺っております。そういう面では、ぜひこれを機に、東京都でしっかり制度を設計してやっていただくのが大事だなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"採択でお願いしたいと思います。さらに、ここでは１日も早くという意味で、品川区でも財源措置を踏まえたとあるわけですけれども、そういう点で言えば、１,０００人だったとしても、１億４,２００万円ということであれば、できない数ではないなと思いますので、採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-049"},{"speaker":"松永委員","kind":"確認","question":"先ほども、１番に関しては、理事者より説明がありましたように、都議会の２月１７日の厚生委員会で、全会一致で採択されたということで、今後の東京都の動きを確認しながら、今後も私たちも働きかけをしていきたいと考えています。２番に関しても、それまでの間、東京都がどのような制度設計をされているのか。そういうことを見据えながら、私たちも今後も働きかけをしていきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-050"}]},{"id":"topic-05","title":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、厚生委員会にかかわる項目","agenda":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、厚生委員会にかかわる項目","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"飯沼雅子議員の代表質問のところで、社会保障の問題で、放課後等デイサービスについてお聞かせいただきたいと思います。上限の表現は変えるけれども、１０日の日数は変えないということがどういうことなのかをお聞かせいただきたいのが１点です。これがどういうことなのかについてお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3468#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":37130,"voices":153}},{"id":"h29-20170227-8","meetingId":"h29-cm02","date":"2017年2月27日","dateIso":"2017-02-27","committee":"建設委員会","time":"午前１０時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第２６号議案 品川区立区民住宅条例の一部を改正する条例","agenda":"第２６号議案 品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"確認ですけれども、八幡勝壱番館は今年の４月３０日で契約が借上型でなくなるから、今回、第１回定例会で条例改正ということですけれども、もう１つのファミーユ大井は９月３０日で、まだ少し期間があって、第２回定例会というタイミングもあるのですけれども、このタイミングでここを条例改正として前倒しというか、そういう形でやられることに何か特段の意味があるのかどうか。","respondent":"今井住宅課長","answer":"ファミーユ大井につきましては、こちらは借上型５戸ということで、今、管理組合の理事長がその５戸を借り上げていらっしゃいますけれども、今後、ご自分たちの事務所も含めて活用されるということで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"この案件はもう流れの中で十分わかっていましたので、確認です。先ほどアイルサイドテラスとロビン成田が、平成３０年度、平成３１年度とおっしゃったので、正確な日付だけ教えてください。","respondent":"今井住宅課長","answer":"今後の返還の予定ですけれども、平成２９年度につきましては、八幡勝壱番館とファミーユ大井です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"幾度かこの区民住宅については議論されていると思うのですが、この後、もちろんお返ししたときのオーナーの考え方によっての運営になるかと思うのですが、とは言っても、区が関わっていたという部分があるので、そこの確認とか関与の仕方、それともべらぼうに、前回いろいろお話ししたときには、あまり家賃としては大きく変わらないような感じで答弁があったと思うのですけれども、そこの確認等々は。","respondent":"今井住宅課長","answer":"そのような中では、家賃につきましては、特段、私ども、新しい条件の中ですので、そこにオーナーが今度、新しい家賃ということでお決めになった金額をお示しされるというふうに認識しております。区から、ここまでとか、金額等の提示は特にしておりません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"２年前からということで、事前に告知をされているということなのでしょうが、新家賃を決めるに当たって、やはりうまく継続的にされる方と合えばいいのですけれども、なかなか物別れという部分もあるかと思うのですが、そのときはどういう対応をされるのでしょうか。","respondent":"今井住宅課長","answer":"中には契約期間満了に伴って転居をお選びになる方もいらっしゃいますが、それは今までの利用形態と家賃等を考えられて、それぞれの入居者ご自身がご判断されることだと考えていますので、そのことについて、特段。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"意見","question":"そこがちょっと気になっていたところで、速やかにいろいろ提示する条件の中で、継続もしくは転居と進めていければいいかと思っているので、そこを考えると、なかなか言いづらい部分がお互いにあるかと思ったのですが、問題ないようであれば、このまま引き続きよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"今のお話の中で、オーナーの考えで新たな管理会社と契約していくということで、新しい家賃になっていく。その新しい家賃が高過ぎればなかなか住んでいけないという方もいるので、オーナーとしても住んでいてもらうということも大事だと思うのですけれども、新しい家賃が高くなっている、低くなっている、オーナーの考えですけれども、その辺はどのように感じていらっしゃるか伺いたいと思います。","respondent":"今井住宅課長","answer":"あくまでも継続入居、オーナーも借りる方があっての運営ですので、私どもは適切な考え方でオーナーが家賃を設定されているというふうに認識しております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"確かに住み続けてもらわなければ、継続入居ということを前提に対応しているということなのですけれども、やはり少し高くなるということが一番多く出ているところなのでしょうか。それとあと、今回のところでの転居、借上型が終わることで転居される方は、今の時点で把握等はないのでしょうか。","respondent":"今井住宅課長","answer":"八幡勝壱番館につきましては、４月末に実際には新しい契約に移行するということになっておりますけれども、一定、継続入居の意思確認ができておりまして、今のところ継続入居については、１０世帯ほど継続して入居するというふうに認識しております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"の７戸は、やはり賃料が上がるということで退居なのか、そこら辺は把握されているのか伺いたいと思います。","respondent":"今井住宅課長","answer":"ただ、返還届は、退室の２週間前までに区に提出になりますので、実際には４月末ですので、４月の中旬までに返還届を出していただくような手続きになっております。","voiceIndex":18,"id":"exchange-008"}]},{"id":"topic-02","title":"第２７号議案 品川区手数料条例の一部を改正する条例","agenda":"第２７号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この改正内容のところで、1)の「新築等を行う場合」ということで、この「等」というのは、ほかに何があるのか伺いたいと思います。それからあと、３００m2の新築というのは、あるものなのかどうかを伺いたいと思います。","respondent":"鈴木建築課長","answer":"説明が不足しておりまして申し訳ございません。今ご質問いただきました新築等の「等」につきましては、増築についても含むものです。","voiceIndex":32,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかりました。そうしたら、増築した場合に、合計で２,０００m2以上になるときに、この３００m2が手数料に関わって入ってくると。この省エネ法というものですけれども、今回はこれが義務化というか、要は、新築・増築するときの確認のときに、省エネ法に基づいてそうした省エネの設備をすることが求められる、これをつけなければいけないというものになったということなのでしょうか。","respondent":"鈴木建築課長","answer":"これまでは省エネ関係は届出の義務化ですので、適合の義務化はなかったのですけれども、今回、法が施行されることになりますと、記載の２,０００m2以上の非住宅建築物につきましては、その省エネ基準に適合したものにしなければいけない。","voiceIndex":34,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"省エネの設備はどういったものになるのか。種類等、たくさんあると大変かもしれないですけれども、主にどんなものなのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"エネルギー消費量を一定以下に抑える必要があるという基準になりますが、このエネルギー消費量が決まる要因としましては、例えば給湯設備あるいは空調・換気設備、照明、エレベーター、こういった設備関係と、それとあと建物の配置計画ですとか、ひさしを設ける。","voiceIndex":36,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうした一定の省エネ設備が取り組まれることでどれくらいの省エネができているというのは、設置した後は確認はされるのですか。つけたというだけでなくて、その後もきちんとそれが機能しているということは確認されるのでしょうか、伺いたいと思います。","respondent":"鈴木建築課長","answer":"建築確認制度の流れの中では、まず書類審査を行って、建物の完了検査のときに、そういった性能の設備がきちんと取りつけられているかというところまでの完了検査の審査は行います。","voiceIndex":38,"id":"exchange-012"},{"speaker":"西本委員","kind":"確認","question":"平成２９年に義務化ということなのですが、そうすると、今、建築が始まっているところは関係なくて、これから建築確認などをする建物に関してこれが適用されますという認識でよろしいのでしょうか。","respondent":"鈴木建築課長","answer":"今現在は、届出でその内容を審査しております。ただ、届出ですから、中には適合までいっていない建物もあります。４月１日の切り替わりにつきましては、４月１日以降、確認申請が出されるものから対象になっていくということになってあります。","voiceIndex":40,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"そうすると、今ちょうど切替え時期で、ちょっと混乱しそうだというところは何件ぐらいですか。品川区の中は、結構今どんどん建っているところがあると思うのですけれども、全く問題ないのか。それとも、何件かは年度によって、今までしていなかったものが義務になってくるので、義務で出さなければいけなくなってくるとか、そういう案件はどのぐらいあるのですか。全くなければ、ないでいいのですけれども。","respondent":"鈴木建築課長","answer":"２,０００m2以上の非住宅建築物、想定は年間で大体６０件から８０件ぐらいでございまして、ちょうどこの切り替わりの時期に出されるものが、単純に言いますと、例えば１０件とかになってきます。","voiceIndex":42,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"確認","question":"この改正内容で、確認申請の、今、民間業者がほぼ全体を占めているという中で、この４月以降で、区側の建築確認、今までの実績といいますか、民間会社ではなく区としては、今どのぐらい建築確認をやっているのか、申請が出ているのか。今後、４月以降どういうふうな見通しなのか教えてください。","respondent":"鈴木建築課長","answer":"来年の見通しとしましては、対象建築物は先ほどご説明しましたように、９５０件のうち、大体５０件から７０件、８０件程度見込まれていますので、区のほうに出されてくるのが、今のところ４件程度、予算的には見ているという状況です。","voiceIndex":44,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今の話に関連するのですけれども、３００m2以上についてというのは、従来どおり、新築とリフォームをやるということなのですけれども、３００m2以上というと、中小、町場の工務店もその程度の規模も請け負ってやっているところもあると思うのですが、当然、事前に告知とかされておられると思うのですけれども、建築士事務所協会には事前にどういった通達というか通告をしているのか。","respondent":"鈴木建築課長","answer":"今現在も３００m2以上の建築物については届出がなされておりますので、そういった届出がされた場合に、設計事務所等々に、こういった国のパンフレット等を使って、今後の法改正、４月１日以降の流れについてはご説明しています。","voiceIndex":46,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"資料１で、３００m2以上２,０００m2未満は今の現状維持で、２,０００m2以上が今回の改定で手数料が設定される、変わると理解したのですけれども、改定は、業務が今までより増えるということだから上がったと思うのですけれども、特に、申請手数料の(1)工場等のみと(2)非住宅のみ・非住宅に工場部分を含むものというもので、かなり、例えば２,０００m2以上５,０００m2未満を見ても。","respondent":"鈴木建築課長","answer":"ほかの(2)のほうは、先ほどご説明しました、例えば空調だとかエレベーターとかそのほかいろいろなものを含みますので、その結果、審査項目に違いが出て手数料にも違いが出ているというものです。","voiceIndex":48,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、いわゆる非住宅のみ・非住宅に工場部分を含むものというのは、具体的にどんなものがあるのですか。","respondent":"鈴木建築課長","answer":"圧倒的に多いのは、おそらく事務所ビルですとか、物販、商業施設というものになろうかと思います。","voiceIndex":50,"id":"exchange-018"},{"speaker":"筒井委員","kind":"確認","question":"この省エネ基準適合にかなっているかどうかというチェックは、この参考資料の中には、指定確認検査機関ということが書いてあるのですけれども、これは具体的に新たにまたそうした検査機関が立ち上がったのでしょうか。具体的な名称とか、おわかりでしたらお知らせください。","respondent":"鈴木建築課長","answer":"民間では、既に確認申請は区内でも数十検査機関が立ち上がって確認検査業務を行っているわけですけれども、今回この法律に合わせて、国がこの省エネ基準をチェックできる機関を認定というか、設置を認めていくという流れになっておりまして、順次、４月１日以降。","voiceIndex":54,"id":"exchange-019"}]},{"id":"topic-03","title":"第２８号議案 品川区対象区域における特定工場の緑地面積率等に関する条例の一部を改正する条例","agenda":"第２８号議案 品川区対象区域における特定工場の緑地面積率等に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"大もとが変わったからということはわかったのですが、この旧のところの第４条の２第２項、要はこの現行を見ればわかるのでしょうけれども、第１項がなくなったということですね。第２項から繰り上がって第１項という形だと思うのですけれども、なくなった部分はどういうところですか。","respondent":"三ツ橋環境課長","answer":"こちらの市の部分が第２項となっておりましたので、市町村と新しくなるものは第１項の部分に「市町村は、当該市町村の」というふうに権限が移譲されるという部分になりますので、第２項と第１項が合体しまして第１項になったという形です。","voiceIndex":68,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回、町村部にも工場立地法による環境保全の部分、緑地面積率等を決められる権限ができたということなのでしょうか。その辺がちょっとよくわからないのと、あと、この区内でこういう条例の中の特定工場というのはあるのか、あればどこになるのか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"一方、区内ですけれども、４工場ございまして、１つが品川火力発電所、もう１つが大井火力発電所、また３件目、ニコンの大井製作所、４件目が日本ダイヤバルブとなっています。","voiceIndex":70,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、区は変わらずこれを決めていく権限があって、それが町村にも及んだということで、大もとの国の緑地面積率、１００分の２０でしたか、これが都の場合、１００分の１５、それを横引きして品川区も１００分の１５ということだと思うのですけれども、その確認と、それと、区としても決定できる１００分の１５というのは自由に上げることも下げることもできるものなのか伺います。","respondent":"三ツ橋環境課長","answer":"しかしながら、東京都の地域準則を引用しておりまして、区の準則規定をしております。２３区全体といたしましても、東京都の準則規定をそのまま引用しておりますので、緑地面積率を１５％、また環境施設面積率を２０％としております。","voiceIndex":72,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、自由に決められるということなのですけれども、都心部において、なかなかそういった緑地面積をとっていくということは、土地的に広さ的にも難しいのかなという推測はできるのですけれども、やはり環境問題の点からも、少しずつでも上げていくという考えは、今、また今後、あるのかどうか伺いたいと思います。","respondent":"三ツ橋環境課長、溝口公園課長","answer":"緑地面積というのは非常に難しい部分がございまして、区内でどの程度の緑地が、もっと大きな規模、例えば公園が大きくあるとか、他区との比較をしても、今現在のところは、緑地面積率は１５％が妥当だと考えていますので。そういった中でいきますと、実際に工場等を建設する場合には、緑地面積よりもみどりの条例のほうが厳しくなっておりますので、そういった中で、各区、特色を持ちながら緑を増やしてきているというのが実情ですし。","voiceIndex":74,"id":"exchange-023"}]},{"id":"topic-04","title":"平成２９年請願第１号 ライドシェア・白タク合法化反対の意見書採択を求める請願","agenda":"平成２９年請願第１号 ライドシェア・白タク合法化反対の意見書採択を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私はここに書かれているとおりだなというふうに思います。今、課長からご説明があった資料の１番の過疎地等での自家用自動車の活用拡大を実施している自治体はないということなのですけれども、この実施されていない理由は、区としてはどう考えられているのかについて教えてください。","respondent":"中村都市計画課長","answer":"そういった中では、ライドシェアそのものは既存のタクシー事業があった上で成り立っているというふうに現時点では言えると思います。そういった意味からすると、導入には慎重な検討が必要だというふうに考えてあります。","voiceIndex":90,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"請願にもあるように、国交省はライドシェアの導入を拒否している。それで、先ほど課長にも答えていただきました既存の事業者への影響も、タクシー運転手の皆さんからすると、そこも心配の１つだと思うのです。皆さんの意見も伺えたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-025"},{"speaker":"塚本委員","kind":"確認","question":"確認させてください。されているとすれば、どんな感じなのかというところの現状を教えてほしい。","respondent":"中村都市計画課長","answer":"それぞれの自治体で、まだこれの導入に向けて検討するというようなことも、現在、情報はございません。","voiceIndex":93,"id":"exchange-026"},{"speaker":"塚本委員","kind":"確認","question":"今般タクシーの初乗り運賃が改正されて、初乗りは安くなったという改正ですけれども、これに対する業界としての改革というか、新たな取組みということですけれども、これは確認したいのですが、特区内のタクシー業者、全国一律でこういうふうに改正したということなのか。できるなので、任意でやってもいいし、やらなくてもいいしということなのかということを教えてください。","respondent":"中村都市計画課長","answer":"タクシーの料金につきましては、これは国の認可が必要だというふうに聞いております。この料金につきましては、これは、この資料の中で、東京都特別区と武三地区ということで、東京２３区と、それから三鷹市と武蔵野市に限った料金体系です。","voiceIndex":95,"id":"exchange-027"},{"speaker":"塚本委員","kind":"確認","question":"一応、確認なのですけれども、今の特別区に限った話、その域で限っているのですけれども、そこの域内のタクシー業者は、全てこうしなければいけないなのか。タクシー料金としては、初乗り４１０円でもいいし、７３０円でもいいという余地があるのかどうか。","respondent":"中村都市計画課長","answer":"そうすると、例えば別の自治体など、料金体系の違うところからこちらに入ってくるというか、そんなようなときには料金体系が乱れることもあるかと思いますけれども、その辺はこの事業認可のエリアだとか、営業の区域だとか。","voiceIndex":97,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"国家戦略特別区域会議、そうした会議でいろいろ議論の上、認められると思われるのですけれども、この一番最後の資料で、東京のタクシー初乗り短縮運賃の公示についての資料の一番最後で、今後３年以内に事後検証を行うということが書いてありますけれども、例えば過疎地等での自家用自動車の活用拡大についても、項目ごとによって違うかもしれませんけれども。","respondent":"中村都市計画課長","answer":"要は、収入の面でちゃんと利益も適正に上げられているかどうか。そんな側面があると思いますので、この検証を行わなければ、今後また需要と供給だとか、適正な料金設定がどこなのかということが明らかになっていきませんので、事後検証は行われるものと区としては考えております。","voiceIndex":99,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"だから、今回の過疎地等での自家用自動車の活用拡大についても、会議内容で、それは今までの会議の流れからして、今回も事後検証は行われる可能性があるのか、概ねそうなっているのかということも含めてご答弁をお願いします。","respondent":"中村都市計画課長","answer":"この特区法に基づきまして、自家用自動車の活用拡大などが万が一実施されるようなことがあれば、なおさらタクシー料金につきましては、今度、自家用自動車の活用拡大とのバランスを考えたときには、当然。","voiceIndex":101,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"過去の国家戦略特別区域会議、２枚目に何件かあるのですけれども、一定年数が経った場合、適時、検証を行っている例が多いのでしょうか。おわかり次第お知らせください。","respondent":"中村都市計画課長","answer":"ですので、あらかじめ最初から何年後に事後検証を行いますといった認定事業は、私、全体を把握はしておりませんけれども、そういったものは少ないのかなというふうに認識しております。","voiceIndex":103,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"確認","question":"行政側ではなくて、紹介議員側のほうでちょっと確認をしたかったのですけれども、直接紹介議員がいないので、会派としてお答えできるかということの確認なのですけれども、中身ではなくて請願の文言の中で引っかかりがあるなと思ったのは、例えば「まともに税金を払わない多国籍ＩＴ大企業」、この辺は確認をとっているのか。答えられなければしようがないですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"意見","question":"私たち共産党は紹介議員にならせていただいているのですが、これを提出されるということで紹介議員になっていますので、文言等のチェックはしていないです。これは、この請願者が直に思っておられることなのではないかと推測するのですが、私たちとしては何も、文言については配慮していないですし、このまま受けとめたという状況です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"議会の中にかかってくるには、紹介議員の段階でそこら辺はやはりチェックして指導するのが、今までの議会の流れだと思うので。そこら辺は、会派の問題になってしまうので、あえて一言言わせてもらうということで。だからどうのこうのではなくて、意見ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"本日、結論を出すということでいいと思います。中身に関してですが、今、言わせていただいたこの辺の文言的な部分が非常に引っかかりがあって、私どもは紹介議員になりませんでした。決してライドシェアを進めろというつもりはありませんので、言ってしまってよければ、趣旨、意見書までは言えないので、趣旨採択で対応がどうかということで考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-035"},{"speaker":"塚本委員","kind":"質問・要望","question":"既存のタクシー業界では間に合わないようなところが、手の届かない事情が何かあるというようなところということが前提であるということと、そういうことに照らしてみると、東京の特区においてはそういった関係にはないので、あまり意見書を出してそれを防いでいこうというような環境下には東京においてはないだろうということがありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"確認","question":"先ほども言ったように、やはり今のタクシー事業というのは、厳確な基準に基づいて事業許可がおりた中で、安心安全に努めるということで、いろいろ改善策も出しながら頑張っている中ですので、その運営を脅かすようなことがないようにというのと、やはり安心安全というところでは、白タク、またライドシェアが全くもって安全性が確認されていないというところでは、この請願事項に私たちは賛成し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-037"},{"speaker":"木村副委員長","kind":"意見","question":"結論を出す。自民や公明と考え方はほとんど同じなのですけれども、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-038"},{"speaker":"筒井委員","kind":"意見","question":"今回の過疎地等での自家用自動車の活用拡大に限っては、衆参両院の附帯決議も出されていること、およびこの国家戦略特別区域会議でも、それに基づいた慎重な議論がなされるであろうこと、およびおそらく事後検証も行われるということなので、そうした国家戦略特別区域会議等の議論の推移を見守っていきたいということで、直ちに今回、意見書を採択するということは反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-039"},{"speaker":"西本委員","kind":"意見","question":"本日、結論を出してください。この題を見ますと、メリットもあるなということがあるのです。そこはチェック項目が出てくると思うのです。今回の請願者の方々の思いもわかりますが、ただやはり残念だったのは、先ほどもご指摘があったように、部分的なところで私は相容れないところがあります。趣旨採択という形の方向で、ただ、これについては慎重に議論しながら見てまいりたいというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-040"}]},{"id":"topic-05","title":"平成２９年陳情第３号 区民住宅「ファミーユ下神明」の家賃助成に関する陳情","agenda":"平成２９年陳情第３号 区民住宅「ファミーユ下神明」の家賃助成に関する陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"このファミーユ下神明の入居者の平均年齢といいますか、世帯主といいますか家賃を払われている方、世帯主の平均年齢がわかるのかどうか伺いたい。４万３,０００円が急激な上昇ではないと品川区は、今、急激な上昇と考えていないということだったのですけれども、これを急激な上昇と考えないことを伺いたいと思います。","respondent":"今井住宅課長","answer":"ただし、月４万円というのは、やはり金額としては高いというふうには考えておりますけれども、これまで傾斜型家賃の方は３％ずつ上がってきた中で、それをお支払いしていただいていたというような状況もありますので、フラット型、傾斜型。","voiceIndex":125,"id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"そしてまた、今のまま据え置いてくれと言っているわけではないのです。そうすると、このファミーユ下神明をそういうことで取り扱えば、ほかにもそういった同じ区民住宅が出てくるかと思うのですけれども、フラット型使用料のところは、ファミーユ下神明ほかの３棟あるということなので、そこも同じような対応をしていくべきではないかと思うのですけれども、いかがでしょうか。","respondent":"今井住宅課長","answer":"区民住宅のフラット型につきましては、先ほどご説明しましたとおり、ファミーユ西五反田西館、そしてファミーユ西五反田東館の２棟も同じように１５年間の家賃助成の満期を迎えますので、ご指摘のとおり、ここに記載のとおり。","voiceIndex":129,"id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は、今のこの暮らしの中で、先ほども中堅層の暮らしの変化については国の調査等出ているということでしたけれども、区の考えは話されていないので、そこを、中堅層の暮らしぶりを把握しているという状況であれば、これは明らかに急激な値上げと受け取れるのではないかと思うのですけれども、中堅層の今の暮らしと、最大で４万３,０００円の値上がりが急激ではないという区の考えを伺いたいと思います。","respondent":"今井住宅課長","answer":"４万円という金額ですけれども、確かにもし自分がひるがえって４万円掛ける１２ヶ月ですから、年額でしますと４８万円ですので、言ってみれば一月の給与以上の額の上がりになりますので、そのことについては高いものと考えておりますけれども。","voiceIndex":131,"id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"そしてやはり高いという認識がある、考えているということであれば、この思いにぜひ応えるべきではないかと思うのですけれども、中堅層の多くの皆さんの声を、個人だけではないわけです、この住宅に住まわれている皆さんの声を区としてはどのように受けとめていらっしゃるのか、もう一度お伺いします。","respondent":"今井住宅課長","answer":"ただし、月４万円について、今のこの来年の３月の一瞬を見れば、一瞬のみ見れば、やはり月４万円上がるというのは高いというのは確かに認識しておりまして、私としては、そのことにつきましては高いものというふうに認識しています。","voiceIndex":133,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"幾つか現状で確認させていただきたいのですが、先ほどフラット型家賃と傾斜型家賃、この２つのタイプについて、平成１５年に都心から人口流出ということへの対策として、極めて先駆的にこういったフラット型家賃を導入したという答弁だったのですけれども、もうちょっと詳しく、傾斜型ではなくてフラット型を採用した、こういう形をとった区としての狙いというか。","respondent":"今井住宅課長","answer":"区民住宅のフラット型家賃の対応につきましては、実際には傾斜型家賃も進めていたわけですけれども、多くはこの３棟を動かしていく中で、６３０戸ということで大きな住宅をつくるときに、１点目は、住替えも考えながら。","voiceIndex":135,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"こちらのファミーユ下神明自治会長の方からの陳情ということで、私も地元なものですからここには結構出入りをしているところがあって、お住まいの方々においても、家賃の助成が切れるということに関しては、いろいろ不安というか、急激なもの、先ほどもご答弁ありましたけれども、最大４万円を超えるという家賃についての急激な変化については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"それでどうなのだということだと思うのです。それがまず１つ、区がこれからをどう考えているのか。それと、今回の陳情ですが、指定管理者とか、オーナー会とか、いろいろあると思うのですけれども、そういう要望は具体的には同じような要望は出ていたのかということ。その状況に応じて説明をどれだけされていたのでしょうかということをお聞きしたいと思います。","respondent":"今井住宅課長","answer":"この中では、これまでもご質問はいただいておりますけれども、居住支援と言われるような方々、特に高齢者の方々ですね、高齢者の２人暮らしとか高齢者世帯だけのお暮らしの中でなかなか入ることが難しい中では。","voiceIndex":140,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"今、確認をさせていただきましたけれども、住宅政策と福祉的な支援はまた違うだろうと思っているのです。それからあと要望については、直接は聞いていないということもあるので、全くそういう機会を設けていなかったのか、そこら辺がどうなのか。いや、持っていたけれども、そういうご意見が出なかったのか、どちらなのでしょうか。","respondent":"今井住宅課長","answer":"こちらのフラット型家賃の終了に当たって、例えば説明会をしたということはございません。","voiceIndex":142,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"議会は議会でもちろん要望はあると思うのです。ただ、この間、住宅政策についてどう考えていくのですかということを再三聞いたときに、区としての考えはこうですと、住宅政策はこうやっていきますということをおっしゃっていました。それとも、私は今までずっと議論した中で、そういうものはないというふうに見ていたのですが、そこの現状はどうでしょうか。","respondent":"今井住宅課長","answer":"私ども、先ほど申しましたとおり、説明会などは開いていない中で、周知としては、文書等で周知したり、または指定管理者から入居のときに、特に昨年の９月の入居につきましては、もうあと１年を切るわけですから、指定管理者も丁寧に説明をしてまいりました。","voiceIndex":144,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"お気持ちはお察しする。それは皆さん、急に上がったらということで。ただ、区の方針が大分前から示されているのです。ここで陳情が来ましたということで、それは考え直すという政策判断になるのかもしれませんが、私は、今までの区長の考え方をずっと見ていますと、住宅施策、こういうものはもうやめます、増やしませんというか、やめますという方向に私は聞いているのです。それはいかがなのでしょうか。","respondent":"今井住宅課長","answer":"今、区の住宅施策がぶれているかとなりますと、これはぶれてはいません。定住化は進めていく、これだけの住宅、本当にほかの区にはないぐらい区民住宅もつくっておりますので、そういう意味では、定住を進めていくという方針には変わりありません。","voiceIndex":146,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、最後に意見も含めて。確かに傾斜型になっていくと、いずれはもともとの家賃に近い状況になってくるわけですが、それで入らない、空きが増えてくることによって定住化ではなくなるということは、私は違うと思うのです。だからといって、税金をたくさん投与してまで助成をしてというような求めについては、私はちょっと、今の品川区の状況には合わないような気がしてならないということがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"質問","question":"あくまで１５年にするというのですから、これは間違いないと、自民党としてはそう思っています。１５年後に実際に数字が上がるときにどういう苦労があるか、住んでいる人もそうだし、行政側としてフラットの上限にするということが簡単にできるかどうかということを考えていなかったのが、あの頃にいた議員としては大変申し訳ないなと思っているのです。それが１つ。","respondent":"今井住宅課長","answer":"初めに、西品川をつくったときに、助成金なども含めまして建物の建設費が大変高いですので、１５年程度で一定建築費も含めてバランスがよくなるような設定でしたというふうな考え方です。","voiceIndex":149,"id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今の現状はわかるのだけれども、さっき言ったような古い建物を建て替えるときに今後どんな感じかというのが、まだ決まっていないと言えばそれで終わってしまうのだけれども、その辺がどうなのかと。","respondent":"今井住宅課長","answer":"今、建設年数が経っている建設型の区民住宅につきましては、他区の事例でもいろいろありますので、内部リフォームをするのかを含めて、今は国としても長寿命化のほうに考えておりますので、平成２９年度、また国の方針のもとで、公的住宅の長寿命化の答申が出されておりますので。","voiceIndex":151,"id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１点、ファミーユ下神明が今出ていますけれども、今度、西五反田東館と西館を考えたときに、戸数が両方で４９８戸ありますけれども、この助成額のバランスは大体下神明と同じような感じなのか。数字を出していなければ結構ですけれども、大体のバランスだけ教えてもらえれば。","respondent":"今井住宅課長","answer":"現在、ファミーユ西五反田西館につきましては、総戸数９８戸のうち、入居戸数が８７戸でございまして、そのうち補助世帯数は６３世帯です。補助の全体の総額が月額２万６,０００円程度になっております。","voiceIndex":153,"id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ただ、全体的に区の政策の公平性を考えていったときに、ここでそれを十分と切ってしまうのかどうかというのは、やや自民党としては、どう考えるべきかということはまだ検討中です。しかも今、数字を聞いて年間で１億３,０００万円ぐらいの家賃収入が減るということが、さっき言った区全体の公平性からすると果たしてどうなのかということが非常に疑問をまだ感じているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-055"},{"speaker":"塚本委員","kind":"意見","question":"そういう意味では区民住宅として、フラット型家賃を採用している区民住宅の今後ということをよくよく検討していく必要があるという意味では、今、自民党からもありましたけれども、いま一重の議論の時間があったほうが、議会としても議論が深まって１つの結論についての合意みたいなものが成し得るのかなというところもありますので、継続ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":159,"id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今日、結論を出すということで、私たちは採択を主張したいと思います。しかも、それはここだけの話ではないのかなということも思います。私たちも以前、区民住宅に空き家が多い理由を区に尋ねたときに、やはり家賃の関係が大きいのではないかという答弁でした。今、公営住宅がすごく求められている中で、暮らしの中で家賃という負担が本当に住民にとって大きいということも見えてくるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-057"},{"speaker":"木村副委員長","kind":"質問","question":"継続でお願いしたいと思います。行政としても、１５年前よりこのような形でちゃんと通知をしている。だから払えないのだったら出ていけということも、ちょっと考えものだなと思います。そういうふうに考えますと、期間もあと１年ですけれども、あと１年しかないのですけれども、いい方法を考えながらということで、議論をすべきだなと思っています。ですから、会派としては継続で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、ここのファミーユ下神明だけ認めるというわけにはいかないということもありますけれども、一方、急激に区への家賃収入がなくなるという恐れもありますし、急に出ていかざるを得ない住民の方もいらっしゃるということで、他の民間住宅の紹介や生活支援策なども提供していかなければならないだろうという必要性もありますので、ここはそうした不利益も考えて、継続とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、それが不十分だったのですかと私は何回も言いました。だけれども、説明はしておりますというご答弁があったのです。税金の使い方だと思うのです。これは本来であれば、４万円プラスした形なわけですよね。その４万円というのは税金です。だったら、経過措置をつくるとか、それは当然考えなければならないではないですか。退去されてしまう人がいるかもしれない、いいではないですか、退去されたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-060"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"もう状況はわかりました。ただ、これを見てわからなかったのは、雨合羽の裾でナンバープレートが壊れるという、その辺の感覚がわからなかったので、どういう状況で壊れたのか。","respondent":"小林品川区清掃事務所長","answer":"両手にごみを持って、前のボタンはかけていたのですが、雨合羽が清掃用の非常に大きめのものを使っているので、その裾がめくれて折り目のところにナンバーの角が引っかかって、そのまますったので、ナンバーが２センチぐらい端が少し曲がったのです。","voiceIndex":170,"id":"exchange-061"}]},{"id":"topic-07","title":"専決処分の報告について（報告第２号）","agenda":"専決処分の報告について（報告第２号）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この大森駅の歩道橋のエスカレーター、これは品川区の持ち物という認識でいいのですか。これはどのような形で発覚をして、区に連絡が来て、対応されたのでしょうか。","respondent":"多並道路課長","answer":"そのＪＲの職員の方から区のほうに連絡がありまして、直ちに現場に行かせていただいて、当事者の方ともそこでお会いして、エスカレーターを管理している株式会社日立ビルシステムという会社が管理しておりますが、こちらの職員の者も一緒に行って、そこで立ち会って。","voiceIndex":177,"id":"exchange-062"}]},{"id":"topic-08","title":"「旗の台駅周辺地区バリアフリー計画（案）」に関するパブリックコメントの実施","agenda":"「旗の台駅周辺地区バリアフリー計画（案）」に関するパブリックコメントの実施","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"当然、事前調査をしていると思うのですけれども、ここで見る限り、２回の中のまとめた内容で現在の課題を、今回、案にまとめているのかということ。区政協力委員会の方たちにも今、そういったお話はいっていると思うのですけれども、また今後、４月１日からということで、区政協力委員会でまた告知をしていくと思うのですが、その辺の詳細を教えていただきたい。","respondent":"中村都市計画課長","answer":"そういった中で、このまち歩き点検は、それまでに検討してきたものにさらに改善や修正箇所を探すために行ったものでございまして、このまち歩き点検２回で決定したということではなくて、これは念のため皆さんに。","voiceIndex":183,"id":"exchange-063"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"商店街のことなのですけれども、今お話しされたように、点字ブロックもこれから検討されているという中で、ぜひそれは区として、やはりそれぞれ商店会長がいるのですけれども、商店会長からのはみ出し啓発というのはなかなかできないというところがありますので、ぜひその辺は区として、そこのところは商店主の皆様に理解していただけるような対応をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-064"},{"speaker":"塚本委員","kind":"質問","question":"このバリアフリー化の推進が今ある施設というか、今ある状況のもの。新たなものはユニバーサルデザインの考え方だというふうなことが書いてあるのですけれども、このバリアフリー化推進とユニバーサルデザインの違いは、バリアフリーではできないけれども、ユニバーサルデザインだったらここまでできるとか、そういう違いとかはあるのですか。","respondent":"中村都市計画課長","answer":"こういった一般の方々に対する安全確保の取組みが、これもすなわち障害者の方々への安全な通行へつながるという、そういう意味合いで、万人に対しての優しさが、当然、障害者の方も含んだ優しさになる、そんなような考え方なのかなというふうに認識しております。","voiceIndex":186,"id":"exchange-065"},{"speaker":"塚本委員","kind":"確認","question":"要するに、ある施設に対して、新規ではないとユニバーサルの考え方を基本とできないので、ユニバーサル的な対応はできませんとかと、そういう意味合いではないですよねという確認なのですが。","respondent":"中村都市計画課長","answer":"バリアフリーに関する取組みの中には、ただバリアフリーという観点からだけでは、例えばホームドアなどは完全なバリアフリー化を定義しにくかったもの、こういったものも取り組んでいくということで、バリアフリー化も含めたユニバーサルのやり方です。","voiceIndex":188,"id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。ほかにもこういうものは幾つかあったりする。やるという事業計画にまで、いつやるかはともかくとして、一応項目として全部出てくるのかなと思うのですけれども、今はたまたまトイレを例に挙げましたが、そういうものも、現状の○×で×がつき、区民の皆さんからも要望が出ているけれども、この事業計画に載っていないというものがあったりするのはなぜかお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"要望があるけれども、なかなか計画の中に載ってこられないという、今１つの例を出していただきましたけれども、こういったものについては、特定事業という、これから何を取り組んでいくべきかというところが、今これは案の段階ではありますけれども。","voiceIndex":190,"id":"exchange-067"},{"speaker":"塚本委員","kind":"質問・要望","question":"ある程度、特定事業として選別が、現時点で今の案の段階でされているということですね。特定事業として認定される、そして事業計画の中に載ってくるというのは、予算的な目途が立っているとか、特定事業として載せられたというのはどんな条件があったりするのか。もう少し詳しくご説明をいただきたい。","respondent":"中村都市計画課長","answer":"こういったものを１つ１つ相談に乗りながら、アドバイスをしながら解決に向けて進めていくというところでは、時間がかかるかもしれませんけれども、そういったものも進めていきまして。","voiceIndex":192,"id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問","question":"地図とかすごく見づらくて、もうちょっと大きく掲載されるとか、そういうことはあるのかどうか。見やすくしていただけるのかどうかということと、あと視覚障害者の方などには、別途、音声の形で説明を聞ける環境が必要だと思うのですけれども、そういう取組みは何かあるのでしょうか。","respondent":"中村都市計画課長","answer":"詳しい言葉での説明ですけれども、こちらも実際にバリアフリー計画の重点地域内については、地域の皆さんにも説明をしていますが、ただ、幅広く説明ということになりますと、１個１個に対応というのは非常に難しいところもあります。","voiceIndex":194,"id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり障害のある方々、障害者団体の皆さんには、せめて説明会を開くべきではないかと思います。それと、このまち歩き点検調査ですけれども、第１回、第２回とあって、先ほど、随時いろいろと更新させていくということですけれども、こうしたまち歩き点検も、３回、４回というふうに想定されているのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"障害者の方々への説明につきましては、今現在、この計画を策定するに当たりまして、障害者の団体の代表、また高齢者の団体の代表にご出席をいただいているところです。","voiceIndex":196,"id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり団体に入られていない方々の届きづらい声も酌んでいくというところでは、こうした形で計画が案として出ています、声をお寄せくださいということを、パブリックコメントだけでなく説明会をしてそこで意見を吸い上げるという形も必要ではないかと思いますので、そこを要望したいと思います。重点整備地区の要件がどういうふうにあるのかということを伺いたいと思います。","respondent":"中村都市計画課長","answer":"実際に障害者の方がこの要件に当てはまらない、もうちょっと幅を広げれば当てはまっていたところで助かっていたのにというようなことがないように、この辺は柔軟に考えてやっているという認識です。","voiceIndex":198,"id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３３ページのエスコートゾーン、交通安全特定事業の音響信号、エスコートゾーンなのですけれども、このエスコートゾーンの整備が「必要に応じ実施」というふうになっているのですけれども、視覚障害者の方からは音響信号とセットでというのが強い要望だと思うのですけれども、この「必要に応じ」ではなく、セットで進めるというふうなことでしょうか。","respondent":"中村都市計画課長","answer":"それからエスコートゾーンですけれども、今こちらに「必要に応じ実施」と書いてありますけれども、これは公安委員会といたしましても、この重点地区に限らず。","voiceIndex":200,"id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問","question":"まちづくりマスタープランが大もとにあると、私たちはやはり再開発がこういったまちでも進められていってしまうのではないかと思うところなのですけれども、この丸の囲いの色の違い、ちょっと小さくてなかなかここでは見えないですけれども、それでもマスタープランがもとなので、この旗の台というまちでもそういった再開発が進むこともあり得る計画ということになるのでしょうか。","respondent":"中村都市計画課長","answer":"どこでも該当するところはこの重点整備地区内においては取り組んでいくという考え方ですので、まちづくりのマスタープランに則してバリアフリーの取組みは行いますが、ただ。","voiceIndex":202,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"はい、わかりました。そうすると、バリアフリー計画として、すべての人にやさしい便利で安全な交通、歩行環境の整備というところでは、今後も品川区内全域的に広がっていく計画になるのですか。","respondent":"中村都市計画課長","answer":"その辺はまた今後の検討の中で進めていきたいと考えております。","voiceIndex":204,"id":"exchange-074"},{"speaker":"筒井委員","kind":"質問","question":"１９ページと３３ページに、エスコートゾーンのことが触れられているのですけれども、１９ページのエスコートゾーンの説明で「横断歩道の中央部に道路全幅にわたって触覚マーカを敷設した設備」と書いてあるのですけれども、３３ページの写真を見ますと、すごい狭い幅で斜めに設置されているように見えるのですけれども、このエスコートゾーンの設置の仕方はどのように決まっているのですか。","respondent":"中村都市計画課長","answer":"このエスコートゾーンの設置の考え方といたしましては、横断する際、最短距離、つまり可能な限り道路に直交方向です。","voiceIndex":206,"id":"exchange-075"},{"speaker":"筒井委員","kind":"確認","question":"旗の台駅東口には、まだ踏切はございましたか。昭和大学通り。確認をお願いします。","respondent":"中村都市計画課長","answer":"昭和大学に向かっていく側の踏切ということで。あそこはまだ踏切はあって、そちらは点字誘導ブロックの設置の対象ではございませんけれども、踏切はあります。","voiceIndex":208,"id":"exchange-076"},{"speaker":"筒井委員","kind":"質問","question":"その踏切の高架化の予定はないのですか。バリアフリーという観点で言うと、なるべく踏切ではなくて高架化したほうが、障害者の方とかも通りやすいのかなと思ったのですけれども、そうした観点はこういう計画には取り入れられないのかということをお聞きしたいのですけれども。","respondent":"中村都市計画課長","answer":"池上線のほうはいいのですが、高架と言いますと今、大井町線が高架でクロスしている関係上、高架というのは非常に難しいのかなと、物理的にはそんなように。ただ、あと踏切解消のための立体化の計画も今現在はまだないということで、それ以上の情報は特にございません。","voiceIndex":210,"id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"踏切があることによる不便さとかは、まち歩き点検調査ではそういったご意見は出なかったのでしょうか。","respondent":"中村都市計画課長","answer":"踏切そのものが、立体交差することのほうが安全性は高いのかと思いますけれども、特に踏切そのもので危険があるというご指摘はございませんでした。","voiceIndex":212,"id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大井町駅周辺まちづくりに続いて２番目ということなのですけれども、大井町周辺と当然条件も、施設とか道路状況も違うので、その辺の違いは別にして、基本的なところは前と変わっているところはあるのかないのかというところを教えてください。","respondent":"中村都市計画課長","answer":"旗の台駅の東口から昭和大学病院、あそこは歩道と車道が分離されていないようなところに点字ブロックを設けていこうというところで、その辺が、設置の状況の違いはありますが、考え方は同じです。","voiceIndex":214,"id":"exchange-079"},{"speaker":"鈴木（真）委員","kind":"確認","question":"変わっているとまずいなと思ったのと、逆に、これから先進めていって、何か変わってくることがあったときには、もともとあった計画も修正していってもらうということで、その辺を確認のためにお願いします。","respondent":"中村都市計画課長","answer":"委員ご指摘のとおりです。計画などが今後変われば、随時、最善のものに修正をしていく考えです。","voiceIndex":216,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"公共交通機関というところの、どれだけ協働してできるのかというところがあるのですが、区がある程度主導権を握っていろいろできるところがあると思うのですけれども、東急とかいろいろな関係があると、かなりここのエリアでは、一緒に進めていただかないと達成できない状況だと思うのです。そこら辺は今どういう現状になっているでしょうか。","respondent":"中村都市計画課長","answer":"このバリアフリー計画策定におきましても、交通事業者にも参加をしていただいた中で一緒につくっていくというところで、この辺は区としましても、鉄道事業者とともにつくり上げた計画を一緒に実施、実現をしていくというところでは。","voiceIndex":218,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"計画をいろいろ書いてありますけれども、それでは到底及ばないという形になってしまう可能性があるのですが、社会貢献ということから考えると、事業者等々については、以前よりはそれなりに前向きに考えているのかなという期待はあるのですが、その辺はここをまとめるに当たって、どういう感じ、どういうニュアンスというか、その手応えといいますか、それはどういうレベルと考えていればいいのでしょうか。","respondent":"中村都市計画課長","answer":"そういった中で、今、大井町駅におきましては、ホームドアの設置工事をやっておりまして、平成２９年度中の完成を目指して今進めておりますが、こういったものも大井町駅の前回のバリアフリー計画を立てたことに基づいて、鉄道事業者も前向きに考えてもらって。","voiceIndex":220,"id":"exchange-082"},{"speaker":"若林委員長","kind":"質問・要望","question":"私のほうからも確認をさせていただきたいと思うのですけれども、１７ページの、先ほども出ましたけれども、重点整備地区のバリアフリー化の現状というところで、法律、それから都条例の基準に則して判断をして、特に2)の都市公園の中で、整備基準を満たしていないという×の印が５、公園で×が５つあります。","respondent":"溝口公園課長","answer":"都市公園の２公園の整備です。荏原南公園につきましては、来年度、改修工事を予定しておりまして、その中でトイレについてもだれでもトイレを設置していく方向で整備を進めていくように考えているところです。","voiceIndex":222,"id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4194#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":62752,"voices":232}}]);
